INSERT INTO `ai_prep_question_bank` (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how you containerized and deployed your system on Kubernetes using Docker, Helm charts, and Amazon EKS?', '{"key_points": [{"id": "KP1", "description": "Build multi-stage, non-root Docker images with pinned dependencies and push immutable SHA-tagged artifacts to Amazon ECR.", "required": true, "acceptable_evidence": ["Technical keywords: multi-stage Dockerfile, python:3.11-slim, non-root user, pinned requirements, Amazon ECR, immutable SHA tag.", "Explains that the FastAPI inference service (e.g., Fraud Detection or RAG backend) is packaged using a multi-stage Dockerfile that separates C/C++ wheel compilation from a lean runtime image (`python:3.11-slim`), runs as a non-root UID, and pushes images to Amazon ECR tagged with the Git commit SHA.", "Provides valid examples such as baking verified preprocessing pipelines (`StandardScaler`) or fetching pinned MLflow Production model artifacts from S3 at container startup."]}, {"id": "KP2", "description": "Parameterize Kubernetes manifests using Helm charts (`Deployment`, `Service`, `Ingress`, `ConfigMap`, `HPA`) with environment-specific values overrides.", "required": true, "acceptable_evidence": ["Technical keywords: Helm chart, values.yaml, values-staging.yaml, values-prod.yaml, Deployment, Service, ALB Ingress, HPA.", "Explains that Helm templates standardize Kubernetes manifests across services (`api-service`, `celery-worker`, `rag-orchestrator`) while isolating environment differences—replica counts, CPU/memory requests/limits, image tags, and MLflow/Bedrock endpoints—into `values-dev.yaml`, `values-staging.yaml`, and `values-prod.yaml`.", "Provides valid examples such as running `helm lint` and `helm template` validation in CI prior to ArgoCD synchronization."]}, {"id": "KP3", "description": "Configure Kubernetes `startupProbe`, `readinessProbe`, and `livenessProbe` alongside rolling update parameters (`maxSurge`, `maxUnavailable: 0`) for zero-downtime EKS rollouts.", "required": true, "acceptable_evidence": ["Technical keywords: startupProbe, readinessProbe, livenessProbe, GET /health, maxUnavailable: 0, maxSurge, PodDisruptionBudget.", "Explains that ML/RAG pods take several seconds to load model weights (`model.pkl` / BGE reranker) or warm Redis/Milvus connections, requiring a `startupProbe` and `readinessProbe` on `GET /health` so the AWS ALB Ingress never routes live traffic to cold pods.", "Provides valid examples such as setting `RollingUpdate` with `maxUnavailable: 0` and `preStop` lifecycle hooks to drain in-flight inference or SSE streaming requests gracefully."]}, {"id": "KP4", "description": "Enforce least-privilege secret and AWS service access on Amazon EKS using IRSA (IAM Roles for Service Accounts) and External Secrets Operator.", "required": true, "acceptable_evidence": ["Technical keywords: IRSA, OIDC provider, AWS Secrets Manager, External Secrets Operator, KMS, VPC private subnets.", "Explains that EKS pods authenticate to AWS Bedrock, S3 artifact buckets, and DynamoDB via IAM Roles for Service Accounts (IRSA) rather than static AWS keys, while sensitive credentials (DB passwords, API keys) are synced from AWS Secrets Manager via External Secrets Operator.", "Provides valid examples such as isolating EKS worker nodes in private subnets behind an AWS Application Load Balancer (ALB) with TLS termination."]}, {"id": "KP5", "description": "Evaluate the operational trade-offs of Amazon EKS + Helm vs. simpler managed container platforms.", "required": false, "acceptable_evidence": ["Technical keywords: control-plane overhead, Karpenter, KEDA, multi-service orchestration, CNI networking.", "Explains that while EKS + Helm provides fine-grained pod autoscaling (HPA/KEDA), multi-AZ resilience, and heterogeneous CPU/GPU node scheduling, it introduces Kubernetes control-plane upgrade, CNI networking, and Helm chart maintenance overhead compared to AWS App Runner or ECS Fargate."]}], "critical_failures": ["Deploys mutable `:latest` Docker image tags to Amazon EKS without immutable Git SHA or digest pinning, making deterministic rollbacks impossible.", "Omits Kubernetes `readinessProbe` / `startupProbe` checks on model-serving pods, causing the load balancer to route live requests to pods before MLflow model artifacts finish loading into memory.", "Hardcodes AWS credentials or database secrets inside `values.yaml` or the `Dockerfile` instead of using IRSA and AWS Secrets Manager."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'Can you walk through your CI/CD pipeline setup using Docker and Kubernetes for deploying AI applications?', '{"key_points": [{"id": "KP1", "description": "Execute automated Continuous Integration (CI) quality gates on every PR (linting, type checking, unit/contract tests, and SAST/dependency scanning).", "required": true, "acceptable_evidence": ["Technical keywords: GitHub Actions, GitLab CI, ruff, mypy, pytest, Pydantic contract tests, Trivy, pip-audit.", "Explains that every Pull Request triggers automated CI stages running `ruff`/`black` formatting, `mypy` static type checks, `pytest` unit and FastAPI Pydantic schema tests (with mocked LLM/Redis/Milvus dependencies), and vulnerability scans (`pip-audit`, `Trivy`).", "Provides valid examples such as verifying feature transformation logic (`StandardScaler`) and prompt template rendering before any container build proceeds."]}, {"id": "KP2", "description": "Gate AI/ML changes with an automated Evaluation & Model Validation stage against a versioned Golden Dataset (CC/CD).", "required": true, "acceptable_evidence": ["Technical keywords: Golden Dataset, DeepEval, RAGAS, Faithfulness, PR-AUC, FPR @ 90% Recall, regression threshold gate.", "Explains that unlike traditional software CI, AI CI pipelines execute Continuous Calibration (CC/CD): running RAG/Agent changes against a stratified Golden Dataset via DeepEval/RAGAS (requiring e.g. Faithfulness $\\\\ge 0.85$, Answer Relevance $\\\\ge 0.80$) or validating tabular ML models against holdout `PR-AUC` and `FPR @ 90% Recall` thresholds.", "Provides valid examples such as failing the CI build automatically if hallucination rate, p95 latency, or cost-per-query regresses beyond tolerance."]}, {"id": "KP3", "description": "Build immutable Docker images, scan for CVEs, and push SHA-tagged artifacts to Amazon ECR synced with MLflow/DVC model versions.", "required": true, "acceptable_evidence": ["Technical keywords: Docker BuildKit, Amazon ECR, Git commit SHA, MLflow Model Registry, DVC hash, artifact provenance.", "Explains that once tests and evaluation gates pass, CI builds a multi-stage Docker image tagged with `<git-sha>` and linked to the approved MLflow Model Registry version (`models:/fraud_detector/Production`), scans the image with ECR/Trivy, and pushes it to Amazon ECR."]}, {"id": "KP4", "description": "Promote artifacts across `Staging -> Production` namespaces on Amazon EKS via GitOps (ArgoCD + Helm) with automated smoke tests and canary rollback.", "required": true, "acceptable_evidence": ["Technical keywords: ArgoCD, Helm values, Staging namespace, smoke tests, Canary rollout, Argo Rollouts, automated rollback.", "Explains that CD updates the image tag in the GitOps manifest repository (`values-staging.yaml` then `values-prod.yaml`), triggering ArgoCD to sync the Helm release onto Amazon EKS, run post-deploy smoke tests against `/health` and `/predict`, and shift traffic gradually (e.g., 10% -> 50% -> 100%) with automatic rollback on 5xx or latency spikes."]}], "critical_failures": ["Deploys AI/LLM application changes solely after passing Python syntax/unit tests without running an automated evaluation gate (DeepEval/RAGAS or ML validation metrics) against a Golden Dataset.", "Rebuilds a new Docker image from scratch for Production instead of promoting the exact immutable image digest verified in Staging.", "Runs `kubectl apply` manually from developer laptops instead of enforcing declarative GitOps promotion with automated rollback."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'BROAD', 150, 'Describe your MLOps experience, including the use of tools like MLflow and Databricks, and detail your CI/CD process for deploying and serving models using Docker, Kubernetes (EKS), ArgoCD, and Helm charts.', '{"key_points": [{"id": "KP1", "description": "Orchestrate distributed data engineering, feature computation, and scalable model training on Databricks / Spark.", "required": true, "acceptable_evidence": ["Technical keywords: Databricks, Delta Lake, PySpark, feature engineering, point-in-time joins, time-based splits.", "Explains how Databricks and Delta Lake (or S3/Parquet with DVC) process large historical transaction/interaction logs, enforce point-in-time correct feature joins to prevent label leakage, and execute distributed hyperparameter tuning across training clusters."]}, {"id": "KP2", "description": "Track experiments, parameters, metrics, and packaged model artifacts in a centralized MLflow Tracking Server.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking, log_params, log_metrics, log_model, conda.yaml, RDS metadata store, S3 artifact store.", "Explains that every training run logs hyperparameters (e.g., `LogisticRegression` regularization `C`, `XGBoost` `max_depth`/`learning_rate`), dataset DVC/Delta version hashes, evaluation metrics (`PR-AUC`, `FPR @ 90% Recall`, confusion matrices, SHAP plots), and serialized pipeline artifacts (`model.pkl` + `StandardScaler` + `requirements.txt`) to MLflow backed by PostgreSQL/RDS and S3."]}, {"id": "KP3", "description": "Govern model lifecycle promotion (`Staging -> Validation -> Production`) via the MLflow Model Registry and automated validation webhooks.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Model Registry, model lineage, Staging, Validation, Production alias, champion-challenger.", "Explains that candidate models registered in MLflow Model Registry must beat the current Production champion on holdout metrics, subgroup fairness slices, and latency benchmarks (`<100ms` p99) before transitioning to the `Production` stage/alias."]}, {"id": "KP4", "description": "Package the approved MLflow model into a stateless FastAPI Docker container and publish it to Amazon ECR via CI.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, Pydantic, multi-stage Docker build, Amazon ECR, Git SHA tag, model_version tag.", "Explains that promoting a model version triggers CI (GitHub Actions) to package the FastAPI inference service (`POST /predict`, `GET /health`) with the pinned MLflow model URI, run contract and latency tests, and push a versioned Docker image to Amazon ECR."]}, {"id": "KP5", "description": "Deploy and scale the model microservice on Amazon EKS using parameterized Helm charts and declarative ArgoCD GitOps synchronization.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, Helm charts, ArgoCD, Application CRD, self-heal, rolling/canary update, HPA.", "Explains that CI commits the new ECR image digest and MLflow model version into the GitOps Helm `values-prod.yaml` file; ArgoCD detects the Git state drift, syncs the Helm chart to the Amazon EKS cluster with zero-downtime rolling or canary updates, and provides instant `argocd app rollback` if production metrics degrade."]}, {"id": "KP6", "description": "Close the production feedback loop with Prometheus/Grafana telemetry and Evidently AI drift detection triggering retraining.", "required": false, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, Evidently AI, PSI, KS-test, prediction drift, automated retraining trigger.", "Explains that live inference logs capture input features, `prediction`, `probability`, and `model_version`, feeding Prometheus/Grafana for p99 latency/error monitoring and Evidently AI for feature/prediction drift detection."]}], "critical_failures": ["Treats Databricks notebook experimentation and EKS production serving as disconnected silos without MLflow Model Registry lineage or shared preprocessing pipelines (causing training-serving skew).", "Deploys models manually to EKS via `kubectl` without Helm templating or ArgoCD GitOps state reconciliation.", "Logs only scalar accuracy numbers in MLflow without persisting the preprocessing transformer (`StandardScaler`), dataset version hash, and environment dependencies."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How did you approach evaluation and observability trade-offs between development and production environments?', '{"key_points": [{"id": "KP1", "description": "Contrast development-time exhaustive reference-based evaluation against production-time low-latency reference-free monitoring.", "required": true, "acceptable_evidence": ["Technical keywords: ground-truth availability, reference-based vs reference-free evaluation, latency budget, Golden Dataset.", "Explains that in development/staging, ground-truth labels exist and latency is unconstrained, enabling exhaustive evaluation across 100% of a Golden Dataset (full RAGAS/DeepEval suites, multi-judge panels, SHAP analysis, and hyperparameter sweeps).", "Provides valid examples such as contrasting this with production, where ground truth is absent or delayed (e.g., 30–90 day fraud chargebacks or unrated RAG chats) and strict SLA budgets (`<100ms` ML inference or `<1.5s` TTFT) prohibit synchronous heavy LLM judges on the hot path."]}, {"id": "KP2", "description": "Decouple production observability from the synchronous critical path using asynchronous telemetry exporters and stratified trace sampling.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Langfuse async SDK, background queue, stratified sampling, 100% error/fallback capture.", "Explains that while development logs 100% of verbose intermediate prompts, embeddings, and debug payloads synchronously, production uses non-blocking async background queues (OpenTelemetry / Langfuse) to emit trace spans (`trace_id`, token usage, tool latency) with zero impact on user-facing latency.", "Provides valid examples such as running expensive reference-free LLM-as-a-Judge checks (Faithfulness, Answer Relevance) asynchronously on a 5–10% stratified sample of normal production traffic plus 100% of thumbs-down, guardrail-triggered, or high-latency traces."]}, {"id": "KP3", "description": "Enforce PII/PHI redaction and payload governance in production observability logs vs. synthetic/anonymized dev traces.", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, PII/PHI scrubbing, HIPAA/GDPR compliance, payload redaction, RBAC trace access.", "Explains that production observability pipelines must scrub sensitive customer PII/PHI (SSNs, credit card numbers, Medicaid IDs) via Microsoft Presidio before persisting spans to Langfuse or CloudWatch Logs, whereas development uses synthetic or pre-anonymized fixtures."]}, {"id": "KP4", "description": "Close the Continuous Calibration / Continuous Development (CC/CD) loop by promoting production failure traces back into the dev Golden Dataset.", "required": true, "acceptable_evidence": ["Technical keywords: Continuous Calibration, CC/CD, failure harvesting, SME annotation queue, Golden Dataset expansion.", "Explains how production observability feeds back into development: flagged production traces (low faithfulness scores, retrieval misses, drift anomalies, or user escalations) are routed to an SME review queue, labeled with expected ground truth, and added to the CI Golden Dataset to prevent future regressions."]}], "critical_failures": ["Executes synchronous multi-second LLM-as-a-Judge evaluations (e.g., full RAGAS suite) inline on 100% of live production requests, blowing up user latency and token bills.", "Logs unredacted raw customer PII/PHI payloads directly into production observability dashboards without Presidio scrubbing.", "Treats offline dev evaluation and online production monitoring as isolated systems with no pipeline to harvest production failures into the CI Golden Dataset."]}', 1),
('HIRING_MANAGER', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'How did you balance coding, testing, and CI/CD tasks in your workflow?', '{"key_points": [{"id": "KP1", "description": "Integrate testing and CI/CD instrumentation directly into the Definition of Done (shift-left engineering) rather than treating them as post-coding afterthoughts.", "required": true, "acceptable_evidence": ["Technical keywords: shift-left testing, Definition of Done, TDD, Pydantic contracts, pre-commit hooks.", "Explains that feature development, unit/integration testing, and CI/CD pipeline updates are coupled within the same Pull Request so no model, RAG chain, or FastAPI endpoint is merged without automated verification.", "Provides valid examples such as enforcing local `pre-commit` hooks (`ruff`, `mypy`, fast `pytest` unit suite) before code ever leaves the developer workstation."]}, {"id": "KP2", "description": "Structure testing as a multi-tier AI/ML test pyramid to keep developer iteration fast while guaranteeing production reliability.", "required": true, "acceptable_evidence": ["Technical keywords: test pyramid, unit tests, deterministic mocks, integration tests, DeepEval Golden Dataset regression.", "Explains how time is balanced across test tiers: fast deterministic unit tests (`<30s` with mocked Bedrock/Milvus/Redis calls) run on every commit for feature transformers (`StandardScaler`) and tool schemas; integration and container smoke tests run on PRs; and heavier LLM/ML evaluation suites (DeepEval/RAGAS or holdout `PR-AUC` gates) run automatically on merge/staging."]}, {"id": "KP3", "description": "Invest upfront in reusable CI/CD templates, Helm charts, and Makefile automation to eliminate repetitive manual toil.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub Actions reusable workflows, Helm chart templates, ArgoCD GitOps, DVC pipelines, toil reduction.", "Explains that automating Docker builds, ECR pushes, MLflow model registration, and ArgoCD GitOps promotions upfront reduces ongoing CI/CD maintenance to `<10-15%` of sprint capacity, freeing the majority of engineering time (`~60%` coding/modeling, `~25%` test & eval curation) for high-leverage feature and model improvements."]}], "critical_failures": ["Writes application or model code for weeks without tests and throws untested code over the wall to QA or DevOps right before release.", "Runs slow, expensive live LLM calls on every local unit test run instead of separating fast deterministic unit tests from CI evaluation gates.", "Performs manual server deployments via SSH or ad-hoc `kubectl` edits instead of automating repeatable tasks in CI/CD."]}', 1),
('HIRING_MANAGER', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'SPECIFIC', 90, 'How did you collaborate with DevOps teams, and what was your experience with infrastructure tools like Terraform?', '{"key_points": [{"id": "KP1", "description": "Define clear ownership boundaries and shared contracts between AI/ML Engineering and DevOps/Platform teams.", "required": true, "acceptable_evidence": ["Technical keywords: ownership boundary, platform foundation vs workload layer, Dockerfile, Helm values, SLO alignment.", "Explains a collaborative shared-responsibility model: DevOps/Platform engineers own foundational AWS networking (VPCs, private subnets, transit gateways), baseline EKS cluster security, and IAM governance, while AI/ML engineers own service-level `Dockerfile`s, Helm `values.yaml` resource requests, model/RAG application logic, and AI-specific Terraform modules.", "Provides valid examples such as collaborating on GPU/CPU node-group sizing, ALB idle timeouts for SSE token streaming, and IRSA least-privilege policies."]}, {"id": "KP2", "description": "Author and maintain modular Terraform Infrastructure-as-Code (IaC) for AWS AI/ML resources (EKS, ECR, S3, RDS, Redis, IAM/IRSA).", "required": true, "acceptable_evidence": ["Technical keywords: Terraform modules, AWS provider, S3 remote state, DynamoDB state locking, terraform plan, terraform apply.", "Explains hands-on experience writing reusable Terraform modules (`modules/eks`, `modules/s3_artifacts`, `modules/rds_mlflow`, `modules/elasticache_redis`, `modules/iam_irsa`) using remote state in S3 with encryption and DynamoDB state locking to provision reproducible `dev`, `staging`, and `prod` environments."]}, {"id": "KP3", "description": "Enforce PR-driven Terraform review workflows (`terraform fmt`, `validate`, `tflint`, `checkov`, `plan`) and drift prevention.", "required": true, "acceptable_evidence": ["Technical keywords: PR-driven IaC, terraform validate, checkov, tfsec, least-privilege IAM, infrastructure drift.", "Explains that all infrastructure changes go through Git Pull Requests where CI automatically runs `terraform fmt`, `terraform validate`, `checkov`/`tfsec` security scans, and posts the `terraform plan` diff for joint AI + DevOps review before `terraform apply` runs in CI.", "Provides valid examples such as prohibiting manual AWS Console click-ops to prevent unrecorded configuration drift."]}], "critical_failures": ["Provisions production S3 buckets, IAM roles, or EKS node groups manually through the AWS Console (''ClickOps''), causing undocumented drift across environments.", "Stores Terraform `.tfstate` files locally on a laptop or commits unencrypted state files containing secrets to Git instead of using S3 remote state with DynamoDB locking.", "Treats DevOps as an isolated ticket queue without understanding container resource profiles, IAM permissions, or health check contracts."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How did you define and measure correctness and faithfulness in your evaluation pipeline?', '{"key_points": [{"id": "KP1", "description": "Distinguish orthogonally between Faithfulness (groundedness in retrieved context) and Answer Correctness (factual alignment with reference ground truth).", "required": true, "acceptable_evidence": ["Technical keywords: Faithfulness, Groundedness, Answer Correctness, intrinsic vs extrinsic hallucination, retrieved context vs reference answer.", "Explains that Faithfulness measures whether every claim in the generated response is logically entailed strictly by the retrieved context chunks (detecting generation hallucinations even without a ground-truth label), whereas Answer Correctness measures whether the generated response is factually and semantically accurate compared to a curated ground-truth reference answer (capturing both retrieval misses and generation errors).", "Provides valid examples such as showing how an answer can be 100% faithful to an outdated or wrong retrieved chunk while still having low Answer Correctness."]}, {"id": "KP2", "description": "Compute Faithfulness via atomic claim decomposition and NLI / LLM-as-a-Judge entailment verification (`RAGAS` / `DeepEval`).", "required": true, "acceptable_evidence": ["Technical keywords: claim decomposition, atomic statements, NLI entailment, RAGAS Faithfulness, DeepEval, citation verification.", "Explains the two-step calculation of Faithfulness: (1) decomposing the LLM response into $N$ atomic factual claims $C = \\\\{c_1, \\\\dots, c_N\\\\}$, and (2) verifying each claim $c_i$ against the retrieved context passages via an NLI model (`DeBERTa-v3-large`) or deterministic `temperature=0` LLM judge: $\\\\text{Faithfulness} = \\\\frac{|\\\\{c_i \\\\in C : c_i \\\\text{ entailed by context}\\\\}|}{|C|}$.", "Provides valid examples such as verifying that inline `[doc_id]` citations actually support the sentence they are attached to."]}, {"id": "KP3", "description": "Compute Answer Correctness by combining claim-level F1 ($TP, FP, FN$ against the golden reference) with semantic similarity.", "required": true, "acceptable_evidence": ["Technical keywords: claim-level F1, True Positives, False Positives, False Negatives, semantic similarity, Golden Dataset.", "Explains that Answer Correctness compares generated claims against the Golden Dataset reference answer to count True Positives (facts present in both), False Positives (unsupported facts added by the model), and False Negatives (required reference facts omitted), combining factual $F_1 = \\\\frac{2TP}{2TP + FP + FN}$ with weighted embedding cosine similarity."]}, {"id": "KP4", "description": "Decouple retrieval evaluation metrics (`Recall@K`, `Precision@K`, `MRR`, `NDCG@K`) from generation metrics to isolate root causes and drive targeted fixes.", "required": true, "acceptable_evidence": ["Technical keywords: Contextual Recall@K, Contextual Precision@K, MRR, NDCG@K, diagnostic matrix, BGE Cross-Encoder, chunking.", "Explains how pairing Retrieval metrics with Faithfulness and Correctness drives engineering decisions: low Correctness + low `Recall@K` (but high Faithfulness) pinpoints a retrieval/chunking bottleneck (fixed by tuning hybrid BM25 + Milvus HNSW search, chunk size `200-500` tokens, or BGE Cross-Encoder reranking), whereas high `Recall@K` + low Faithfulness pinpoints a generation/prompting flaw (fixed by stricter grounding instructions, `temperature=0`, and output guardrails)."]}], "critical_failures": ["Conflates Faithfulness (alignment with retrieved context) and Answer Correctness (alignment with ground-truth reference) as the exact same metric.", "Relies solely on surface lexical overlap metrics (`BLEU` or `ROUGE`) to measure semantic correctness or hallucination in RAG responses.", "Evaluates only end-to-end answer correctness without measuring retrieval `Recall@K` / `MRR`, making it impossible to tell whether failures stem from bad retrieval or LLM hallucination."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'HARD', 'SPECIFIC', 120, 'How did you deploy your system on AWS using EKS and CI/CD pipelines, and what tools did you use to ensure reproducibility?', '{"key_points": [{"id": "KP1", "description": "Architect the AWS production topology across Amazon EKS, ECR, ALB/API Gateway, S3, RDS, ElastiCache Redis, and AWS Bedrock.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, Amazon ECR, AWS ALB, API Gateway, S3, RDS PostgreSQL, ElastiCache Redis, AWS Bedrock, VPC private subnets.", "Explains the end-to-end AWS architecture from the Study Guides: external traffic enters via CloudFront/ALB or API Gateway (JWT auth) into stateless FastAPI and Celery/LangGraph pods running on Amazon EKS in private VPC subnets, backed by ElastiCache Redis (online feature store / multi-layer semantic cache), RDS PostgreSQL (metadata & MLflow backend), S3 (DVC datasets & model artifacts), and AWS Bedrock / Milvus."]}, {"id": "KP2", "description": "Guarantee four-pillar reproducibility across Code (Git), Data (DVC + S3), Models (MLflow + Seeds), and Environment (Docker Digests + Lockfiles).", "required": true, "acceptable_evidence": ["Technical keywords: Git SHA, DVC .dvc pointer, S3 versioning, MLflow run_id, random seeds, poetry.lock/requirements.txt, Docker SHA256 digest.", "Explains that full ML/AI reproducibility requires locking all four axes: (1) Code via Git commit SHA, (2) Data via DVC `.dvc` MD5/SHA256 pointers backed by versioned S3 buckets, (3) Model & Experiments via MLflow Tracking (`run_id`, hyperparameters, fixed `random_state=42`, serialized `StandardScaler` + model weights), and (4) Runtime Environment via `poetry.lock`/`requirements.txt` inside an immutable Docker image referenced by SHA256 digest in Amazon ECR."]}, {"id": "KP3", "description": "Provision deterministic cloud infrastructure using Terraform IaC and deploy via CI/CD + ArgoCD GitOps.", "required": true, "acceptable_evidence": ["Technical keywords: Terraform, S3 remote state, DynamoDB locking, GitHub Actions, Helm charts, ArgoCD GitOps.", "Explains that AWS infrastructure (VPC, EKS node groups, IAM/IRSA roles, S3, RDS, Redis) is provisioned deterministically via versioned Terraform modules, while GitHub Actions CI and ArgoCD GitOps reconcile Helm releases onto EKS so any environment or historical deployment can be recreated from Git."]}, {"id": "KP4", "description": "Evaluate AWS architectural trade-offs across security (IRSA/KMS), scalability (Karpenter/HPA), latency (`<100ms` / VPC endpoints), and cost.", "required": true, "acceptable_evidence": ["Technical keywords: IRSA, AWS KMS, VPC PrivateLink endpoints, Karpenter, Spot instances, NAT Gateway cost.", "Explains key AWS operational trade-offs: using VPC PrivateLink endpoints for S3, ECR, and Bedrock eliminates public internet traversal, reduces latency, and avoids expensive NAT Gateway data-processing charges; combining On-Demand EKS nodes for stateless critical APIs with Spot instances for batch/training jobs optimizes cost vs. availability."]}], "critical_failures": ["Ensures code versioning in Git but ignores data versioning (DVC/S3), model artifact lineage (MLflow), or Infrastructure-as-Code (Terraform), making past model deployments impossible to reproduce.", "Uses floating dependency ranges (`>=`) and mutable `:latest` Docker tags in production.", "Routes high-volume S3, ECR, and Bedrock traffic from private EKS pods through a public NAT Gateway instead of configuring AWS VPC Endpoints."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'HARD', 'SPECIFIC', 120, 'How did you design and implement an end-to-end ML pipeline, including data versioning, model versioning, and reproducibility?', '{"key_points": [{"id": "KP1", "description": "Version raw and processed datasets alongside code using DVC (`.dvc` content hashes in Git) backed by Amazon S3 and label-maturity windows.", "required": true, "acceptable_evidence": ["Technical keywords: DVC, .dvc pointer files, dvc.lock, S3 remote storage, label-maturity window, point-in-time joins.", "Explains that raw transaction/event snapshots in S3/Parquet are versioned with DVC, storing lightweight `.dvc` metadata and `dvc.lock` MD5/SHA256 checksums in Git so `git checkout <sha> && dvc pull` restores the exact training dataset.", "Provides valid examples from the Fraud Detection Study Guide such as enforcing a label-maturity window (accounting for 30–90 day delayed chargeback confirmations) and strict chronological train/test splits (e.g., Jan–Mar train, Apr test) to prevent future data leakage."]}, {"id": "KP2", "description": "Eliminate training-serving skew via a dual-layer Feature Store (S3/Parquet offline + Redis online) and unified scikit-learn/XGBoost transformation pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: training-serving skew, Feature Store, S3/Parquet offline store, Redis online store, sklearn.pipeline.Pipeline, StandardScaler.", "Explains that feature definitions (rolling velocity counts, amount z-scores) are computed from a single source of truth populating both the S3/Parquet offline training store and low-latency Redis online serving store, and preprocessing transformers (`StandardScaler`, imputers) are fitted strictly on `X_train` and bundled inside a single `sklearn.pipeline.Pipeline`."]}, {"id": "KP3", "description": "Enforce deterministic training and comprehensive experiment logging in a central MLflow Tracking Server.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic seeds, random_state, MLflow Tracking, RDS backend, S3 artifact store, PR-AUC, FPR @ 90% Recall, TreeSHAP.", "Explains that training scripts pin global random seeds (`numpy`, `random`, `xgboost`), handle severe class imbalance (`0.1%` fraud via majority down-sampling and `class_weight=''balanced''`), and log Git commit SHA, DVC data hash, hyperparameters, metrics (`PR-AUC`, `FPR @ 90% Recall`), SHAP feature attributions, and serialized model artifacts to MLflow."]}, {"id": "KP4", "description": "Gate model registration and stage promotion (`Staging -> Validation -> Production`) in the MLflow Model Registry.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Model Registry, model version lineage, automated validation gate, champion-challenger, p99 latency check.", "Explains that a newly trained model version is registered in MLflow Model Registry (`Staging`), automatically evaluated against the current `Production` champion on holdout metrics and `<100ms` inference latency in `Validation`, and promoted to `Production` only when all gates pass."]}, {"id": "KP5", "description": "Deploy the versioned model via Docker/EKS with `model_version` response tagging and close the loop with Evidently AI drift monitoring.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, POST /predict, model_version response field, Evidently AI, PSI, KS-test, instant rollback.", "Explains that the stateless FastAPI service on EKS serves predictions returning `prediction`, `probability`, top-3 SHAP `explanation` features, and `model_version` (enabling exact auditability and 1-command rollback to the prior MLflow Production version), while Evidently AI monitors feature/prediction drift (PSI/KS-test) to trigger retraining."]}], "critical_failures": ["Uses random `train_test_split` on time-series transaction data or fits `StandardScaler` on the full dataset before splitting, causing severe temporal and statistical data leakage.", "Overwrites `model.pkl` or training CSVs in place on S3 without DVC content hashing or MLflow Model Registry versioning.", "Re-implements feature engineering logic separately in Python training scripts and production API code without a shared pipeline or Feature Store, causing training-serving skew."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'How did you design and implement the model quantization pipeline for deploying models on edge devices?', '{"key_points": [{"id": "KP1", "description": "Select the appropriate quantization paradigm (Dynamic PTQ, Static Post-Training Quantization with Calibration, or Quantization-Aware Training) based on accuracy and layer sensitivity.", "required": true, "acceptable_evidence": ["Technical keywords: FP32 to INT8/INT4/FP16, Post-Training Quantization (PTQ), Quantization-Aware Training (QAT), AWQ/GPTQ, fake-quantization nodes.", "Explains that the pipeline starts with FP16 or Static INT8 Post-Training Quantization (PTQ)—mapping FP32 weights and activations via scale $S$ and zero-point $Z$ ($q = \\\\text{round}(r / S) + Z$)—and escalates to Quantization-Aware Training (QAT, inserting fake-quantization nodes with Straight-Through Estimator during fine-tuning) when INT8/INT4 PTQ degrades task accuracy beyond tolerance (e.g., $>1\\\\%$ drop)."]}, {"id": "KP2", "description": "Calibrate activation clipping ranges using a representative unlabeled dataset and apply per-channel weight quantization with mixed precision for sensitive layers.", "required": true, "acceptable_evidence": ["Technical keywords: calibration dataset, KL-divergence / entropy calibration, percentile clipping, per-channel weight quantization, mixed-precision sensitivity analysis.", "Explains that Static INT8 PTQ runs 100–1,000 representative domain samples through the FP32 network to collect activation histograms and compute optimal clipping thresholds (via KL-divergence/entropy or 99.99th percentile to handle activation outliers).", "Provides valid examples such as using symmetric per-channel quantization for conv/linear weights, asymmetric per-tensor quantization for activations, and keeping outlier-sensitive layers (first/last projections, LayerNorm, Softmax) in FP16."]}, {"id": "KP3", "description": "Compile and fuse operators for the target edge hardware runtime (`ONNX Runtime`, `TensorRT`, `TFLite`, `CoreML`, or `llama.cpp` / `GGUF`).", "required": true, "acceptable_evidence": ["Technical keywords: ONNX graph export, operator fusion, Conv+BN+ReLU fusion, NVIDIA TensorRT, TFLite XNNPACK/NNAPI, GGUF.", "Explains that the quantized model is exported via ONNX and compiled into a target-specific engine (e.g., TensorRT for NVIDIA Jetson, TFLite/NNAPI for Android NPUs, CoreML for Apple Neural Engine) performing graph optimizations like `Conv + BatchNorm + ReLU` fusion and constant folding."]}, {"id": "KP4", "description": "Validate the quantized edge artifact via hardware-in-the-loop (HIL) benchmarking across accuracy parity, p99 latency, peak RAM/VRAM, and thermal/power budget.", "required": true, "acceptable_evidence": ["Technical keywords: Hardware-in-the-Loop (HIL), FP32-vs-INT8 accuracy delta, p99 on-device latency, peak RSS memory, thermal throttling.", "Explains that CI gates the quantized artifact by comparing predictions against the FP32 baseline on the Golden Dataset (achieving ~4x footprint reduction and 2x–4x latency speedup) and profiling on physical or emulated target edge hardware to verify memory limits and sustained thermal performance."]}], "critical_failures": ["Applies static INT8 quantization without running a representative calibration dataset to determine activation dynamic ranges, resulting in severe clipping and accuracy collapse.", "Benchmarks quantized model latency only on an x86 cloud server GPU instead of profiling on the actual target edge NPU/ARM processor where unsupported INT8 ops may fall back to slow CPU emulation.", "Quantizes every single layer uniformly to INT4/INT8 without sensitivity analysis or keeping sensitive boundary/normalization layers in FP16."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'How did you ensure consistency between staging and production environments in your deployment pipeline?', '{"key_points": [{"id": "KP1", "description": "Promote the exact same immutable Docker image digest (`sha256:...`) and pinned MLflow model version from Staging to Production (''Build Once, Promote Many'').", "required": true, "acceptable_evidence": ["Technical keywords: Build Once Deploy Many, immutable Docker digest, Amazon ECR, MLflow model version URI, poetry.lock.", "Explains that CI builds the Docker container once per commit with locked dependencies (`poetry.lock`/`requirements.txt`) and pushes it to Amazon ECR; Promoting to Production references the exact same image SHA digest and MLflow model artifact tested in Staging rather than rebuilding from source."]}, {"id": "KP2", "description": "Provision identical cloud topology using shared Terraform modules (`modules/`) and shared Helm chart templates across environments.", "required": true, "acceptable_evidence": ["Technical keywords: Terraform modules, workspaces/tfvars, Helm base templates, values-staging.yaml, values-prod.yaml, ArgoCD.", "Explains that both Staging and Production are provisioned from the exact same parameterized Terraform modules (VPC, EKS version, IAM/IRSA structure, Redis/RDS engines) and deployed using the same Helm chart templates managed by ArgoCD, restricting environment differences strictly to scale parameters (`replicas`, instance sizes, endpoints) in `tfvars` and `values-*.yaml`."]}, {"id": "KP3", "description": "Enforce database schema, vector index, and feature transformation parity via automated migrations and versioned Feature Store schemas.", "required": true, "acceptable_evidence": ["Technical keywords: Flyway / Alembic migrations, Milvus collection schema parity, Feature Store transformation parity, prompt registry.", "Explains that relational schema changes (Flyway/Alembic), Milvus vector index configurations (`HNSW` `M`, `efConstruction`, embedding model dimension), and Feature Store transformation definitions are version-controlled and applied automatically in CI/CD before traffic shifts."]}, {"id": "KP4", "description": "Validate Staging under production-like traffic distributions using shadow/mirrored traffic or anonymized replay before Production cutover.", "required": false, "acceptable_evidence": ["Technical keywords: shadow deployment, traffic mirroring, anonymized production replay, contract verification.", "Explains how replaying anonymized production payloads or mirroring live requests to Staging catches edge-case schema mismatches, rate-limit bottlenecks, and latency regressions before Production promotion."]}], "critical_failures": ["Rebuilds a separate Docker image on the `prod` branch with unpinned dependencies (`pip install` without lockfiles), allowing dependency drift between Staging and Production.", "Maintains hand-edited, diverging Kubernetes YAML files or manual AWS Console configurations for Staging and Production.", "Tests Staging against a different embedding model, tokenizer, or Milvus index metric (`L2` vs `COSINE`) than Production."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'How did you integrate evaluation into your CI/CD pipeline, and how frequently were evaluations executed?', '{"key_points": [{"id": "KP1", "description": "Embed automated evaluation as a blocking CI/CD stage (Continuous Calibration / CC/CD) with hard pass/fail quality gates.", "required": true, "acceptable_evidence": ["Technical keywords: Continuous Calibration (CC/CD), pytest + DeepEval, RAGAS, MLflow evaluation gate, non-zero exit code.", "Explains that evaluation is executed as a programmatic CI job (via GitHub Actions running `deepeval test run` or MLflow validation scripts) that compares candidate metrics against baseline thresholds—e.g., RAG Faithfulness $\\\\ge 0.85$, Contextual Recall $\\\\ge 0.80$, or Fraud `PR-AUC` $\\\\ge$ champion with `FPR @ 90% Recall` within SLA—and fails the pipeline (blocking ArgoCD promotion) if any metric regresses."]}, {"id": "KP2", "description": "Structure evaluation execution across three tiered frequencies to balance CI speed, LLM judge cost, and coverage.", "required": true, "acceptable_evidence": ["Technical keywords: Tier 1 PR smoke eval, Tier 2 merge/staging full Golden Dataset eval, Tier 3 nightly/continuous production eval.", "Explains the multi-frequency execution cadence: (1) **On every Pull Request (per-commit)**: fast deterministic unit tests + a lightweight 30–50 sample critical Golden Dataset subset (`<2–3 min`) to catch immediate regressions; (2) **On Merge to `main` / Pre-Production Promotion**: full stratified Golden Dataset evaluation (200–1,000+ cases across normal, edge, and adversarial red-team prompts) plus latency/load benchmarks; and (3) **Scheduled Nightly / Continuous**: full benchmark sweeps, drift checks (Evidently AI), and async evaluation on 5–10% sampled live production traces."]}, {"id": "KP3", "description": "Trigger path-aware conditional evaluations when prompts, retrieval parameters, chunking logic, or model weights change.", "required": true, "acceptable_evidence": ["Technical keywords: path-based CI triggers, prompt registry diff, DVC/MLflow webhook, artifact caching.", "Explains that CI inspects changed file paths and MLflow webhooks so pure UI/CSS changes skip expensive LLM judge runs, while changes to prompts, LangGraph nodes, chunking/reranking configs, or MLflow `Staging` model versions automatically trigger the full evaluation harness."]}, {"id": "KP4", "description": "Persist evaluation scorecards as CI artifacts and MLflow/Langfuse experiment runs for historical trend tracking.", "required": false, "acceptable_evidence": ["Technical keywords: PR comment scorecard, MLflow log_metrics, Langfuse dataset run, slice-based error analysis.", "Explains that each CI evaluation run posts a markdown comparison table directly onto the GitHub PR (showing delta vs. `main` across each metric and query slice) and logs full per-sample traces to MLflow/Langfuse."]}], "critical_failures": ["Runs a 2,000-sample LLM-as-a-Judge suite on every single developer `git push`, causing 45-minute CI queues and runaway API costs.", "Logs evaluation metrics passively without configuring blocking pass/fail threshold assertions, allowing degraded models or hallucinating prompts to auto-deploy to production.", "Never re-evaluates the deployed system between code releases, missing gradual data/concept drift in production."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you monitor the performance and health of your deployed AI system, and what metrics or tools did you rely on?', '{"key_points": [{"id": "KP1", "description": "Monitor API & infrastructure Golden Signals (p50/p95/p99 latency, RPS throughput, 4xx/5xx error rates, and pod CPU/Memory/GPU saturation) using Prometheus, Grafana, and AWS CloudWatch.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, AWS CloudWatch, p50/p95/p99 latency, RPS, HTTP 4xx/5xx, EKS pod saturation, Redis hit ratio.", "Explains that FastAPI microservices expose `/metrics` scraped by Prometheus and visualized in Grafana (alongside CloudWatch container insights), tracking end-to-end latency (`<100ms` for Fraud inference; TTFT and total generation latency for RAG), request throughput (RPS), HTTP 429/5xx error rates, Redis cache hit ratio, and Milvus query latency."]}, {"id": "KP2", "description": "Trace LLM, RAG, and Agent execution spans, token consumption, and retrieval quality using Langfuse and OpenTelemetry.", "required": true, "acceptable_evidence": ["Technical keywords: Langfuse, OpenTelemetry, trace_id, TTFT, tokens per request, cost per query, retrieval similarity scores, tool call failure rate.", "Explains that for RAG and Agentic workloads (Study Guides), OpenTelemetry and Langfuse capture hierarchical traces across query rewriting, Milvus hybrid retrieval, BGE Cross-Encoder reranking, Bedrock LLM calls, and MCP tool executions, monitoring input/output token cost, guardrail blocks, fallback rates, and sampled online Faithfulness/Relevance scores."]}, {"id": "KP3", "description": "Track statistical Data Drift, Prediction Score Drift, and delayed ground-truth Concept Drift using Evidently AI.", "required": true, "acceptable_evidence": ["Technical keywords: Evidently AI, Population Stability Index (PSI), Kolmogorov-Smirnov (KS) test, prediction score distribution, delayed label join, PR-AUC / FPR @ 90% Recall.", "Explains that for predictive ML models (Fraud Detection Study Guide), live feature inputs and output fraud probabilities are logged and analyzed by Evidently AI using KS-tests and PSI ($>0.2$ critical drift) against the training baseline, using prediction score distribution shifts as an early warning before delayed chargeback labels arrive to compute actual `PR-AUC` and `FPR @ 90% Recall`."]}, {"id": "KP4", "description": "Configure actionable multi-severity alerting (Alertmanager / CloudWatch Alarms -> PagerDuty / Slack) tied to runbooks and automated mitigations.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus Alertmanager, CloudWatch Alarms, PagerDuty, Slack, SLO burn rate, automated rollback / retraining trigger.", "Explains that critical SLO breaches (e.g., 5xx rate $>1\\\\%$, p99 latency $>2\\\\times$ SLA, or Bedrock throttling spikes) page on-call via PagerDuty and can trigger ArgoCD rollback, while sustained feature/concept drift alerts notify the ML team in Slack and trigger automated retraining pipelines."]}], "critical_failures": ["Monitors only infrastructure metrics (CPU/memory and HTTP 200 status codes) while remaining completely blind to silent model failures such as feature drift, hallucinated RAG answers, or all-zero fraud predictions.", "Tracks only average (mean) latency instead of tail percentiles (p95/p99), hiding severe latency spikes affecting power users.", "Waits purely for 90-day delayed ground-truth labels to monitor a production model without tracking real-time feature drift (PSI/KS) and prediction score distributions."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'SPECIFIC', 120, 'How did you support model lifecycle management and deployment using MLflow, FastAPI, and ReactJS?', '{"key_points": [{"id": "KP1", "description": "Manage model artifact lineage, metadata, and stage transitions (`Staging -> Validation -> Production`) in the MLflow Model Registry.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking Server, MLflow Model Registry, mlflow.pyfunc.load_model, Production alias, S3 artifact store, RDS metadata.", "Explains that MLflow serves as the central contract between offline training and online serving: training pipelines log serialized pipelines (`StandardScaler` + `XGBoost`/`LogisticRegression` or prompt/RAG configs), evaluation metrics, and SHAP explainers to S3/RDS, exposing promoted models via a stable URI (`models:/fraud_detector@production`)."]}, {"id": "KP2", "description": "Serve low-latency predictions, explanations, and version metadata through a stateless FastAPI backend (`POST /predict`, `GET /health`, `POST /reload`).", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, lifespan context manager, Pydantic validation, POST /predict, GET /health, model_version, TreeSHAP explanation.", "Explains that the FastAPI service loads the `Production` MLflow model into memory during its `lifespan` startup hook, validates requests via strict Pydantic schemas, enriches inputs from the Redis online Feature Store, and returns a structured JSON response containing `prediction`, `probability`, `explanation` (top 3 SHAP feature drivers), and `model_version` (`run_id`) in `<100ms`."]}, {"id": "KP3", "description": "Build a responsive ReactJS (TypeScript + Tailwind) frontend that renders predictions, confidence indicators, SHAP/citation explanations, and captures human feedback.", "required": true, "acceptable_evidence": ["Technical keywords: ReactJS, TypeScript, real-time status/streaming, SHAP feature attribution UI, citation cards, human-in-the-loop feedback.", "Explains that the ReactJS UI consumes the FastAPI REST/SSE endpoints (via AWS API Gateway with JWT auth) to display risk scores or streamed answers, visualizes top contributing features or source document citations for analyst trust, and provides analyst override / thumbs-up-down controls."]}, {"id": "KP4", "description": "Close the lifecycle loop by routing ReactJS user feedback and override labels back through FastAPI into the evaluation store labeled with `model_version`.", "required": true, "acceptable_evidence": ["Technical keywords: feedback endpoint, POST /feedback, model_version correlation, Golden Dataset curation, drift monitoring.", "Explains that because every FastAPI prediction response includes `model_version` and `trace_id`, analyst overrides or feedback submitted from the ReactJS dashboard are joined deterministically to the exact model version and input features, feeding Evidently AI monitoring and future MLflow retraining datasets."]}], "critical_failures": ["Loads the `.pkl` model file from S3/disk on every single `POST /predict` HTTP request in FastAPI instead of caching the loaded model in memory at startup/lifespan.", "Exposes the MLflow Tracking Server directly to the public ReactJS browser client instead of mediating inference and auth through the FastAPI backend.", "Omits `model_version` and `trace_id` from FastAPI responses, making it impossible to correlate ReactJS user feedback with the specific MLflow model version that produced the prediction."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 90, 'How did you use MLflow in your experimentation workflow, and how did it support model tracking and reproducibility?', '{"key_points": [{"id": "KP1", "description": "Structure experiments and hierarchical runs (`mlflow.start_run`) to systematically log hyperparameters, dataset hashes, and domain evaluation metrics.", "required": true, "acceptable_evidence": ["Technical keywords: mlflow.start_run, nested runs, log_params, log_metrics, PR-AUC, FPR @ 90% Recall, DVC dataset hash, Git commit SHA.", "Explains that during model experimentation (e.g., comparing Phase 1 `LogisticRegression` L2 `C` GridSearch against Phase 2 `XGBoost` `max_depth`, `learning_rate`, `scale_pos_weight` in the Fraud Detection Study Guide), every run logs hyperparameters, the Git commit SHA, the DVC dataset version hash, and imbalanced evaluation metrics (`PR-AUC`, `FPR @ 90% Recall`, F1)."]}, {"id": "KP2", "description": "Log complete model pipelines, input/output signatures (`ModelSignature`), environment lockfiles, and diagnostic plots as S3-backed MLflow artifacts.", "required": true, "acceptable_evidence": ["Technical keywords: mlflow.sklearn.log_model, mlflow.xgboost.log_model, infer_signature, input_example, conda.yaml, requirements.txt, SHAP plots, PR curves.", "Explains that MLflow logs not just raw weights, but the entire fitted preprocessing + estimator pipeline (`StandardScaler` + model), explicit `ModelSignature` (enforcing input feature names and dtypes at inference), pinned `requirements.txt`/`conda.yaml`, and visual artifacts (Precision-Recall curves, confusion matrices, TreeSHAP summary plots) stored in Amazon S3 with metadata in RDS."]}, {"id": "KP3", "description": "Enforce end-to-end reproducibility so any historical run can be reconstructed bit-for-bit across machines.", "required": true, "acceptable_evidence": ["Technical keywords: deterministic random_state, Git SHA tag, dvc.lock hash, mlflow.pyfunc, environment recreation.", "Explains that because each MLflow `run_id` binds together the exact Git commit SHA, DVC data snapshot checksum, fixed random seed (`random_state=42`), hyperparameters, and dependency lockfile, any engineer or CI runner can reproduce the exact training results or reload the exact artifact via `mlflow.pyfunc.load_model(f''runs:/{run_id}/model'')`."]}, {"id": "KP4", "description": "Use the MLflow UI and Model Registry to compare candidate runs side-by-side and govern stage promotion (`Staging -> Validation -> Production`).", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Model Registry, parallel coordinates plot, stage transition, Production alias, rollback.", "Explains how the team compares runs in the MLflow UI / API to select the best model (balancing `PR-AUC` gain vs. `<100ms` latency and SHAP explainability), registers it as a new version in the MLflow Model Registry, and promotes it through `Staging -> Validation -> Production`."]}], "critical_failures": ["Runs MLflow with a local SQLite/filesystem `./mlruns` directory on individual laptops instead of a shared remote MLflow Tracking Server backed by RDS and S3.", "Logs only the trained classifier without including the fitted `StandardScaler` / feature preprocessing pipeline or `ModelSignature`.", "Logs metrics in MLflow without recording the Git commit SHA and DVC dataset version hash, making it impossible to know which code or data slice produced a given run."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How did your team structure support rapid iteration between model development and production deployment?', '{"key_points": [{"id": "KP1", "description": "Embed Data Scientists, ML/AI Engineers, Backend Engineers, and DevOps into a unified cross-functional product squad rather than siloed handoff teams.", "required": true, "acceptable_evidence": ["Technical keywords: embedded cross-functional pod, end-to-end ownership, zero throw-over-the-wall handoff, shared sprint cadence.", "Explains that instead of a waterfall handoff where Data Scientists write standalone notebooks that Backend Engineers must rewrite weeks later, the team operates as an integrated pod sharing ownership of production KPIs (`PR-AUC`, Faithfulness, `<100ms` p99 latency, and business conversion/fraud loss)."]}, {"id": "KP2", "description": "Establish standardized technical interface contracts (MLflow Model Registry, Feature Store, and Pydantic API schemas) that decouple model iteration from service redeployment.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow ModelSignature, Feature Store contract, Pydantic schema, Prompt Registry, decoupled model promotion.", "Explains that standardizing on the MLflow `pyfunc` contract, shared Feature Store transformations (S3/Parquet offline + Redis online), and strict FastAPI Pydantic schemas allows ML engineers to train, validate, and promote a new model version (e.g., Phase 1 Logistic Regression -> Phase 2 XGBoost) without requiring backend or ReactJS frontend code rewrites."]}, {"id": "KP3", "description": "Empower self-service deployment and rapid validation through automated CI/CD evaluation gates (CC/CD), Helm templates, and canary rollouts.", "required": true, "acceptable_evidence": ["Technical keywords: self-service CI/CD, Golden Dataset gate, ArgoCD GitOps, canary deployment, production trace feedback loop.", "Explains that automated CI evaluation gates (DeepEval/RAGAS or holdout ML validation) and paved-road Helm/ArgoCD pipelines let engineers safely take an experiment from local hypothesis to canary production traffic within hours while shared Langfuse/Grafana dashboards provide immediate real-world feedback."]}], "critical_failures": ["Maintains a rigid silo where Data Scientists hand over unversioned Jupyter notebooks for Software Engineers to translate into production code from scratch.", "Requires a full cross-team backend and frontend rewrite every time model hyperparameters, prompts, or feature weights are updated.", "Bypasses automated staging validation and peer review in the name of speed, causing frequent production outages."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'How do A/B testing and rollback strategies work in model deployment pipelines?', '{"key_points": [{"id": "KP1", "description": "Route production traffic deterministically between Champion (`v1`) and Challenger (`v2`) models using sticky hashing and weighted traffic splitting.", "required": true, "acceptable_evidence": ["Technical keywords: Champion-Challenger, deterministic user_id/session_id hashing, Istio VirtualService, AWS ALB weighted target groups, Argo Rollouts.", "Explains that A/B testing splits live traffic (e.g., 90% Champion `v1`, 10% Challenger `v2`) at the ingress/mesh layer or feature-flag router using a deterministic hash (`hash(user_id + experiment_id) % 100`) so multi-turn sessions consistently hit the same model variant without cross-contamination."]}, {"id": "KP2", "description": "Attribute predictions and downstream business outcomes via `model_version` logging and evaluate statistical significance.", "required": true, "acceptable_evidence": ["Technical keywords: model_version tag, trace_id, sample size power analysis, two-sample t-test / Mann-Whitney U / chi-square, guardrail metrics.", "Explains that every inference response and telemetry span logs `model_version` (`run_id`) and `experiment_variant`, enabling side-by-side comparison of primary business/quality metrics (conversion, resolution rate, `PR-AUC`, Faithfulness) alongside guardrail metrics (p99 latency, 5xx errors, token cost) until statistical significance ($p < 0.05$) is reached."]}, {"id": "KP3", "description": "Define automated quantitative rollback triggers on infrastructure SLOs and model behavior anomalies.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus AnalysisRun, automated rollback trigger, 5xx error rate > 1%, p99 latency breach, prediction score collapse.", "Explains that Argo Rollouts / Prometheus continuously query health metrics during progressive rollout and automatically abort and roll back if HTTP 5xx exceeds threshold, p99 latency breaches SLA (`>100ms`), or prediction score distributions shift abnormally (e.g., fraud flagging rate spikes 10x)."]}, {"id": "KP4", "description": "Execute instant zero-downtime rollbacks across traffic routing, ArgoCD GitOps revisions, and MLflow Model Registry aliases.", "required": true, "acceptable_evidence": ["Technical keywords: traffic weight 0%, argocd app rollback, helm rollback, MLflow Production alias pointer, stateless container.", "Explains the three-layer rollback mechanism: (1) immediate ingress traffic shift setting Challenger weight to `0%` in seconds, (2) re-pointing the MLflow `Production` alias to the previous validated `model_version`, and (3) reverting the GitOps Helm release to the prior immutable ECR SHA digest."]}], "critical_failures": ["Routes A/B test traffic randomly per HTTP request (`random.random() < 0.5`) in a stateful or multi-turn application, causing the same user session to flip-flop between Model A and Model B.", "Requires retraining or rebuilding a Docker image from scratch to perform a rollback instead of shifting traffic back to the warm prior revision / MLflow artifact.", "Declares an A/B test winner after a few hours of traffic without checking statistical power or guardrail latency/cost metrics."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'How do you deploy and scale AI models in production, and what infrastructure or tools do you use to handle real-time traffic?', '{"key_points": [{"id": "KP1", "description": "Architect a stateless, horizontally scalable inference tier using FastAPI / Triton / vLLM containers on Amazon EKS behind AWS ALB & API Gateway.", "required": true, "acceptable_evidence": ["Technical keywords: stateless FastAPI pods, Amazon EKS, AWS ALB, API Gateway, Uvicorn/Gunicorn workers, vLLM / Triton.", "Explains that real-time inference decouples compute from state: stateless FastAPI pods (or vLLM/Triton for GPU models) pre-load model weights into memory at startup (`lifespan`) and sit behind AWS API Gateway (rate limiting, JWT auth) and an Application Load Balancer distributing traffic across multi-AZ EKS nodes."]}, {"id": "KP2", "description": "Eliminate synchronous I/O bottlenecks on the hot path using an online Redis Feature Store, multi-layer caching, and connection pooling.", "required": true, "acceptable_evidence": ["Technical keywords: ElastiCache Redis, online Feature Store, sub-5ms lookup, multi-layer semantic/embedding cache, asyncpg / connection pooling.", "Explains that meeting strict real-time SLAs (`<100ms` for Fraud Detection; low TTFT for RAG) requires fetching pre-computed user/transaction features from ElastiCache Redis in `<5ms` (rather than running slow SQL joins on the hot path) and serving frequent RAG queries/embeddings from a multi-layer Redis cache."]}, {"id": "KP3", "description": "Configure two-level Kubernetes autoscaling: Pod-level HPA/KEDA on custom concurrency/queue metrics and Node-level Karpenter.", "required": true, "acceptable_evidence": ["Technical keywords: Kubernetes HPA, KEDA, Prometheus custom metrics, in-flight requests, queue depth, Karpenter node provisioning.", "Explains that pods scale horizontally via HPA/KEDA triggered not just by CPU/GPU utilization but by custom Prometheus metrics (active in-flight requests per pod, p95 latency, or Celery/SQS queue depth), while Karpenter rapidly provisions right-sized EC2 Spot/On-Demand instances when pods enter `Pending` state."]}, {"id": "KP4", "description": "Offload heavy or bursty workloads via Celery/SQS asynchronous workers, dynamic batching, and Bedrock cross-region fallbacks.", "required": false, "acceptable_evidence": ["Technical keywords: Celery workers, Redis/SQS broker, dynamic batching, SSE token streaming, circuit breakers.", "Explains how non-blocking async tasks (document ingestion, audit logging, post-call summarization) are offloaded to Celery workers and how SSE streaming keeps perceived latency low under heavy real-time load."]}], "critical_failures": ["Stores session state or local disk caches inside individual container filesystems, preventing horizontal pod scaling.", "Computes heavy historical SQL aggregations synchronously during a real-time `POST /predict` request instead of reading pre-materialized features from an online Redis Feature Store.", "Scales I/O-bound LLM streaming pods exclusively on CPU utilization, causing connection exhaustion before CPU thresholds ever fire."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 90, 'How do you manage model versioning, reproducibility, and rollback in an MLOps workflow?', '{"key_points": [{"id": "KP1", "description": "Enforce immutable semantic model versioning and stage aliases (`Staging`, `Validation`, `Production`) in the MLflow Model Registry.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Model Registry, immutable version numbers (v1, v2, v3), @production alias, @champion/@challenger, S3 immutable artifacts.", "Explains that every registered model receives a monotonically increasing immutable version ID in the MLflow Model Registry with artifacts stored in versioned S3 paths (`s3://mlflow-artifacts/<exp_id>/<run_id>/artifacts/model`), using mutable aliases (`@production`) to decouple consumer APIs from hardcoded version numbers."]}, {"id": "KP2", "description": "Bind every model version to a complete lineage metadata manifest (Git commit SHA, DVC data hash, hyperparameters, random seed, and dependency lockfile).", "required": true, "acceptable_evidence": ["Technical keywords: Git SHA, DVC dvc.lock hash, random_state=42, fitted StandardScaler pipeline, conda.yaml / poetry.lock, ModelSignature.", "Explains that reproducibility is guaranteed by recording the exact code commit, DVC training/test dataset checksums, deterministic random seeds, and bundled preprocessing pipeline (`StandardScaler` + estimator) inside the MLflow run tags and artifact bundle."]}, {"id": "KP3", "description": "Stamp every production inference log and API response with `model_version` to enable per-version performance auditing.", "required": true, "acceptable_evidence": ["Technical keywords: model_version response field, prediction telemetry, version-sliced drift/error analysis.", "Explains that the FastAPI `/predict` endpoint returns `model_version` in every response and logs it to Prometheus/Evidently AI, allowing engineers to isolate whether a spike in latency or false positives was introduced by a specific model version cutover."]}, {"id": "KP4", "description": "Execute deterministic sub-minute rollbacks by re-pointing the MLflow `@production` alias and reverting the ArgoCD/Helm ECR digest.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow alias re-pointing, ArgoCD rollback, Helm revision rollback, zero-retraining recovery, schema backward compatibility.", "Explains that because prior model versions (`v_{n-1}`), their fitted scalers, and their ECR container images remain immutable and warm, rolling back requires zero retraining—simply reverting the ArgoCD Helm release or MLflow `@production` pointer and verifying feature schema compatibility."]}], "critical_failures": ["Overwrites `model_latest.pkl` in an S3 bucket on each training run, destroying previous model weights and making instant rollback impossible.", "Versions model weights in MLflow but fails to version the corresponding feature preprocessing transformer (`StandardScaler`) or DVC training dataset.", "Changes Feature Store column semantics destructively in place during a model upgrade, breaking `v_{n-1}` when a rollback is attempted."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How do you measure and maintain the accuracy of a generative AI system over time?', '{"key_points": [{"id": "KP1", "description": "Measure multi-dimensional retrieval and generation quality continuously using the RAG Triad (`Faithfulness`, `Answer Relevance`, `Contextual Recall/Precision`) and human-calibrated LLM judges.", "required": true, "acceptable_evidence": ["Technical keywords: DeepEval, RAGAS, Faithfulness, Answer Relevance, Contextual Precision, Recall@K, MRR, Cohen''s Kappa.", "Explains that accuracy in a GenAI/RAG system is measured across both retrieval (`Recall@K`, `MRR`, `NDCG@K`) and generation (`Faithfulness` to context, `Answer Correctness` against Golden references, schema compliance) using `temperature=0` LLM judges calibrated against human SMEs ($\\\\kappa \\\\ge 0.80$)."]}, {"id": "KP2", "description": "Detect production accuracy decay via online trace sampling (Langfuse), embedding query drift, and implicit/explicit user feedback signals.", "required": true, "acceptable_evidence": ["Technical keywords: Langfuse online evaluation, query embedding centroid drift, low retrieval similarity alerts, thumbs-down rate, human escalation rate.", "Explains that in production, accuracy is tracked over time by running async reference-free Faithfulness/Relevance evaluations on a 5–10% sample of live traces (and 100% of low-confidence/fallback turns), monitoring Milvus top-1 cosine similarity drops (indicating knowledge base gaps), and tracking user thumbs-down or call-center agent escalation rates."]}, {"id": "KP3", "description": "Maintain accuracy through automated incremental knowledge base synchronization (S3 -> Docling -> Milvus) and freshness metadata filtering.", "required": true, "acceptable_evidence": ["Technical keywords: S3 event-driven ingestion, Docling parsing, chunk hash deduplication, vector index deprecation, effective_date metadata.", "Explains that GenAI accuracy degrades rapidly when underlying policies, product docs, or Medicaid/clinical guidelines change; an event-driven ingestion pipeline automatically parses updated S3 documents with Docling, re-embeds modified chunks, and purges deprecated vectors in Milvus."]}, {"id": "KP4", "description": "Run a Continuous Calibration / Continuous Development (CC/CD) flywheel that converts production failures into Golden Dataset test cases.", "required": true, "acceptable_evidence": ["Technical keywords: Continuous Calibration (CC/CD), living Golden Dataset, SME annotation queue, prompt/reranker tuning, pinned provider model snapshots.", "Explains that failed or thumbs-down production traces are triaged weekly by SMEs, added to the versioned Golden Dataset, and used in CI to validate prompt refinements, BGE Cross-Encoder reranker thresholds, or migrations between pinned foundation model checkpoints."]}], "critical_failures": ["Evaluates the GenAI system only once before launch on a static 20-question spreadsheet and never monitors production faithfulness or retrieval drift afterward.", "Allows stale or superseded policy documents to accumulate in the vector database alongside new versions without deprecation or `effective_date` filtering.", "Points production calls to unpinned floating model aliases without running CI regression tests when provider checkpoints update."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'How does a model move from development to production in an MLOps pipeline, and what roles are involved at each stage?', '{"key_points": [{"id": "KP1", "description": "Execute Stage 1 (Development & Experimentation): Data Scientists / ML Engineers version data with DVC, train candidate pipelines, and register the best run in MLflow.", "required": true, "acceptable_evidence": ["Technical keywords: Data Scientist, ML Engineer, DVC data snapshot, time-based split, MLflow Tracking, ModelSignature.", "Explains that in Development, Data Scientists and ML Engineers collaborate with Domain SMEs to engineer point-in-time features, train models (`LogisticRegression` / `XGBoost` or RAG chains) on DVC-versioned splits, log metrics (`PR-AUC`, `FPR @ 90% Recall`, SHAP) in MLflow, and register the candidate artifact into the MLflow Model Registry."]}, {"id": "KP2", "description": "Execute Stage 2 (CI & Staging Promotion): ML Engineers / Backend Engineers validate code contracts, containerize with Docker/ECR, and deploy to the EKS Staging namespace.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub Actions CI, pytest, Pydantic contract tests, Amazon ECR, Staging namespace, MLflow Staging stage.", "Explains that opening a PR or transitioning the model to `Staging` triggers automated CI owned by ML & Backend Engineers: running unit tests, feature-pipeline skew checks, building the immutable FastAPI Docker image in ECR, and deploying via ArgoCD/Helm to the EKS `staging` environment."]}, {"id": "KP3", "description": "Execute Stage 3 (Automated Validation & Governance Review): QA / Risk & Product Stakeholders verify champion-challenger benchmarks, fairness, and `<100ms` latency SLAs.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Validation stage, Champion-Challenger evaluation, Golden Dataset gate, p99 load testing, Risk/Compliance sign-off.", "Explains that in `Validation`, automated suites verify that the candidate outperforms the current Production champion on holdout datasets and subgroup slices while load tests (`Locust`/`k6`) confirm `<100ms` p99 latency; for regulated workflows (e.g., Fraud Detection or Healthcare RAG), Product/Compliance stakeholders review SHAP explainability and guardrail reports."]}, {"id": "KP4", "description": "Execute Stage 4 (Production Rollout & Continuous Monitoring): MLOps / SREs oversee progressive canary rollout via ArgoCD and monitor live telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Production alias, ArgoCD GitOps, Canary rollout, SRE/DevOps, Prometheus, Grafana, Evidently AI.", "Explains that promoting the model to `Production` updates the GitOps manifest and triggers a progressive canary rollout on Amazon EKS (monitored by MLOps/SREs via Prometheus, Grafana, and Evidently AI) with automated rollback if live error rates, latency, or prediction drift breach SLOs."]}], "critical_failures": ["Allows a Data Scientist to copy a `.pkl` file directly from a local Jupyter notebook into the production container without automated CI/CD validation, load testing, or lineage tracking.", "Lacks clear role accountability for post-deployment drift monitoring and incident rollback.", "Promotes models to production based solely on offline training accuracy without testing inference latency (`<100ms`), memory footprint, or subgroup fairness in Staging."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'BROAD', 150, 'How would you design an end-to-end MLOps pipeline for training, validating, and deploying models into production?', '{"key_points": [{"id": "KP1", "description": "Architect an automated Data Ingestion, Validation, and Dual-Layer Feature Store layer (DVC + S3/Parquet offline + Redis online).", "required": true, "acceptable_evidence": ["Technical keywords: Great Expectations / Pandera data validation, DVC versioning, S3/Parquet offline store, Redis online store, point-in-time joins, label-maturity window.", "Explains that the pipeline begins with automated schema, null, and distribution checks on incoming S3 data, applies a label-maturity window (e.g., waiting for confirmed fraud chargebacks), versions immutable snapshots with DVC, and materializes consistent features to both the offline training store (S3/Parquet) and online serving store (Redis)."]}, {"id": "KP2", "description": "Orchestrate reproducible Training & Hyperparameter Tuning with full lineage logging to an MLflow Tracking Server.", "required": true, "acceptable_evidence": ["Technical keywords: chronological train/test split, class imbalance handling, sklearn.pipeline.Pipeline, MLflow Tracking, RDS + S3 backend, TreeSHAP.", "Explains that orchestrated training jobs (Airflow / GitHub Actions / SageMaker Pipelines) run chronological splits, handle class imbalance (`class_weight=''balanced''`, down-sampling), fit unified preprocessing + estimator pipelines (`StandardScaler` + `XGBoost`/`LogisticRegression`), and log parameters, DVC hashes, metrics (`PR-AUC`, `FPR @ 90% Recall`), and SHAP explainers to MLflow."]}, {"id": "KP3", "description": "Enforce multi-stage Automated Model Validation gates (Champion-Challenger comparison, slice fairness, and latency/contract checks) before Registry promotion.", "required": true, "acceptable_evidence": ["Technical keywords: Champion-Challenger gate, PR-AUC threshold, subgroup slice evaluation, ModelSignature check, <100ms latency benchmark.", "Explains that a candidate model in MLflow (`Staging`) is automatically blocked from promotion unless it beats or matches the active `Production` champion on holdout metrics, passes critical cohort slice checks, satisfies Pydantic/`ModelSignature` contracts, and meets `<100ms` p99 latency."]}, {"id": "KP4", "description": "Deploy validated models via immutable Docker/ECR images, Helm charts, and ArgoCD GitOps with progressive Canary rollouts on Amazon EKS.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI microservice, Amazon ECR, Helm charts, ArgoCD GitOps, Amazon EKS, Canary / Shadow deployment, automated rollback.", "Explains that transitioning a model to `Production` triggers CI/CD to build/tag the stateless FastAPI container in ECR and sync the Helm release via ArgoCD onto EKS using shadow or canary traffic shifting (`10% -> 50% -> 100%`) with automatic rollback on error or latency spikes."]}, {"id": "KP5", "description": "Close the loop with continuous Prometheus/Grafana observability, Evidently AI drift detection, and automated retraining triggers.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, Evidently AI, PSI, KS-test, prediction drift, delayed ground-truth join, retraining webhook.", "Explains that production inference logs (`features`, `prediction`, `probability`, `model_version`) feed Prometheus/Grafana for system health and Evidently AI for feature/prediction drift (PSI/KS-test) and delayed-label `PR-AUC` tracking, automatically triggering the retraining pipeline when drift or accuracy degradation crosses threshold."]}], "critical_failures": ["Designs a one-way training-to-deployment script with no automated validation gate comparing the new model against the current Production champion.", "Omits a unified Feature Store or shared transformation pipeline, allowing offline training features and online FastAPI inference features to diverge.", "Deploys models without continuous drift monitoring (PSI/KS-test) or a mechanism to join delayed ground-truth labels back to historical predictions."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'BROAD', 210, 'How would you design and deploy a scalable inference system to handle high concurrency (e.g., 1000 requests per second)?', '{"key_points": [{"id": "KP1", "description": "Perform capacity planning via Little''s Law ($L = \\\\lambda W$) and architect a stateless multi-worker FastAPI / Triton serving tier on Amazon EKS.", "required": true, "acceptable_evidence": ["Technical keywords: Little''s Law, 1000 RPS, stateless FastAPI pods, Uvicorn/uvloop workers, pre-loaded MLflow model, Amazon EKS.", "Explains that at $\\\\lambda = 1,000\\\\text{ RPS}$ and target latency $W = 0.05\\\\text{s}$ (`<100ms` SLA in the Fraud Detection Study Guide), at least $L = 50$ requests are concurrently in flight at all times; models (`XGBoost`/`ONNX`) are loaded into shared memory once at container startup (`lifespan`) across multiple horizontally scaled EKS pods behind an AWS ALB and API Gateway."]}, {"id": "KP2", "description": "Eliminate synchronous database joins on the hot path using an ElastiCache Redis online Feature Store (`<5ms` pipelined lookups) and multi-layer caching.", "required": true, "acceptable_evidence": ["Technical keywords: ElastiCache Redis cluster, MGET / pipelining, online Feature Store, sub-5ms lookup, multi-layer semantic/embedding cache.", "Explains that querying relational/analytical stores (RDS/S3) at 1,000 RPS would collapse under I/O wait; instead, pre-aggregated historical and rolling velocity features are fetched from a sharded Redis cluster in `<2-5ms` via connection pools (`redis.asyncio`), while RAG/LLM workloads leverage multi-layer Redis caching (query embedding, retrieval result 1h TTL, and response caches) to absorb 30–50% of traffic before hitting compute."]}, {"id": "KP3", "description": "Optimize per-request compute overhead using compiled runtimes (`ONNX Runtime`, `TensorRT`, `vLLM`) and dynamic micro-batching.", "required": true, "acceptable_evidence": ["Technical keywords: ONNX Runtime, TensorRT, NVIDIA Triton dynamic batching, max_queue_delay_microseconds, vLLM continuous batching, C++ release of Python GIL.", "Explains that C++-backed inference engines (`ONNX Runtime`, `XGBoost` C-API, or `NVIDIA Triton` / `vLLM`) release the Python GIL and group incoming requests within a tiny window (e.g., `2–5ms` `max_queue_delay_microseconds` up to `max_batch_size=32/64`) into vectorized matrix operations to maximize CPU/GPU throughput at 1,000+ RPS."]}, {"id": "KP4", "description": "Offload non-critical work (audit logging, drift telemetry, notifications) to asynchronous background queues (`Celery` / `Kafka` / `SQS`).", "required": true, "acceptable_evidence": ["Technical keywords: asynchronous fire-and-forget, Kafka / Kinesis / SQS, Celery workers, non-blocking telemetry.", "Explains that writing prediction audit logs, publishing Evidently AI drift events, and sending downstream alerts are decoupled from the synchronous `POST /predict` response path via async buffers (`asyncio.Queue` / Kafka / SQS + Celery workers) so user-facing p99 latency remains `<100ms`."]}, {"id": "KP5", "description": "Enforce backpressure, token-bucket rate limiting, circuit breakers, and KEDA/HPA + Karpenter autoscaling.", "required": true, "acceptable_evidence": ["Technical keywords: API Gateway rate limiting, Redis token bucket, circuit breaker, KEDA / HPA, Karpenter, graceful degradation.", "Explains how the system survives traffic spikes beyond 1,000 RPS: API Gateway enforces per-tenant token-bucket rate limits, circuit breakers fail fast with fallback heuristics if a dependency degrades, and KEDA/HPA scales EKS pods on in-flight request concurrency while Karpenter provisions nodes."]}], "critical_failures": ["Executes synchronous PostgreSQL/RDS analytical joins or loads model weights from disk inside the `POST /predict` handler at 1,000 RPS.", "Runs pure-Python single-worker inference without releasing the GIL, horizontal pod replication, or dynamic batching.", "Writes audit logs and drift metrics synchronously to a database before returning the HTTP response, inflating p99 tail latency."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'What monitoring and alerting mechanisms did you put in place to ensure the system remained reliable in production?', '{"key_points": [{"id": "KP1", "description": "Instrument Golden Signals and infrastructure health probes across EKS, Redis, RDS, and Milvus using Prometheus, Grafana, and CloudWatch.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, AWS CloudWatch, p50/p95/p99 latency, HTTP 5xx error rate, GET /health readiness/liveness probes, Redis/Milvus saturation.", "Explains that production reliability starts with scraping `/metrics` and `/health` endpoints to track p95/p99 latency (`<100ms` for Fraud API; `<1.5s` TTFT for RAG), 4xx/5xx error rates, EKS pod restarts (`OOMKilled`), Celery queue lag, and Redis/Milvus connection health."]}, {"id": "KP2", "description": "Configure AI/ML-specific quality and safety monitors (Evidently AI drift checks, Langfuse Faithfulness/guardrail spikes, and Bedrock throttling).", "required": true, "acceptable_evidence": ["Technical keywords: Evidently AI, PSI > 0.2, KS-test, prediction score drift, Langfuse, Faithfulness drop, NeMo Guardrails block rate, HTTP 429 ThrottlingException.", "Explains that standard infrastructure checks miss silent AI failures, so the system also monitors feature/prediction distribution drift (PSI $> 0.2$, KS-test $p < 0.05$), spikes in null/missing online features, RAG retrieval top-1 cosine similarity drops, guardrail block rates, and AWS Bedrock token quota exhaustion."]}, {"id": "KP3", "description": "Structure multi-severity alerting (P1 PagerDuty vs. P2/P3 Slack) with sustained time-window evaluation to prevent alert fatigue.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus Alertmanager, CloudWatch Alarms, PagerDuty, Slack webhooks, `for: 5m` sustained window, multi-window SLO burn rate.", "Explains that alerts are tiered by customer impact and require sustained breach windows (e.g., `for: 5m`) to filter transient jitter: P1 critical SLO breaches (5xx $>1\\\\%$, p99 latency $>2\\\\times$ SLA, pod crash loops) page on-call via PagerDuty, while P2/P3 warnings (feature drift PSI $>0.2$, cache hit ratio drop, daily token budget >80%) post structured diagnostics to Slack."]}, {"id": "KP4", "description": "Pair every alert with an actionable runbook and automated self-healing (circuit breakers, fallback models, and ArgoCD rollback).", "required": false, "acceptable_evidence": ["Technical keywords: runbook link, trace_id correlation, circuit breaker fallback, ArgoCD auto-rollback, retraining webhook.", "Explains that alert payloads link directly to the relevant Grafana/Langfuse dashboard and incident runbook, while automated mitigations route around Bedrock outages via cross-region profiles or roll back faulty canary releases."]}], "critical_failures": ["Pages on-call engineers on single-request latency spikes without sustained evaluation windows (`for: 5m`) or severity tiering, causing severe alert fatigue.", "Monitors only HTTP 200 status codes without alerting on silent model failures (such as 100% fallback responses, null feature vectors, or severe prediction drift).", "Fires alerts with no runbook, `trace_id` context, or rollback mechanism."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how your model or application is deployed using Docker and Kubernetes, including how services are exposed and scaled?', '{"key_points": [{"id": "KP1", "description": "Package the application as a stateless Docker container and deploy it declaratively via a Kubernetes `Deployment` with resource requests/limits and probes.", "required": true, "acceptable_evidence": ["Technical keywords: Docker image, Amazon ECR, Kubernetes Deployment, replicas, resources.requests, resources.limits, readinessProbe, livenessProbe.", "Explains that the FastAPI model/RAG service is packaged in a non-root Docker image stored in Amazon ECR and deployed via a Kubernetes `Deployment` specifying replica count, CPU/Memory/GPU `requests` and `limits`, and `readinessProbe`/`livenessProbe` on `GET /health`."]}, {"id": "KP2", "description": "Expose internal pod communication via `ClusterIP` Services and external client traffic via AWS ALB Ingress Controller and API Gateway.", "required": true, "acceptable_evidence": ["Technical keywords: ClusterIP Service, kube-proxy / CoreDNS, AWS Load Balancer Controller, ALB Ingress, target-type: ip, AWS ACM TLS, API Gateway, CloudFront.", "Explains how traffic is exposed at two levels: internal microservices (`fastapi-backend`, `celery-worker`, `milvus`, `redis`) communicate privately over Kubernetes `ClusterIP` Services via CoreDNS, while external client traffic (e.g., from the ReactJS SPA on CloudFront) passes through AWS API Gateway / WAF and an AWS ALB `Ingress` (`target-type: ip` with ACM TLS termination) directly to ready pod IPs in private subnets."]}, {"id": "KP3", "description": "Scale pods horizontally using HPA/KEDA and scale underlying EC2 compute nodes using Karpenter or Cluster Autoscaler.", "required": true, "acceptable_evidence": ["Technical keywords: HorizontalPodAutoscaler (HPA), KEDA, custom Prometheus metrics, Karpenter, Cluster Autoscaler, PodDisruptionBudget.", "Explains that HPA/KEDA adjusts pod replicas dynamically (e.g., between `minReplicas: 3` and `maxReplicas: 25`) based on CPU/memory and custom Prometheus metrics (active in-flight requests, p95 latency, or Celery queue backlog), while Karpenter provisions additional multi-AZ EC2 nodes when unschedulable pods appear."]}, {"id": "KP4", "description": "Configure long-lived connection timeouts and graceful termination (`preStop`, `terminationGracePeriodSeconds`) for streaming and inference workloads.", "required": false, "acceptable_evidence": ["Technical keywords: ALB idle timeout, SSE streaming, preStop hook, terminationGracePeriodSeconds, zero-downtime scale-down.", "Explains that during scale-down or rolling updates, `preStop` hooks and extended `terminationGracePeriodSeconds` allow in-flight inference or SSE token streams to complete cleanly before `SIGTERM` terminates the container."]}], "critical_failures": ["Exposes individual EKS worker node ports (`NodePort` or public node IPs) directly to the public internet instead of routing through an ALB Ingress / API Gateway into private subnets.", "Omits CPU/memory `resources.requests` on the `Deployment`, preventing the Kubernetes HorizontalPodAutoscaler (HPA) from calculating utilization percentages.", "Terminates pods abruptly on scale-down without `readinessProbe` deregistration or `terminationGracePeriodSeconds`, dropping active client requests."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain the role of Argo CD in your deployment pipeline and how it integrates with Kubernetes and Helm charts?', '{"key_points": [{"id": "KP1", "description": "Define ArgoCD''s role as a pull-based Kubernetes GitOps controller that continuously reconciles live EKS cluster state with the desired state in Git.", "required": true, "acceptable_evidence": ["Technical keywords: pull-based GitOps, single source of truth, reconciliation loop, OutOfSync detection, selfHeal, prune.", "Explains that instead of CI scripts running `kubectl apply` with cluster-admin credentials from outside the cluster, ArgoCD runs inside Amazon EKS, watches the GitOps configuration repository, detects when live cluster objects diverge (`OutOfSync`), and automatically reconciles (`selfHeal: true`, `prune: true`) the cluster to match Git."]}, {"id": "KP2", "description": "Integrate ArgoCD `Application` / `ApplicationSet` CRDs with parameterized Helm charts and environment-specific `values-*.yaml` files.", "required": true, "acceptable_evidence": ["Technical keywords: ArgoCD Application CRD, ApplicationSet, Helm repo/path, valueFiles, values-staging.yaml, values-prod.yaml.", "Explains that each ArgoCD `Application` manifest points to a shared Helm chart (`charts/ai-service`) and overlays the target environment''s values file (`values-dev.yaml`, `values-staging.yaml`, `values-prod.yaml`); ArgoCD renders the Helm templates internally (`helm template`) and applies the resulting Kubernetes manifests to the target EKS namespace."]}, {"id": "KP3", "description": "Connect CI image/model builds to CD promotion via automated Git commits updating the ECR image SHA and MLflow model version.", "required": true, "acceptable_evidence": ["Technical keywords: CI-to-GitOps handoff, immutable ECR SHA tag, MLflow model_version, Sync Waves, PreSync hooks.", "Explains the end-to-end flow: after GitHub Actions CI passes DeepEval/ML validation gates and pushes `image:<git-sha>` to Amazon ECR, CI updates `image.tag` and `modelVersion` in the GitOps repo''s `values-staging.yaml` (or opens a PR for `values-prod.yaml`), which ArgoCD immediately syncs using Sync Waves (`PreSync` DB migrations -> `Sync` Deployment -> `PostSync` smoke test)."]}, {"id": "KP4", "description": "Leverage ArgoCD / Argo Rollouts for progressive Canary delivery, auditability, and instant Git-backed rollback.", "required": false, "acceptable_evidence": ["Technical keywords: Argo Rollouts, AnalysisTemplate, Prometheus metrics gate, git revert, argocd app rollback.", "Explains that every production change has a cryptographic Git audit trail (`git blame`/`git log`), and rolling back a bad deployment is as simple as `git revert` or `argocd app rollback`, restoring the exact previous Helm + ECR state in seconds."]}], "critical_failures": ["Stores long-lived EKS `cluster-admin` kubeconfig credentials inside external CI runners and mixes manual `kubectl edit` changes with ArgoCD (causing constant sync conflicts).", "Maintains duplicated raw Kubernetes YAML manifests per environment instead of using ArgoCD `valueFiles` overrides on a shared Helm chart.", "Commits plaintext secrets directly into the GitOps repository without External Secrets Operator or SealedSecrets."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain what a golden dataset is and how you created and used it for evaluation?', '{"key_points": [{"id": "KP1", "description": "Define a Golden Dataset and specify its structured schema (`input_query`, `ground_truth_context_ids`, `reference_answer`, `expected_tool_calls`, and `slice_metadata`).", "required": true, "acceptable_evidence": ["Technical keywords: Golden Dataset, ground-truth benchmark, input query, expected context doc_ids, reference answer, expected tool trajectory, metadata tags.", "Explains that a Golden Dataset is a version-controlled, SME-verified ground-truth evaluation benchmark where each test case pairs a realistic user query (or multi-turn conversation) with the exact ground-truth source chunk IDs required for retrieval, the verified reference answer/facts, expected tool calls (for agents), and slice tags (domain category, difficulty, adversarial type)."]}, {"id": "KP2", "description": "Construct the dataset by combining anonymized production logs, SME-authored domain edge cases, and LLM-synthesized adversarial/multi-hop queries verified by humans.", "required": true, "acceptable_evidence": ["Technical keywords: stratified sampling, SME annotation, Inter-Annotator Agreement, synthetic evolution (Evol-Instruct/RAGAS), out-of-scope abstention cases, prompt injection cases.", "Explains how the dataset is built across three sources (per the Study Guides & AI Builder''s Handbook): (1) clustering historical call-center/support queries and failure logs, (2) generating synthetic single-hop, multi-hop, and adversarial/out-of-scope abstention queries from Docling-parsed corpus chunks, and (3) having Domain SMEs review and approve every reference answer."]}, {"id": "KP3", "description": "Use the Golden Dataset to benchmark component-level Retrieval (`Recall@K`, `MRR`) and Generation (`Faithfulness`, `Answer Correctness`) in offline optimization and CI/CD gates.", "required": true, "acceptable_evidence": ["Technical keywords: DeepEval, RAGAS, Recall@K, MRR, NDCG@K, Faithfulness, Answer Correctness, CI/CD regression gate, judge calibration.", "Explains that the Golden Dataset drives systematic engineering decisions: comparing chunking sizes (`200–500` tokens), hybrid BM25 + Milvus weights, BGE Cross-Encoder reranking, and prompt templates, while acting as an automated blocking gate in GitHub Actions CI before any deployment."]}, {"id": "KP4", "description": "Version the Golden Dataset in DVC/Langfuse strictly separated from few-shot prompt exemplars and continuously expand it from production failures.", "required": false, "acceptable_evidence": ["Technical keywords: DVC / Langfuse Datasets versioning, data contamination prevention, Continuous Calibration (CC/CD) feedback loop.", "Explains that the Golden Dataset is versioned like code, strictly isolated from training/few-shot prompt examples to prevent data leakage, and updated continuously when new production edge cases are discovered."]}], "critical_failures": ["Uses unverified LLM-generated synthetic Q&A pairs as the Golden Dataset without human SME review, baking the generator LLM''s own hallucinations into the ground truth.", "Includes only easy ''happy-path'' single-fact questions while omitting multi-hop queries, unanswerable/abstention cases, and adversarial prompt injections.", "Copies examples directly from the Golden Dataset into the system prompt''s few-shot exemplars, invalidating the evaluation through data leakage."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'Can you walk through your Kubernetes deployment setup, including cluster architecture, scaling, and the types of workloads running in the pods?', '{"key_points": [{"id": "KP1", "description": "Architect a multi-AZ Amazon EKS cluster with segregated CPU and GPU Managed/Karpenter Node Groups using Taints, Tolerations, and Node Affinity.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS, multi-AZ private subnets, compute-optimized CPU node group, GPU node group (g5/g6), taints and tolerations, nodeSelector, namespace isolation.", "Explains that the EKS control plane spans 3 Availability Zones while worker nodes run in private VPC subnets segregated by workload profile: general/compute-optimized CPU nodes (`m6i`/`c6i`) for stateless APIs and orchestration, memory-optimized nodes for vector/data caching, and GPU nodes (`g5`/`g6` with `nvidia.com/gpu` taints) reserved strictly for local embedding/reranker (`BGE`) or SLM (`vLLM`/`Triton`) pods."]}, {"id": "KP2", "description": "Detail the distinct pod workloads running in the cluster (FastAPI API pods, LangGraph/RAG orchestrators, Celery async workers, reranker/model pods, and observability DaemonSets).", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI gateway pods, LangGraph/RAG worker pods, Celery ingestion workers, BGE reranker / MLflow model pods, DaemonSets (Prometheus Node Exporter, Fluent Bit, OpenTelemetry Collector).", "Explains the specific pod breakdown from the Study Guides: (1) stateless `fastapi-api` pods handling REST/SSE requests and `<100ms` fraud/RAG inference, (2) `celery-worker` pods consuming Redis/SQS queues for async Docling PDF parsing, chunking, embedding, and batch evaluations, (3) dedicated model/reranker inference pods, and (4) cluster-wide `DaemonSets` (`fluent-bit`, `otel-collector`, `prometheus-node-exporter`)."]}, {"id": "KP3", "description": "Scale heterogeneous workloads independently using HPA/KEDA custom metrics and Karpenter node autoscaling.", "required": true, "acceptable_evidence": ["Technical keywords: HorizontalPodAutoscaler (HPA), KEDA ScaledObject, active request concurrency, Redis/SQS queue length, Karpenter, Spot vs On-Demand.", "Explains that each workload scales on its bottleneck metric: `fastapi-api` pods scale via HPA/Prometheus on concurrent active requests and p95 latency; `celery-worker` pods scale via KEDA on Redis/SQS queue depth (even scaling down to low baseline replicas when idle); and Karpenter provisions On-Demand nodes for latency-critical APIs and Spot instances for fault-tolerant batch workers."]}, {"id": "KP4", "description": "Enforce pod resilience and security via `PodDisruptionBudget`s, Topology Spread Constraints, NetworkPolicies, and IRSA.", "required": false, "acceptable_evidence": ["Technical keywords: PodDisruptionBudget (PDB), topologySpreadConstraints, NetworkPolicy, IRSA, resource requests/limits.", "Explains how `topologySpreadConstraints` distribute replicas evenly across AZs, `PodDisruptionBudget`s guarantee minimum availability during node drains, and `NetworkPolicy` restricts pod-to-pod traffic."]}], "critical_failures": ["Runs heavy asynchronous PDF ingestion and batch embedding jobs inside the same FastAPI pod as real-time user-facing API requests, causing CPU starvation and `OOMKilled` crashes.", "Schedules lightweight CPU web pods onto expensive GPU instances because GPU node groups lack Kubernetes taints.", "Deploys all replicas into a single Availability Zone without `topologySpreadConstraints` or `PodDisruptionBudget`s."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'SPECIFIC', 90, 'Can you walk through your deployment architecture using Docker, AWS (ECR, ECS/EKS), and infrastructure as code?', '{"key_points": [{"id": "KP1", "description": "Provision the complete AWS network, security, data, and compute foundation declaratively using modular Terraform Infrastructure-as-Code.", "required": true, "acceptable_evidence": ["Technical keywords: Terraform modules, S3 remote state, DynamoDB state lock, VPC, public/private subnets, KMS, IAM/IRSA, RDS, ElastiCache Redis, S3.", "Explains that all AWS resources—multi-AZ VPC with public/private subnets and VPC PrivateLink endpoints, KMS encryption keys, S3 buckets (for DVC data & MLflow artifacts), RDS PostgreSQL, ElastiCache Redis, Amazon ECR repositories, and the EKS/ECS cluster—are defined in reusable Terraform modules (`modules/`) with encrypted S3 state and DynamoDB locking."]}, {"id": "KP2", "description": "Build hardened multi-stage Docker images and store them in Amazon ECR with automated vulnerability scanning and lifecycle policies.", "required": true, "acceptable_evidence": ["Technical keywords: multi-stage Dockerfile, non-root user, Amazon ECR, immutable tags, scanOnPush, ECR lifecycle policy.", "Explains that application and inference services are packaged into lean, non-root Docker images and pushed by CI to Amazon ECR with tag immutability enabled (`<git-sha>`), automated CVE scanning (`scanOnPush=true`), and lifecycle policies that expire untagged/stale dev images."]}, {"id": "KP3", "description": "Orchestrate containerized workloads on Amazon EKS (or ECS) behind AWS ALB & API Gateway with least-privilege IAM roles.", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS / ECS, AWS ALB, API Gateway, IRSA / ECS Task Role, AWS Secrets Manager, rolling/canary deployment.", "Explains that EKS pods (managed via Helm + ArgoCD) or ECS tasks pull signed images from ECR over a private VPC endpoint, assume fine-grained IAM roles (IRSA / Task IAM Role) to access Bedrock, S3, and Secrets Manager without static keys, and serve traffic behind an ALB and API Gateway."]}, {"id": "KP4", "description": "Coordinate Terraform infrastructure pipelines and application GitOps pipelines cleanly in CI/CD.", "required": true, "acceptable_evidence": ["Technical keywords: terraform plan/apply in CI, checkov/tfsec, separation of infra lifecycle vs app release lifecycle.", "Explains that Terraform manages long-lived AWS infrastructure via PR-gated `terraform plan` -> `terraform apply` workflows, while frequent daily application/model releases update ECR image tags in Helm/ArgoCD (or ECS task definitions) without re-running full cluster Terraform scripts."]}], "critical_failures": ["Mixes manual AWS Console modifications with Terraform, causing state drift and failed `terraform apply` runs.", "Embeds static `AWS_ACCESS_KEY_ID` and `AWS_SECRET_ACCESS_KEY` in Docker images or environment variables instead of using EKS IRSA or ECS Task IAM Roles.", "Pushes un-scanned root-user Docker images with mutable `:latest` tags to Amazon ECR."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'BROAD', 150, 'Can you walk through your end-to-end MLOps lifecycle, including data pipelines, model training, deployment, and monitoring, and how these components interact?', '{"key_points": [{"id": "KP1", "description": "Connect the Data Pipeline to both Training and Serving through DVC-versioned S3 storage and a Dual-Layer Feature Store (S3/Parquet offline + Redis online).", "required": true, "acceptable_evidence": ["Technical keywords: DVC, S3/Parquet offline store, Redis online store, point-in-time feature joins, label-maturity window, schema validation.", "Explains how data pipelines ingest raw events/transactions, enforce schema/quality checks and label-maturity windows (e.g., confirmed chargebacks in Fraud Detection), version snapshots with DVC, and write shared feature transformations to both the S3/Parquet offline store (for training) and Redis online store (for `<5ms` real-time inference lookups), preventing training-serving skew."]}, {"id": "KP2", "description": "Connect the Training Pipeline to the Deployment Pipeline via the MLflow Tracking Server and MLflow Model Registry.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Tracking Server, RDS metadata, S3 artifact store, sklearn.pipeline.Pipeline, PR-AUC, FPR @ 90% Recall, TreeSHAP, MLflow Model Registry.", "Explains that training pipelines pull DVC-versioned offline features, perform chronological train/test splits and imbalance handling, fit bundled `StandardScaler` + `LogisticRegression`/`XGBoost` pipelines, log metrics (`PR-AUC`, `FPR @ 90% Recall`) and SHAP explainers to MLflow, and register candidate models into the MLflow Model Registry (`Staging -> Validation -> Production`)."]}, {"id": "KP3", "description": "Connect the MLflow Model Registry to the Production Serving tier via CI/CD, Docker/ECR, Helm, and ArgoCD on Amazon EKS.", "required": true, "acceptable_evidence": ["Technical keywords: Model Registry webhook, GitHub Actions CI, FastAPI, Amazon ECR, Helm chart, ArgoCD GitOps, Amazon EKS, POST /predict.", "Explains that promoting a validated model to `Production` in MLflow triggers CI/CD to package the stateless FastAPI service (`POST /predict`, `GET /health`) with the pinned model version into an ECR Docker image and roll it out progressively onto Amazon EKS via ArgoCD and Helm."]}, {"id": "KP4", "description": "Connect the Serving tier to the Monitoring tier by emitting structured inference telemetry (`features`, `prediction`, `probability`, `model_version`) to Prometheus and Evidently AI.", "required": true, "acceptable_evidence": ["Technical keywords: inference telemetry, model_version tag, Prometheus, Grafana, Evidently AI, PSI, KS-test, prediction score drift.", "Explains that every FastAPI inference response logs the input feature vector, output `prediction`, `probability`, top-3 SHAP `explanation`, and `model_version`, enabling Prometheus/Grafana to monitor p99 latency (`<100ms` SLA) and 5xx rates while Evidently AI compares live feature and prediction distributions against the training baseline stored in MLflow."]}, {"id": "KP5", "description": "Close the feedback loop by joining delayed ground-truth labels and triggering automated retraining when drift or accuracy degradation occurs.", "required": true, "acceptable_evidence": ["Technical keywords: delayed label join, realized PR-AUC / FPR, drift webhook trigger, closed-loop retraining.", "Explains how the Monitoring component feeds back into the Data and Training pipelines: when Evidently AI detects sustained feature drift ($\\\\text{PSI} > 0.2$) or when matured ground-truth labels join with logged predictions and reveal `PR-AUC` degradation, an automated webhook triggers a fresh DVC data snapshot and MLflow retraining run."]}], "critical_failures": ["Describes data ingestion, training, deployment, and monitoring as four isolated steps without explaining the concrete integration contracts (Feature Store, MLflow Registry URI, and `model_version` telemetry) that connect them.", "Computes training features and online inference features using separate, unshared codebases, introducing training-serving skew.", "Has no feedback loop to join production predictions with delayed ground-truth outcomes or trigger retraining on drift."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'Have you worked with AWS SageMaker, and how did you use it for model training, deployment, or lifecycle management?', '{"key_points": [{"id": "KP1", "description": "Execute ephemeral, scalable distributed training and hyperparameter tuning using SageMaker Training Jobs (with Managed Spot Training) and S3 data channels.", "required": true, "acceptable_evidence": ["Technical keywords: SageMaker Training Jobs, Script Mode / BYOC container, S3 FastFile / Pipe mode, Managed Spot Training, checkpointing, Hyperparameter Tuning Jobs (AMT).", "Explains how SageMaker provisions ephemeral CPU/GPU instances on demand to train models on S3 Parquet datasets, saves up to 70% compute cost via Managed Spot Training with S3 checkpoint resumption, and runs Bayesian Automated Model Tuning (AMT) while logging metrics to SageMaker Experiments or a remote MLflow Tracking Server."]}, {"id": "KP2", "description": "Orchestrate end-to-end MLOps DAGs and govern model approval workflows using SageMaker Pipelines and SageMaker Model Registry.", "required": true, "acceptable_evidence": ["Technical keywords: SageMaker Pipelines, ProcessingStep, TrainingStep, EvaluationStep, ConditionStep, ModelPackageGroup, PendingManualApproval -> Approved.", "Explains that SageMaker Pipelines automates the DAG (`ProcessingStep` for feature engineering -> `TrainingStep` -> `EvaluationStep` computing `PR-AUC`/`F1` -> `ConditionStep` quality gate) and registers passing models in a SageMaker Model Registry `ModelPackageGroup`, triggering EventBridge deployment events upon status transition to `Approved`."]}, {"id": "KP3", "description": "Select the optimal SageMaker deployment mode (Real-Time Multi-Model/Multi-Container Endpoints, Asynchronous Inference, or Batch Transform) or hybrid EKS serving.", "required": true, "acceptable_evidence": ["Technical keywords: SageMaker Real-Time Endpoints, Multi-Model Endpoints (MME), Asynchronous Inference, Batch Transform, SageMaker Clarify & Model Monitor.", "Explains how SageMaker serving modes match workload patterns: Real-Time Endpoints with auto-scaling and Data Capture for `<100ms` online inference (or Multi-Model Endpoints to share GPU/CPU instances across dozens of models), Asynchronous Inference for large payloads up to 1GB, and Batch Transform for offline scoring, alongside Model Monitor / Clarify for drift and SHAP bias detection."]}, {"id": "KP4", "description": "Evaluate the architectural trade-offs of AWS SageMaker vs. custom FastAPI + MLflow deployments on Amazon EKS.", "required": true, "acceptable_evidence": ["Technical keywords: managed instance markups, cold-start scaling speed, hybrid training on SageMaker + serving on EKS.", "Explains the practical trade-off highlighted in the Study Guides: SageMaker eliminates cluster maintenance for bursty GPU training and managed endpoints, but incurs a per-instance AWS markup and less flexible custom orchestration than EKS—leading many architectures to run ephemeral GPU training on SageMaker while serving custom FastAPI + LangGraph + Redis microservices on Amazon EKS."]}], "critical_failures": ["Leaves expensive GPU SageMaker Studio notebooks or idle Real-Time Endpoints running 24/7 for sporadic batch workloads instead of using ephemeral SageMaker Training Jobs or Batch Transform.", "Cannot distinguish between SageMaker Real-Time Endpoints, Asynchronous Inference, and Batch Transform.", "Registers models in SageMaker without an automated `EvaluationStep` + `ConditionStep` gate."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'Content-wise, how does your MLOps architecture differ when deploying traditional ML models versus LLM/GenAI applications?', '{"key_points": [{"id": "KP1", "description": "Contrast Artifact & Versioning granularity: tabular model weights + Feature Store (`DVC` + `MLflow`) vs. composite GenAI system bundles (Prompts, RAG Vector Indexes, Rerankers, and Agent Tools).", "required": true, "acceptable_evidence": ["Technical keywords: model.pkl + StandardScaler + Feature Store vs Prompt Registry + Milvus HNSW index + BGE reranker + MCP tool schemas + Bedrock model ID.", "Explains that in traditional ML (e.g., Fraud Detection Study Guide), the primary versioned unit is a trained estimator (`XGBoost`/`LogisticRegression`), its fitted `StandardScaler`, and structured Feature Store definitions (S3/Parquet + Redis); in LLM/GenAI Ops (RAG & Agentic Study Guides), foundation model weights are often frozen/external (AWS Bedrock), so versioning must track a composite bundle of system prompts, chunking parameters (`200-500` tokens), embedding models, Milvus vector index snapshots, and LangGraph/MCP tool schemas."]}, {"id": "KP2", "description": "Contrast Evaluation paradigms: deterministic scalar metrics against ground-truth labels (`PR-AUC`, `FPR @ 90% Recall`, `RMSE`) vs. multi-dimensional semantic & reference-free RAG/Agent rubrics (`DeepEval`, `RAGAS`, LLM-as-a-Judge).", "required": true, "acceptable_evidence": ["Technical keywords: PR-AUC, ROC-AUC, F1, confusion matrix vs RAG Triad, Faithfulness, Answer Relevance, Contextual Recall@K, MRR, trajectory tool accuracy.", "Explains that traditional ML outputs a scalar probability or class evaluated deterministically against ground-truth labels (`PR-AUC`, `FPR @ 90% Recall`), whereas GenAI outputs unstructured stochastic text and multi-step tool trajectories requiring decoupled Retrieval metrics (`Recall@K`, `MRR`) and human-calibrated LLM-as-a-Judge evaluation (`Faithfulness`, `Answer Correctness`) on a Golden Dataset."]}, {"id": "KP3", "description": "Contrast Serving & Latency mechanics: stateless `<100ms` request-response CPU/light-GPU inference vs. stateful KV-cached token streaming (`SSE`), multi-layer semantic caching, and external API rate-limit management.", "required": true, "acceptable_evidence": ["Technical keywords: <100ms synchronous REST vs Time-To-First-Token (TTFT), Inter-Token Latency (ITL), SSE streaming, KV prefix caching, Redis semantic cache, Bedrock TPM/RPM quotas.", "Explains that traditional ML inference executes in `<10–100ms` on compact feature vectors, whereas LLM/GenAI requests take `1–15s`, stream tokens over Server-Sent Events (SSE), are bounded by GPU HBM bandwidth (KV cache) or external provider TPM/RPM quotas, and rely heavily on multi-layer Redis semantic/embedding caching and tiered model routing (Claude Haiku vs. Sonnet)."]}, {"id": "KP4", "description": "Contrast Production Monitoring & Safety: statistical covariate/prediction drift (`PSI`, `KS-test`) and SHAP vs. trace-level observability (`Langfuse`), multi-stage guardrails (`NeMo`, `Presidio`), and prompt injection defense.", "required": true, "acceptable_evidence": ["Technical keywords: Evidently AI, PSI, KS-test, TreeSHAP vs Langfuse, OpenTelemetry spans, NeMo Guardrails, Presidio PII/PHI redaction, indirect prompt injection.", "Explains that traditional MLOps monitors numerical feature distributions (KS-test, PSI) and delayed-label concept drift, whereas LLMOps requires span-by-span distributed tracing (Langfuse/OpenTelemetry), real-time PII/PHI scrubbing (Presidio), input/output safety rails against jailbreaks and hallucinations (NeMo Guardrails), and token-cost governance."]}], "critical_failures": ["Claims that deploying an LLM/RAG system is identical to deploying a scikit-learn `.pkl` model and requires only standard CPU autoscaling and accuracy metrics.", "Applies simple numerical KS-tests on raw text strings instead of monitoring retrieval similarity, Faithfulness, and embedding centroid drift in GenAI systems.", "Ignores prompt/context versioning, semantic caching, and safety guardrails when transitioning from traditional ML to LLMOps."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How did you design and manage the infrastructure for your application, including compute resources and deployment environment?', '{"key_points": [{"id": "KP1", "description": "Right-size heterogeneous compute tiers by matching workload bottlenecks (CPU-bound APIs, memory-bound vector indexes, GPU-bound inference/reranking) to dedicated instance families.", "required": true, "acceptable_evidence": ["Technical keywords: compute-optimized (c6i/m6i), memory-optimized (r6i), GPU instances (g5/g6), AWS Bedrock managed serverless, resource requests/limits.", "Explains that infrastructure is partitioned by hardware bottleneck rather than running everything on one generic instance type: stateless FastAPI and LangGraph orchestration pods run on CPU-optimized EKS nodes (`c6i`/`m6i`), Milvus HNSW indexes and ElastiCache Redis run on memory-optimized instances (`r6i`), local BGE Cross-Encoder / SLM workloads run on GPU nodes (`g5`), and frontier LLM generation uses managed AWS Bedrock."]}, {"id": "KP2", "description": "Isolate `dev`, `staging`, and `prod` environments across network boundaries, IAM permissions, and data stores using Terraform and Kubernetes namespaces/clusters.", "required": true, "acceptable_evidence": ["Technical keywords: environment isolation, VPC private subnets, Security Groups, IRSA least privilege, KMS encryption, Terraform workspaces/modules.", "Explains that `dev`, `staging`, and `prod` are provisioned via shared Terraform modules with strict isolation: `prod` runs in dedicated private VPC subnets with multi-AZ RDS/Redis high availability, strict Security Groups, and KMS-encrypted storage that `dev`/`staging` IAM roles cannot access."]}, {"id": "KP3", "description": "Manage dynamic compute elasticity and cloud FinOps using HPA/KEDA, Karpenter, Spot instances for batch/training jobs, and multi-layer caching.", "required": true, "acceptable_evidence": ["Technical keywords: Karpenter consolidation, Spot instances (Celery/training), On-Demand/Savings Plans (online APIs), HPA/KEDA, Redis caching.", "Explains how compute costs and latency SLAs are balanced: latency-critical `POST /predict` and RAG API pods run on baseline On-Demand/Savings Plan nodes with HPA headroom, while fault-tolerant Celery ingestion workers and offline training jobs run on Spot instances (saving 60–70%) and scale to zero/minimum when queues drain."]}], "critical_failures": ["Runs stateless FastAPI web servers or idle dev environments on expensive 24/7 GPU instances.", "Shares the same production RDS database, Redis cache, or Milvus collection with `dev` and `staging` test workloads.", "Provisions fixed static EC2 instances manually without autoscaling (HPA/Karpenter) or Infrastructure-as-Code (Terraform)."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you detect and handle data drift or concept drift in your production models, and how did that trigger retraining?', '{"key_points": [{"id": "KP1", "description": "Distinguish mathematically and operationally between Data (Covariate) Drift ($P(X)$ shifts) and Concept Drift ($P(Y \\\\mid X)$ shifts).", "required": true, "acceptable_evidence": ["Technical keywords: Data Drift (covariate shift, P(X)), Concept Drift (posterior shift, P(Y|X)), Prediction Drift (P(y_hat)).", "Explains that Data Drift occurs when the distribution of incoming production input features $P(X)$ diverges from the training baseline (e.g., holiday transaction amount surges or a broken upstream feature feed), whereas Concept Drift occurs when the relationship between features and target $P(Y \\\\mid X)$ changes (e.g., fraudsters inventing a new attack pattern so previously benign feature combinations become fraudulent)."]}, {"id": "KP2", "description": "Quantify Data Drift and Prediction Score Drift in real time using Evidently AI statistical tests (`PSI`, `KS-test`, `Chi-Square` / `Jensen-Shannon`) weighted by SHAP importance.", "required": true, "acceptable_evidence": ["Technical keywords: Evidently AI, Population Stability Index (PSI > 0.2), two-sample Kolmogorov-Smirnov (KS) test, Chi-Square test, prediction probability distribution, TreeSHAP weighting.", "Explains that per the Fraud Detection Study Guide, Evidently AI compares sliding windows of production features against the MLflow training reference using KS-tests (continuous features) and PSI / Chi-Square (binned/categorical features, where $\\\\text{PSI} < 0.1$ is stable, $0.1–0.2$ is warning, and $>0.2$ is critical drift), prioritizing drift on top TreeSHAP features and tracking output `probability` score drift as an immediate proxy before delayed labels arrive."]}, {"id": "KP3", "description": "Detect Concept Drift by joining delayed ground-truth labels (after the label-maturity window) and analyst overrides with logged `model_version` predictions.", "required": true, "acceptable_evidence": ["Technical keywords: delayed chargeback labels, label-maturity window, realized PR-AUC, FPR @ 90% Recall, analyst override feedback.", "Explains that as confirmed ground-truth outcomes (e.g., 30–90 day fraud chargebacks or human review labels) mature, an offline job joins them via `transaction_id`/`trace_id` to historical predictions to compute realized `PR-AUC` and `FPR @ 90% Recall`, confirming true Concept Drift."]}, {"id": "KP4", "description": "Triage data pipeline bugs vs. genuine domain shifts and trigger automated Champion-Challenger retraining and MLflow validation.", "required": true, "acceptable_evidence": ["Technical keywords: upstream data quality triage, automated retraining webhook, DVC sliding window snapshot, MLflow Champion-Challenger gate, shadow/canary rollout.", "Explains that when drift breaches threshold across sustained windows, the system first verifies that the drift is not an upstream schema/null bug (which requires a data fix, not retraining on corrupted data!), and then triggers an automated retraining pipeline on the latest matured DVC dataset, promoting the new model through MLflow `Staging -> Validation -> Production` only if it beats the current champion."]}], "critical_failures": ["Blindly triggers automated retraining and auto-deploys to production when an upstream bug sends all-null or zeroed features, training a corrupted model on broken data.", "Cannot distinguish between Data Drift ($P(X)$ change) and Concept Drift ($P(Y \\\\mid X)$ change).", "Trains a replacement model on the most recent 24 hours of transactions before delayed fraud/outcome labels have matured, treating unconfirmed fraud as legitimate negative examples."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Cloud Architecture & Services', 'MEDIUM', 'SPECIFIC', 90, 'How did you handle monitoring and logging in production using tools like AWS CloudWatch, Prometheus, and Grafana?', '{"key_points": [{"id": "KP1", "description": "Emit structured JSON logs with correlation IDs (`trace_id`, `request_id`, `model_version`) scraped by Fluent Bit DaemonSets into AWS CloudWatch Logs.", "required": true, "acceptable_evidence": ["Technical keywords: structured JSON logging, python-json-logger, Fluent Bit DaemonSet, AWS CloudWatch Logs, CloudWatch Logs Insights, S3 Glacier archival, PII scrubbing.", "Explains that all EKS pods write structured JSON logs to `stdout`/`stderr` enriched with `trace_id`, `tenant_id`, `model_version`, and latency, which are collected by a lightweight `Fluent Bit` DaemonSet (after Presidio PII redaction) and shipped to AWS CloudWatch Log Groups with retention policies and CloudWatch Logs Insights query indexes."]}, {"id": "KP2", "description": "Scrape time-series application and Kubernetes cluster metrics using Prometheus (`ServiceMonitor`, histograms, counters, gauges).", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, /metrics endpoint, Histogram (http_request_duration_seconds_bucket), Counter, Gauge, kube-state-metrics, node-exporter, label cardinality.", "Explains that FastAPI and Celery workers expose Prometheus metrics via `/metrics` (using `Histogram` buckets for p50/p95/p99 latency, `Counter` for request/error/prediction counts by `model_version`, and `Gauge` for queue depth and active streams) while keeping label cardinality bounded (never putting `user_id` or `trace_id` in Prometheus labels)."]}, {"id": "KP3", "description": "Unify Prometheus and AWS CloudWatch data sources in Grafana dashboards with Exemplars linking metric spikes directly to CloudWatch logs.", "required": true, "acceptable_evidence": ["Technical keywords: Grafana dashboards, PromQL (histogram_quantile), CloudWatch data source (RDS, Redis, ALB, Bedrock), Prometheus Exemplars, Alertmanager.", "Explains that Grafana combines PromQL pod/application metrics with AWS CloudWatch managed-service metrics (ALB 5xx, RDS CPU/connections, ElastiCache Redis evictions, Bedrock throttling) into unified operational dashboards and uses Prometheus Exemplars (`trace_id`) so engineers can click a p99 latency spike and jump directly to the exact CloudWatch JSON log."]}], "critical_failures": ["Writes unstructured multi-line `print()` statements to local container disk files instead of emitting structured JSON logs to `stdout` for Fluent Bit / CloudWatch collection.", "Includes high-cardinality identifiers (`user_id`, `request_id`, or raw query strings) as Prometheus metric labels, causing Prometheus TSDB memory explosion.", "Logs raw unredacted customer PII/PHI or API tokens into CloudWatch Logs."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you implement observability and monitoring using tools like Langfuse, CloudWatch, Prometheus, and Grafana?', '{"key_points": [{"id": "KP1", "description": "Instrument deep LLM, RAG, and Agent workflow tracing in Langfuse (prompts, retrieved chunks, reranker scores, tool calls, token cost, and online evals).", "required": true, "acceptable_evidence": ["Technical keywords: Langfuse, OpenTelemetry, nested trace spans, prompt version tracking, Milvus retrieval scores, BGE reranker scores, MCP tool calls, token cost attribution.", "Explains that Langfuse captures the semantic execution tree of every RAG or Agentic request (per the Call Center, TalentScreen, and Recruiting 2.0 Study Guides): recording the exact prompt template version, query rewrite, retrieved Milvus document IDs and similarity scores, BGE Cross-Encoder reranking scores, LangGraph node transitions, MCP tool inputs/outputs, Bedrock input/output token counts, USD cost, and sampled DeepEval/RAGAS Faithfulness scores."]}, {"id": "KP2", "description": "Use Prometheus and Grafana for real-time infrastructure and service-level telemetry (p50/p95/p99 latency, TTFT, RPS, cache hit rates, and pod saturation).", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, TTFT, end-to-end latency histograms, Redis multi-layer cache hit rate, Celery queue lag, EKS pod CPU/Memory/GPU.", "Explains that Prometheus scrapes high-frequency numeric time-series from FastAPI, Celery, Redis, and Milvus, while Grafana visualizes real-time SLO dashboards (Time-To-First-Token, p99 latency, multi-layer Redis cache hit ratios, and pod resource utilization)."]}, {"id": "KP3", "description": "Use AWS CloudWatch for centralized container/infrastructure logs and managed AWS service metrics (Bedrock, ALB, RDS, S3).", "required": true, "acceptable_evidence": ["Technical keywords: AWS CloudWatch Logs, Fluent Bit, CloudWatch Metrics, AWS Bedrock invocation/throttling metrics, RDS/ElastiCache health.", "Explains that CloudWatch aggregates Fluent Bit container JSON logs and tracks AWS-native infrastructure telemetry (Bedrock `InvocationThrottles`, API Gateway/ALB 4xx/5xx, RDS IOPS, and S3 ingestion events)."]}, {"id": "KP4", "description": "Correlate all four tools via a shared OpenTelemetry `trace_id` for rapid cross-layer incident debugging.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry W3C TraceContext, shared trace_id, metric-to-trace-to-log correlation, async non-blocking export.", "Explains how the four tools form a cohesive stack: when a Grafana/Prometheus alert fires on high p99 latency or error rate, the engineer inspects the exemplar `trace_id`, opens that exact `trace_id` in Langfuse to see which RAG retrieval step, LLM prompt, or tool call failed or hallucinated, and cross-references system stack traces in CloudWatch Logs."]}], "critical_failures": ["Cannot explain the division of responsibilities between Langfuse (semantic LLM/RAG trace & eval observability), Prometheus/Grafana (time-series metrics & SLO dashboards), and CloudWatch (centralized AWS logs & managed service telemetry).", "Emits Langfuse traces synchronously without background batching, adding network latency to user requests.", "Uses separate, unconnected IDs in Prometheus, CloudWatch, and Langfuse so alerts cannot be traced to the underlying LLM prompt or retrieved chunks."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'SPECIFIC', 90, 'How did you manage environment-specific configurations and secrets across dev, QA, and production in your CI/CD pipeline?', '{"key_points": [{"id": "KP1", "description": "Separate non-sensitive environment configuration (`ConfigMap` / Helm `values-*.yaml`) strictly from sensitive credentials (`Secret` / AWS Secrets Manager).", "required": true, "acceptable_evidence": ["Technical keywords: 12-Factor App, Helm values-dev.yaml / values-qa.yaml / values-prod.yaml, Kubernetes ConfigMap, Pydantic BaseSettings.", "Explains that non-sensitive settings (replica counts, log levels, MLflow registry URIs, Redis/Milvus hostnames, chunking/reranker thresholds) are stored in Git inside Helm `values-<env>.yaml` files, injected as Kubernetes `ConfigMap`s, and validated at FastAPI startup using `pydantic-settings` (`BaseSettings`)."]}, {"id": "KP2", "description": "Store encrypted secrets in AWS Secrets Manager / Parameter Store (KMS) and inject them dynamically into EKS via External Secrets Operator (ESO) and IRSA.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Secrets Manager, AWS KMS, External Secrets Operator (ESO), ExternalSecret CRD, IRSA, Secrets Store CSI Driver, automated secret rotation.", "Explains that sensitive credentials (RDS database passwords, JWT signing keys, Langfuse/third-party API keys) are never stored in Git or container images; they reside in KMS-encrypted AWS Secrets Manager under environment-prefixed paths (`/prod/ai-app/...`) and are synced into EKS namespaces by External Secrets Operator using least-privilege IRSA roles."]}, {"id": "KP3", "description": "Secure CI/CD pipeline execution using OIDC federated authentication (`aws-actions/configure-aws-credentials`) and environment-scoped approval rules.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub Actions OIDC federation, short-lived STS tokens, environment protection rules, gitleaks / trufflehog secret scanning.", "Explains that CI/CD pipelines authenticate to AWS using short-lived OIDC federation tokens scoped per branch/environment (`dev` vs `prod` IAM roles) rather than static long-lived AWS keys, while pre-commit and CI `gitleaks`/`trufflehog` scans block any accidental secret commits."]}], "critical_failures": ["Commits plaintext `.env` files, database passwords, or API keys into the Git repository or bakes them inside the `Dockerfile`.", "Shares the exact same database credentials, JWT signing keys, or IAM role across `dev`, `qa`, and `prod`.", "Uses static, non-rotating root `AWS_SECRET_ACCESS_KEY` credentials in CI/CD instead of OIDC role federation."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 90, 'How did you manage model lifecycle and deployment when transitioning from an older model version to a newer one?', '{"key_points": [{"id": "KP1", "description": "Validate the new model version (`v2`, e.g., Phase 2 XGBoost) against the incumbent (`v1`, e.g., Phase 1 Logistic Regression) offline in MLflow across holdout metrics, calibration, and `<100ms` latency.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Model Registry, Champion-Challenger evaluation, PR-AUC, FPR @ 90% Recall, probability calibration, ModelSignature compatibility.", "Explains that before any production traffic touches `v2`, offline validation in MLflow confirms that `v2` beats `v1` on chronological holdout sets (`PR-AUC`, `FPR @ 90% Recall`), verifies probability calibration (so downstream decision thresholds remain valid or are recalibrated), and checks input/output schema (`ModelSignature`) and `<100ms` p99 latency parity."]}, {"id": "KP2", "description": "Maintain non-breaking backward compatibility in the Online Feature Store (Redis) and API response contract (`POST /predict`) during dual-version operation.", "required": true, "acceptable_evidence": ["Technical keywords: additive Feature Store evolution, dual-version feature availability, bundled StandardScaler, Pydantic response compatibility.", "Explains that if `v2` requires new features, they are added non-destructively to the Redis Online Feature Store while keeping all `v1` features active, and each model artifact bundles its own fitted preprocessing pipeline (`StandardScaler`) so `v1` and `v2` can run concurrently without conflict."]}, {"id": "KP3", "description": "Execute a phased production cutover: Shadow (Dark) Mirroring followed by Progressive Canary Traffic Shifting (`5% -> 25% -> 50% -> 100%`).", "required": true, "acceptable_evidence": ["Technical keywords: Shadow / Dark deployment, asynchronous traffic mirroring, Canary rollout, Argo Rollouts / Istio, model_version logging.", "Explains that `v2` is first deployed in Shadow mode—receiving mirrored live production requests asynchronously to verify p99 latency, zero runtime errors, and prediction distribution alignment without affecting users—followed by a progressive Canary rollout (`5% -> 25% -> 50% -> 100%`) where every response is stamped with `model_version`."]}, {"id": "KP4", "description": "Keep `v1` warm during the stabilization window for instant rollback before archiving `v1` in MLflow.", "required": true, "acceptable_evidence": ["Technical keywords: warm standby / instant rollback, MLflow Archived stage, post-cutover Evidently AI monitoring.", "Explains that `v1` remains warm and tagged in ECR/MLflow throughout the burn-in period so traffic can be shifted back to `v1` in seconds if Prometheus or Evidently AI detects anomalies, transitioning `v1` to `Archived` in MLflow only after `v2` proves stable at 100% traffic."]}], "critical_failures": ["Performs an abrupt 100% in-place overwrite of `v1` with `v2` in production without shadow testing or canary traffic shifting.", "Applies `v1`''s raw decision threshold to `v2`''s uncalibrated probability scores without verifying score distribution alignment (causing an immediate spike in false positives or false negatives).", "Deletes `v1`''s required features from the Redis Feature Store before confirming `v2` is stable in production, breaking rollback capability."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 90, 'How did you use DVC for data and model versioning, and how does it integrate with Git in your workflow?', '{"key_points": [{"id": "KP1", "description": "Explain how DVC decouples large binary datasets/models from Git using content-addressable MD5/SHA256 `.dvc` pointer files and an Amazon S3 remote cache.", "required": true, "acceptable_evidence": ["Technical keywords: dvc add, .dvc pointer file, .gitignore, MD5/SHA256 content-addressable cache, dvc remote add s3://, dvc push, dvc pull.", "Explains that Git is designed for source code and degrades on multi-gigabyte Parquet/CSV datasets or `.pkl` artifacts; running `dvc add data/transactions.parquet` adds the large file to `.gitignore`, computes its cryptographic content hash, stores the binary in a content-addressed Amazon S3 remote (`dvc push`), and commits only the tiny human-readable `.dvc` pointer file into Git."]}, {"id": "KP2", "description": "Define reproducible multi-stage ML DAGs using `dvc.yaml`, `params.yaml`, and `dvc.lock` (`dvc repro`).", "required": true, "acceptable_evidence": ["Technical keywords: dvc.yaml, params.yaml, dvc.lock, dvc repro, dependency graph (deps, params, outs, metrics).", "Explains that `dvc.yaml` declaratively defines pipeline stages (`preprocess -> featurize -> train -> evaluate`) with explicit `deps`, `params` (from `params.yaml`), `outs`, and `metrics`; running `dvc repro` skips unchanged stages via cached hashes and updates `dvc.lock` with exact input/output checksums."]}, {"id": "KP3", "description": "Synchronize Git branches/tags with DVC snapshots (`git checkout <sha> && dvc checkout / dvc pull`) and log DVC hashes into MLflow.", "required": true, "acceptable_evidence": ["Technical keywords: git checkout + dvc pull, dvc metrics diff, MLflow dataset hash logging, CI/CD data hydration.", "Explains that every Git commit or release tag (`v1.2.0`) locks both the exact Python code and the exact `dvc.lock` data/model checksums, allowing any developer or CI runner to execute `git checkout v1.2.0 && dvc pull` to restore the exact historical dataset and cross-reference the DVC hash recorded in MLflow."]}], "critical_failures": ["Commits multi-gigabyte Parquet datasets or `.pkl` model binaries directly into Git without DVC, bloating the `.git` repository.", "Runs `dvc add` locally without executing `dvc push` to the shared S3 remote or without committing the updated `.dvc` / `dvc.lock` file to Git.", "Cannot explain how `.dvc` pointer files and `dvc.lock` link Git commits to S3 content-addressed storage."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'How did you design and implement your CI/CD pipeline from code commit to production deployment?', '{"key_points": [{"id": "KP1", "description": "Execute Stage 1 (Commit & Static/Unit Verification): run linting, static type checks, secret scans, and fast deterministic unit/contract tests.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub Actions / GitLab CI, ruff, black, mypy, gitleaks, pytest, Pydantic contract validation.", "Explains that every commit/PR triggers fast automated checks: `ruff`/`black` linting, `mypy` strict typing, `gitleaks` secret detection, and `pytest` unit/contract tests validating FastAPI schemas, feature preprocessing (`StandardScaler`), and mocked tool/RAG components."]}, {"id": "KP2", "description": "Execute Stage 2 (AI/ML Evaluation Gate & Artifact Packaging): run Golden Dataset / holdout model checks, build a multi-stage Docker image, scan with Trivy, and push to Amazon ECR.", "required": true, "acceptable_evidence": ["Technical keywords: DeepEval / RAGAS Golden Dataset gate, MLflow PR-AUC / FPR gate, multi-stage Docker build, Trivy CVE scan, Amazon ECR, immutable Git SHA tag.", "Explains that the pipeline gates merges on quantitative AI quality (DeepEval/RAGAS Faithfulness & Recall thresholds or MLflow champion-challenger metrics), then builds a non-root Docker image tagged with `<git-sha>`, scans it for critical CVEs via Trivy/ECR, and pushes the immutable artifact to Amazon ECR."]}, {"id": "KP3", "description": "Execute Stage 3 (Staging Promotion & Integration/Load Validation): sync to EKS Staging via ArgoCD + Helm and run automated E2E and `<100ms` latency tests.", "required": true, "acceptable_evidence": ["Technical keywords: ArgoCD sync, Helm values-staging.yaml, EKS staging namespace, integration smoke tests, Locust / k6 load test.", "Explains that merging to `main` updates `values-staging.yaml` in the GitOps repo, triggering ArgoCD to deploy the release to the EKS `staging` namespace where automated integration smoke tests (`GET /health`, `POST /predict`) and `k6`/`Locust` p99 latency benchmarks execute."]}, {"id": "KP4", "description": "Execute Stage 4 (Production GitOps Release & Canary Rollout): promote the verified ECR digest to Production with progressive traffic shifting and auto-rollback.", "required": true, "acceptable_evidence": ["Technical keywords: values-prod.yaml promotion, Argo Rollouts Canary (10% -> 50% -> 100%), Prometheus AnalysisRun, automated rollback.", "Explains that once Staging verification succeeds, the exact same ECR SHA digest is promoted to `values-prod.yaml`; ArgoCD / Argo Rollouts shifts production traffic progressively while monitoring Prometheus 5xx error rates, p99 latency, and drift metrics, automatically rolling back if any SLO breaches."]}], "critical_failures": ["Deploys directly from a developer commit to Production without a Staging validation environment or automated evaluation gates.", "Builds separate, unverified container images for Staging and Production instead of promoting the same immutable ECR digest.", "Lacks automated post-deployment health verification and rollback triggers during production rollout."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How did you monitor model performance, latency, and drift in production, and how did you configure alerts for anomalies?', '{"key_points": [{"id": "KP1", "description": "Track real-time and delayed Model Performance using online proxy metrics (prediction confidence, RAG Faithfulness sampling) and delayed ground-truth joins (`PR-AUC`, `FPR @ 90% Recall`).", "required": true, "acceptable_evidence": ["Technical keywords: proxy metrics, prediction score distribution, Langfuse sampled Faithfulness/Relevance, delayed label join, PR-AUC, FPR @ 90% Recall.", "Explains that because true labels in systems like Fraud Detection arrive 30–90 days later via chargebacks, immediate model health is monitored via output probability distributions, positive-flagging rate stability, and analyst override rates (or sampled async DeepEval/RAGAS Faithfulness in RAG), while an automated pipeline joins matured labels to compute exact realized `PR-AUC` and `FPR @ 90% Recall`."]}, {"id": "KP2", "description": "Measure end-to-end and stage-breakdown Tail Latency (`p50`, `p95`, `p99`) using Prometheus histograms and OpenTelemetry/Langfuse spans.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus Histogram, histogram_quantile(0.99), OpenTelemetry spans, Redis lookup latency, model inference latency, TTFT.", "Explains that latency is instrumented both at the FastAPI ingress (`<100ms` p99 SLA) and across sub-stages (Redis feature lookup, `StandardScaler` + `XGBoost` scoring, TreeSHAP explanation, or Milvus retrieval + BGE reranking + Bedrock TTFT) using Prometheus histograms and OpenTelemetry spans."]}, {"id": "KP3", "description": "Monitor covariate Data Drift and Prediction Drift using Evidently AI (`PSI`, `KS-test`, null-rate spikes) against the MLflow training reference.", "required": true, "acceptable_evidence": ["Technical keywords: Evidently AI, PSI (warning > 0.1, critical > 0.2), KS-test, feature null/out-of-range rate, TreeSHAP feature priority.", "Explains that scheduled and streaming Evidently AI jobs compute PSI and two-sample KS-tests on incoming production features and output scores compared to the MLflow training baseline, weighting alerts by top TreeSHAP feature importance."]}, {"id": "KP4", "description": "Configure noise-resistant anomaly alerts in Prometheus Alertmanager / CloudWatch using sustained breach windows, SLO burn rates, and dynamic baselines.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus Alertmanager, sustained window (`for: 5m`), z-score / seasonal baseline, PagerDuty P1 vs Slack P2, automated rollback/retraining.", "Explains that anomaly alerts avoid false alarms by requiring sustained window breaches (`for: 5m–15m`) or multi-window SLO burn rates, routing acute latency/5xx/score-collapse anomalies to PagerDuty (with auto-rollback) and gradual PSI drift warnings to Slack and the retraining pipeline."]}], "critical_failures": ["Relies solely on average (`mean`) latency instead of `p95`/`p99` histogram quantiles, missing severe tail-latency regressions.", "Configures static single-data-point threshold alerts without sustained duration windows (`for: 5m`), flooding on-call engineers with false-positive pages.", "Has no proxy monitoring (prediction distribution or feature PSI) during the weeks before ground-truth labels arrive."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'SPECIFIC', 90, 'How do you ensure API reliability and performance under high load, including strategies like caching, rate limiting, and horizontal scaling?', '{"key_points": [{"id": "KP1", "description": "Implement a Multi-Layer Caching architecture (CloudFront CDN + 4-Tier Redis Cache + Provider KV Prefix Caching) to shed redundant compute.", "required": true, "acceptable_evidence": ["Technical keywords: CloudFront CDN, ElastiCache Redis, query embedding cache, retrieval result cache (1h TTL), semantic response cache, online Feature Store, cache stampede lock.", "Explains the multi-layer caching strategy from the Study Guides: static assets are served at the edge via CloudFront CDN, while backend APIs use ElastiCache Redis for (1) `<5ms` online Feature Store lookups, (2) query embedding caching, (3) Milvus retrieval result caching (1-hour TTL), and (4) semantic/exact response caching, with TTL jitter and single-flight locks to prevent cache stampedes."]}, {"id": "KP2", "description": "Enforce distributed Token-Bucket / Sliding-Window Rate Limiting and Token-Budget Quotas at AWS API Gateway and Redis.", "required": true, "acceptable_evidence": ["Technical keywords: AWS API Gateway usage plans, Redis atomic Lua token bucket / sliding window, per-tenant RPM/TPM quotas, HTTP 429 Too Many Requests, Retry-After header.", "Explains that to prevent noisy-neighbor abuse and protect downstream AWS Bedrock / database quotas, distributed rate limiting is enforced at AWS API Gateway and via atomic Redis Lua scripts by `tenant_id`/`user_id` (bounding both Requests-Per-Minute and LLM Tokens-Per-Minute), returning `HTTP 429` with a `Retry-After` header when exceeded."]}, {"id": "KP3", "description": "Scale stateless FastAPI pods horizontally on Amazon EKS via HPA/KEDA and offload heavy tasks to async Celery workers.", "required": true, "acceptable_evidence": ["Technical keywords: stateless FastAPI, async def I/O, connection pooling, Kubernetes HPA / KEDA, Karpenter, Celery + Redis/SQS async queues.", "Explains that keeping FastAPI pods 100% stateless with non-blocking `async` I/O and pooled DB/Redis connections allows Kubernetes HPA/KEDA and Karpenter to scale replicas seamlessly across AZs on in-flight request concurrency, while long-running work is offloaded to Celery workers."]}, {"id": "KP4", "description": "Protect against cascading failures using strict timeouts, exponential backoff with jitter, circuit breakers, and graceful fallbacks.", "required": true, "acceptable_evidence": ["Technical keywords: per-hop timeouts, exponential backoff with jitter, circuit breaker, Bedrock cross-region / Haiku fallback, load shedding.", "Explains that every external call (Milvus, Redis, Bedrock, MCP tools) enforces strict timeouts and circuit breakers so a slow downstream dependency triggers a fast fallback (e.g., routing to a secondary Bedrock region, cached answer, or rule-based heuristic) rather than exhausting all API worker threads."]}], "critical_failures": ["Implements rate limiting using an in-memory Python dictionary inside each individual pod, which fails completely when traffic is load-balanced across 20 horizontally scaled pods.", "Calls blocking synchronous I/O (`requests.get`, `time.sleep`) inside an `async def` FastAPI route, freezing the entire Uvicorn event loop under load.", "Omits timeouts and circuit breakers on downstream LLM/vector DB calls, allowing a single slow dependency to cause cascading thread/connection exhaustion."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'MEDIUM', 'SPECIFIC', 90, 'How do you ensure code quality and reliability before deploying changes to production in your CI/CD pipeline?', '{"key_points": [{"id": "KP1", "description": "Enforce automated static analysis, formatting, strict type checking, and security scanning (`ruff`, `mypy`, `bandit`, `gitleaks`, `Trivy`) on every Pull Request.", "required": true, "acceptable_evidence": ["Technical keywords: pre-commit hooks, ruff, black, mypy, bandit SAST, pip-audit, gitleaks, Trivy container scan, checkov IaC scan.", "Explains that CI blocks any PR that fails formatting/linting (`ruff`/`black`), static type verification (`mypy`), Python SAST (`bandit`), secret detection (`gitleaks`), dependency/container CVE scanning (`pip-audit`/`Trivy`), or Terraform/Helm linting (`tflint`/`checkov`/`helm lint`)."]}, {"id": "KP2", "description": "Execute a multi-tier Automated Test Pyramid (deterministic unit tests with >=80% coverage, Pydantic contract tests, and containerized integration tests).", "required": true, "acceptable_evidence": ["Technical keywords: pytest, coverage threshold, Pydantic schema contract tests, Testcontainers / ephemeral Redis & Postgres, Feature Store transformation tests.", "Explains that unit tests verify isolated business logic and feature transformations (`StandardScaler`, edge-case null/NaN handling) with deterministic mocks, while integration tests spin up ephemeral service containers to validate FastAPI endpoints (`POST /predict`, `GET /health`), DB migrations, and Redis/Milvus interactions."]}, {"id": "KP3", "description": "Gate AI/ML reliability with automated Golden Dataset evaluation (`DeepEval`/`RAGAS` or `PR-AUC`/`FPR` Champion-Challenger checks) and Staging load tests.", "required": true, "acceptable_evidence": ["Technical keywords: DeepEval, RAGAS, Golden Dataset regression gate, MLflow Champion-Challenger validation, Locust / k6 p99 latency load test.", "Explains that for AI/ML systems, code syntax checks are supplemented by Continuous Calibration (CC/CD): verifying that RAG Faithfulness/Recall or fraud `PR-AUC`/`FPR @ 90% Recall` meets strict thresholds on the Golden Dataset and confirming `<100ms` p99 latency under `k6`/`Locust` load in Staging."]}, {"id": "KP4", "description": "Require protected branch governance (mandatory CODEOWNERS peer review, signed commits, and Staging smoke verification) before Production sync.", "required": false, "acceptable_evidence": ["Technical keywords: branch protection rules, CODEOWNERS review, required status checks, post-deploy smoke test.", "Explains that direct pushes to `main` are prohibited and Production promotion requires green CI status checks, peer review sign-off, and passing Staging smoke tests."]}], "critical_failures": ["Allows developers to merge directly to `main` or bypass failing unit/evaluation checks without branch protection.", "Tests only happy-path inputs in unit tests while ignoring malformed payloads, null features, timeout handling, and AI regression evaluations.", "Skips container vulnerability scanning (`Trivy`) and secret scanning (`gitleaks`) in CI."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'How does horizontal scaling work in Kubernetes, and how does it help handle latency and increased load?', '{"key_points": [{"id": "KP1", "description": "Explain the Kubernetes HorizontalPodAutoscaler (HPA) control loop and desired-replica calculation formula.", "required": true, "acceptable_evidence": ["Technical keywords: HorizontalPodAutoscaler (HPA), Metrics Server, Prometheus Adapter / KEDA, desiredReplicas = ceil(currentReplicas * (currentMetricValue / desiredMetricValue)).", "Explains that the HPA controller queries resource metrics (via `metrics-server`) or custom/external metrics (via Prometheus Adapter or KEDA) every 15 seconds and computes $\\\\text{desiredReplicas} = \\\\lceil \\\\text{currentReplicas} \\\\times (\\\\text{currentMetricValue} / \\\\text{desiredMetricValue}) \\\\rceil$ within configured `minReplicas` and `maxReplicas` bounds."]}, {"id": "KP2", "description": "Scale AI/ML pods on custom concurrency and queue-depth metrics (in-flight requests, p95 latency, Celery/SQS backlog) rather than CPU alone.", "required": true, "acceptable_evidence": ["Technical keywords: custom Prometheus metrics, active in-flight requests, p95 latency, KEDA ScaledObject, Redis/SQS queue depth, GPU utilization (DCGM).", "Explains that LLM/RAG orchestrator pods waiting on AWS Bedrock SSE streams are I/O-bound (low CPU despite saturated worker connections), while model inference pods are compute/GPU-bound; scaling via KEDA/Prometheus on active concurrent requests per pod or Celery queue depth triggers scale-out before latency degrades."]}, {"id": "KP3", "description": "Explain how distributing load across additional stateless pods eliminates worker queueing delay ($M/M/c$ queueing theory) to protect p99 tail latency.", "required": true, "acceptable_evidence": ["Technical keywords: queueing delay vs service time, Uvicorn worker saturation, AWS ALB target group registration, readinessProbe gate, <100ms p99 SLA.", "Explains that while horizontal scaling does not make a single model forward pass faster, it prevents incoming requests from piling up in Uvicorn/Triton queues when RPS surges; once new pods pass their `readinessProbe` (after loading the MLflow model into memory), the ALB/Service immediately distributes requests across the expanded pod pool to keep p99 latency `<100ms`."]}, {"id": "KP4", "description": "Pair Pod Autoscaling (HPA/KEDA) with Node Autoscaling (Karpenter) and asymmetric scale-up/scale-down stabilization windows.", "required": true, "acceptable_evidence": ["Technical keywords: Karpenter, Pending pods, stabilizationWindowSeconds, fast scale-up, gradual scale-down, thrashing/flapping prevention.", "Explains that when HPA creates pods that exceed current EC2 node capacity (`Pending`), Karpenter provisions new right-sized EC2 nodes in seconds, while HPA `behavior.scaleDown.stabilizationWindowSeconds` (e.g., `300s`) prevents rapid pod thrashing on bursty traffic."]}], "critical_failures": ["Claims that horizontal scaling reduces the single-request compute execution time of a single sequential model forward pass when there is no queueing contention.", "Configures HPA without setting pod resource `requests` or `readinessProbe`s, causing Kubernetes to fail utilization math or route live traffic to cold pods before model weights load.", "Uses HPA without a node autoscaler (Karpenter / Cluster Autoscaler), leaving scaled-out pods stuck in `Pending` state when cluster nodes fill up."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How have you applied A/B testing and monitoring to evaluate and improve the performance of ML or generative AI systems in production?', '{"key_points": [{"id": "KP1", "description": "Design controlled online Champion-Challenger A/B experiments with sticky user/session assignment and explicit hypothesis metrics.", "required": true, "acceptable_evidence": ["Technical keywords: Champion-Challenger A/B test, sticky hash(user_id), statistical power, minimum detectable effect (MDE), Langfuse prompt/model experiment.", "Explains how candidate improvements—such as upgrading from Phase 1 Logistic Regression to Phase 2 XGBoost in Fraud Detection, or testing BGE Cross-Encoder reranking vs. pure vector search in RAG—are exposed to a controlled traffic slice (e.g., 80% Control / 20% Treatment) using deterministic `user_id`/`tenant_id` hashing."]}, {"id": "KP2", "description": "Evaluate both primary quality/business KPIs and operational guardrail metrics (`p99` latency, token cost, guardrail blocks) per variant.", "required": true, "acceptable_evidence": ["Technical keywords: primary KPI (PR-AUC, resolution rate, thumbs-up rate, Faithfulness), guardrail metrics (p99 latency <100ms, TTFT, USD cost/query, 5xx errors).", "Explains that every response logs `model_version` / `prompt_version` and `trace_id` to Langfuse and Prometheus, allowing the team to verify statistically significant gains ($p < 0.05$) on primary quality metrics (realized `PR-AUC`, call-center deflection rate, sampled RAGAS Faithfulness) without violating latency or token-cost guardrails."]}, {"id": "KP3", "description": "Use production monitoring (Evidently AI drift reports and Langfuse failure cluster analysis) to surface systematic bottlenecks and drive the next iteration.", "required": true, "acceptable_evidence": ["Technical keywords: Evidently AI slice drift, Langfuse low-score trace clustering, Golden Dataset expansion, iterative CC/CD improvement.", "Explains how continuous monitoring drives iterative improvement: inspecting low-Faithfulness or high-override clusters in Langfuse/Evidently AI reveals concrete failure modes (e.g., broken table formatting in PDFs or a new merchant fraud pattern), which are added to the Golden Dataset and used to engineer the next A/B challenger."]}], "critical_failures": ["Promotes a new prompt or model based solely on 10 ad-hoc manual tests without measuring statistical significance or production guardrail metrics.", "Evaluates an A/B test only on accuracy while ignoring that the Challenger model doubled p99 latency or tripled LLM token costs.", "Splits multi-turn conversational sessions randomly per turn rather than deterministically per `user_id`/`session_id`."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'SPECIFIC', 90, 'How have you handled model inference and deployment, and what is your familiarity with inference servers like NVIDIA Triton?', '{"key_points": [{"id": "KP1", "description": "Serve lightweight CPU/tabular models (`XGBoost`, `scikit-learn`) via stateless FastAPI + `ONNX Runtime` with pre-loaded MLflow artifacts and `<100ms` latency.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI lifespan pre-loading, mlflow.pyfunc, ONNX Runtime, Redis online Feature Store, <100ms p99 SLA.", "Explains that for low-footprint tabular models (such as the Fraud Detection Study Guide''s `LogisticRegression` / `XGBoost`), loading the serialized MLflow pipeline (`StandardScaler` + model) into memory at FastAPI startup alongside `<5ms` Redis Feature Store lookups achieves `<20–50ms` latency on CPU pods without GPU overhead."]}, {"id": "KP2", "description": "Leverage NVIDIA Triton Inference Server for high-throughput GPU/CPU serving via Dynamic Batching, Concurrent Model Execution, and Multi-Backend support.", "required": true, "acceptable_evidence": ["Technical keywords: NVIDIA Triton Inference Server, config.pbtxt, dynamic_batching, max_queue_delay_microseconds, instance_group, TensorRT, ONNX, PyTorch, Model Analyzer.", "Explains how NVIDIA Triton optimizes deep learning and reranker/embedding inference (e.g., BGE Cross-Encoder, vision, or custom neural models): Triton''s C++ core bypasses the Python GIL, groups individual HTTP/gRPC requests on the fly via `dynamic_batching` (`preferred_batch_size`, `max_queue_delay_microseconds`), runs multiple `instance_group`s concurrently on a single GPU, and executes `Model Ensembles` (preprocessing -> TensorRT model -> postprocessing) in shared memory."]}, {"id": "KP3", "description": "Use specialized LLM serving engines (`vLLM` / `TensorRT-LLM` with PagedAttention and Continuous Batching) or managed AWS Bedrock for generative workloads.", "required": true, "acceptable_evidence": ["Technical keywords: vLLM, TensorRT-LLM, Triton vLLM/TensorRT-LLM backend, PagedAttention, continuous (in-flight) batching, KV cache.", "Explains that autoregressive LLMs require iteration-level continuous batching and PagedAttention (`vLLM` or Triton''s `TensorRT-LLM` backend) so completed sequences exit the batch immediately and new requests join mid-generation without padding waste."]}, {"id": "KP4", "description": "Deploy and autoscale inference servers on Amazon EKS with gRPC/HTTP health checks and DCGM GPU metrics.", "required": false, "acceptable_evidence": ["Technical keywords: gRPC / HTTP v2 KServe protocol, /v2/health/ready, NVIDIA DCGM Exporter, Prometheus HPA/KEDA.", "Explains that Triton/vLLM pods run on EKS GPU node groups (`g5`/`g6`), expose `/v2/health/ready` for Kubernetes readiness probes, and autoscale via HPA/KEDA on Prometheus GPU duty-cycle and inference queue time metrics."]}], "critical_failures": ["Wraps a heavy GPU deep learning model inside a single-threaded Python Flask/FastAPI loop with batch size 1, leaving GPU compute utilization under 10% and bottlenecking on the Python GIL.", "Cannot explain how NVIDIA Triton''s `dynamic_batching` or `instance_group` concurrency works.", "Reloads model weights from disk/S3 on every inference request instead of serving from resident GPU/CPU memory."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'HARD', 'SPECIFIC', 120, 'How would you approach productionizing a pre-trained model into a microservice, including containerization, CI/CD integration, and deployment using tools like Docker, ECR, and ArgoCD?', '{"key_points": [{"id": "KP1", "description": "Wrap the pre-trained model artifact (`MLflow` / `ONNX`) in a stateless FastAPI microservice with strict Pydantic contracts, lifespan model pre-loading, and `/health` + `/metrics` endpoints.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, lifespan context manager, Pydantic input/output validation, POST /predict, GET /health, GET /metrics, model_version.", "Explains that productionizing a pre-trained model begins by registering the serialized pipeline (`StandardScaler` + model weights) in MLflow/S3 and building a stateless FastAPI service that loads the artifact once during the `lifespan` startup hook, enforces strict Pydantic request/response schemas (returning `prediction`, `probability`, `explanation`, `model_version`), and exposes `/health` and Prometheus `/metrics`."]}, {"id": "KP2", "description": "Containerize the microservice with a multi-stage, non-root `Dockerfile` and locked dependencies (`poetry.lock` / `requirements.txt`).", "required": true, "acceptable_evidence": ["Technical keywords: multi-stage Dockerfile, python:3.11-slim, non-root user, pinned lockfile, Uvicorn/Gunicorn workers, .dockerignore.", "Explains that a multi-stage `Dockerfile` compiles dependencies in a builder stage, copies only the virtual environment and application code into a minimal runtime image running as a non-root user, and configures Uvicorn/Gunicorn worker processes."]}, {"id": "KP3", "description": "Automate CI testing, model evaluation gates, Trivy CVE scanning, and immutable image publishing to Amazon ECR.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub Actions CI, pytest unit/contract tests, golden-sample inference verification, Trivy scan, Amazon ECR, Git SHA tag.", "Explains that GitHub Actions CI runs `ruff`/`mypy`, `pytest` schema and golden-input inference parity tests, builds the Docker image tagged with `<git-sha>`, scans it for vulnerabilities with Trivy, and pushes it to Amazon ECR via OIDC authentication."]}, {"id": "KP4", "description": "Deploy declaratively to Amazon EKS using Helm charts and ArgoCD GitOps with `startupProbe`/`readinessProbe` and progressive Canary rollout.", "required": true, "acceptable_evidence": ["Technical keywords: Helm chart, values-staging.yaml, values-prod.yaml, ArgoCD Application, startupProbe, readinessProbe, Argo Rollouts Canary, automated rollback.", "Explains that CI updates the image SHA tag in the GitOps repository (`values-staging.yaml` -> `values-prod.yaml`); ArgoCD detects the Git commit, renders the Helm chart onto Amazon EKS, waits for `startupProbe`/`readinessProbe` (`GET /health`) to confirm the model is loaded in memory, and executes a Canary rollout with automatic rollback if Prometheus 5xx or `<100ms` p99 latency SLOs breach."]}], "critical_failures": ["Loads the pre-trained model from disk or S3 inside the `POST /predict` request handler on every API call instead of pre-loading at container startup.", "Pushes an untested, root-user `:latest` image to ECR and runs `kubectl apply` manually without health probes or GitOps rollback.", "Omits Pydantic input validation, allowing malformed or missing feature fields to crash the model worker with unhandled 500 errors."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How would you debug and resolve issues in a production ML system, including monitoring, logging, and handling data drift?', '{"key_points": [{"id": "KP1", "description": "Triage and contain the incident immediately by distinguishing Infrastructure/Code failures from Data Pipeline bugs and Model/Concept Drift.", "required": true, "acceptable_evidence": ["Technical keywords: incident triage, blast-radius containment, ArgoCD / MLflow rollback, Infrastructure vs Data vs Model failure.", "Explains that step one of production debugging is checking whether the anomaly (e.g., spike in 5xx errors, p99 latency $>100\\\\text{ms}$, or fraud flagging rate jumping from $0.1\\\\%$ to $15\\\\%$) correlated with a recent code/model deployment; if a recent release caused the regression, immediately roll back via ArgoCD / MLflow `@production` alias to stabilize production before deep-diving."]}, {"id": "KP2", "description": "Trace request-level failures using correlated Prometheus/Grafana metrics, OpenTelemetry/Langfuse `trace_id` spans, and structured CloudWatch JSON logs.", "required": true, "acceptable_evidence": ["Technical keywords: trace_id correlation, model_version tag, CloudWatch Logs Insights, Langfuse trace tree, Redis Feature Store timeout/null check.", "Explains how to pinpoint the exact failing component: using Prometheus Exemplars in Grafana to grab a failing `trace_id`, inspecting the structured JSON logs in CloudWatch (filtered by `trace_id` and `model_version`) and spans in Langfuse/OpenTelemetry to see whether the failure occurred in Redis feature retrieval (e.g., cache miss returning `None`/zeros), `StandardScaler` transformation, model scoring, or an external Bedrock/tool call."]}, {"id": "KP3", "description": "Diagnose feature & prediction anomalies using Evidently AI (`PSI`, `KS-test`, null-rate & schema checks) and TreeSHAP attributions.", "required": true, "acceptable_evidence": ["Technical keywords: Evidently AI, PSI > 0.2, KS-test, upstream data corruption vs genuine market drift, TreeSHAP feature attribution shift.", "Explains how to debug silent model degradation: inspecting Evidently AI reports and TreeSHAP explanations to determine whether a single corrupted upstream feature (e.g., an upstream currency unit change or broken ETL sending `0.0` for `transaction_velocity_24h`) is driving skewed predictions, or whether multiple features shifted organically due to real-world market/behavioral drift."]}, {"id": "KP4", "description": "Execute targeted remediation (fix broken upstream ETL & backfill Redis vs. retrain/recalibrate on matured DVC data) and add regression guards.", "required": true, "acceptable_evidence": ["Technical keywords: upstream ETL fix, Redis Feature Store backfill, probability threshold recalibration, DVC + MLflow retraining, post-mortem test case.", "Explains that resolution matches the root cause: upstream data bugs are fixed at the source with stricter Pydantic/Great Expectations ingress validation and Redis backfill; genuine data/concept drift is resolved by recalibrating decision thresholds and retraining a challenger model on recent matured DVC data in MLflow, followed by adding the failure scenario to the CI regression suite."]}], "critical_failures": ["Immediately retrains the model on recent production data when predictions spike, without first checking if an upstream data pipeline bug is feeding corrupted/null features into the model.", "Lacks structured logging of input features, `model_version`, and `trace_id`, making it impossible to reproduce why the model made a specific erroneous prediction.", "Leaves a broken model serving live traffic for hours while debugging instead of rolling back or activating a fallback heuristic."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'SPECIFIC', 90, 'How would you design a production-ready API for fraud prediction, including endpoints and deployment considerations?', '{"key_points": [{"id": "KP1", "description": "Design RESTful FastAPI endpoints (`POST /v1/predict`, `POST /v1/predict/batch`, `GET /health`) with strict Pydantic request/response contracts and idempotency keys.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, POST /predict, GET /health, Pydantic BaseModel, Idempotency-Key, prediction, probability, explanation (top 3 SHAP features), model_version.", "Explains the exact API contract from the Fraud Detection Study Guide: `POST /predict` accepts validated transaction attributes (`transaction_id`, `user_id`, `merchant_id`, `amount`, `timestamp`, plus an `Idempotency-Key` header to prevent duplicate scoring on payment gateway retries) and returns `{prediction: 0|1, probability: float, explanation: [top_3_shap_features], model_version: str, trace_id: str}`, while `GET /health` verifies model-in-memory and Redis connectivity for Kubernetes probes."]}, {"id": "KP2", "description": "Achieve `<100ms` p99 end-to-end latency via lifespan model pre-loading and `<5ms` ElastiCache Redis Online Feature Store enrichment.", "required": true, "acceptable_evidence": ["Technical keywords: <100ms p99 SLA, FastAPI lifespan hook, MLflow Production model in RAM, ElastiCache Redis pipeline, StandardScaler + XGBoost, pre-computed TreeSHAP.", "Explains that the caller sends only raw transaction event fields; the FastAPI handler fetches pre-aggregated user/merchant velocity features from the Redis Online Feature Store in `<5ms`, applies the in-memory `StandardScaler` + `XGBoost` pipeline and fast `TreeSHAP` top-3 feature attribution, and responds well within the `<100ms` payment authorization SLA."]}, {"id": "KP3", "description": "Implement graceful degradation, circuit breakers, and asynchronous audit/drift telemetry so payment processing is never blocked.", "required": true, "acceptable_evidence": ["Technical keywords: circuit breaker, deterministic fallback rules, asynchronous Kafka/SQS/BackgroundTasks telemetry, Presidio PII masking.", "Explains that if Redis times out (`>15ms`), a circuit breaker falls back to payload-only features or a fast deterministic velocity rule so checkout never hangs, while full feature/prediction audit logs are emitted asynchronously off the critical path to CloudWatch and Evidently AI."]}, {"id": "KP4", "description": "Deploy stateless containers on multi-AZ Amazon EKS via Docker/ECR, Helm, and ArgoCD with HPA autoscaling and Canary rollouts.", "required": true, "acceptable_evidence": ["Technical keywords: Docker, Amazon ECR, Amazon EKS, Helm, ArgoCD, startupProbe/readinessProbe, HPA, Shadow/Canary deployment.", "Explains that the API runs as a non-root Docker container across multi-AZ EKS nodes behind AWS API Gateway (mTLS/JWT auth) and ALB, using `startupProbe`/`readinessProbe` on `GET /health`, HPA autoscaling, and Shadow/Canary traffic shifting for new MLflow model versions."]}], "critical_failures": ["Requires the payment gateway client to compute and pass 50 historical rolling database aggregations in the `POST /predict` request body instead of enriching features server-side from an Online Feature Store.", "Returns only a bare `0` or `1` integer without `probability`, top-3 SHAP `explanation`, or `model_version`, failing regulatory explainability and auditability requirements.", "Queries a slow relational database synchronously on the request path or loads the model from disk per request, breaching the `<100ms` payment SLA."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'How would you design a system to identify which stage of the pipeline (ingestion, preprocessing, model, deployment) is responsible for failures?', '{"key_points": [{"id": "KP1", "description": "Propagate a unified OpenTelemetry `trace_id` with stage-specific child spans (`ingestion`, `preprocessing`, `retrieval/feature_lookup`, `model_inference`, `postprocessing`) across the entire pipeline.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry W3C TraceContext, Langfuse spans, stage-level latency/status attribution, structured error taxonomy.", "Explains that wrapping every distinct pipeline stage in its own instrumented span with standardized status codes (`STAGE_INGESTION_ERR`, `STAGE_PREPROC_SCHEMA_ERR`, `STAGE_MODEL_TIMEOUT`, `STAGE_DEPLOY_OOM`) immediately reveals which stage threw an exception or consumed the latency budget."]}, {"id": "KP2", "description": "Enforce deterministic Data & Schema Contracts at every stage boundary (Great Expectations / Pandera / Pydantic) to catch silent corruption at the source.", "required": true, "acceptable_evidence": ["Technical keywords: stage boundary contracts, Great Expectations / Pandera, Pydantic validation, NaN/Inf assertion, vector norm check.", "Explains how boundary assertions prevent silent failure propagation: (1) **Ingestion -> Preprocessing**: verify file integrity, non-empty Docling text extraction, or raw S3 schema completeness; (2) **Preprocessing -> Model**: assert zero unexpected `NaN`/`Inf` values after `StandardScaler`, valid feature dimensionality, or non-zero embedding vector norms; and (3) **Model -> Deployment API**: validate output probability bounds ($[0, 1]$) or strict JSON Schema compliance."]}, {"id": "KP3", "description": "Build a Decoupled Diagnostic Evaluation Matrix that isolates Retrieval/Preprocessing degradation from Model/Generation failures.", "required": true, "acceptable_evidence": ["Technical keywords: diagnostic isolation matrix, Recall@K / MRR vs Faithfulness (RAG), Feature PSI vs Residual/Calibration error (ML), synthetic canary probes.", "Explains how quality failures are attributed to the exact stage: in RAG (Study Guides), low Answer Correctness + low `Recall@K` isolates an **Ingestion/Chunking/Retrieval** failure, whereas high `Recall@K` + low `Faithfulness` isolates a **Model/Prompt** failure; in tabular ML (Fraud Study Guide), high feature `PSI`/null rate before scaling isolates an **Ingestion/Feature Store** bug, whereas stable pre-scaled features + corrupted post-scaler values isolates a **Preprocessing** bug, and stable features + degraded `PR-AUC` isolates **Model Concept Drift**."]}, {"id": "KP4", "description": "Run synthetic Golden Canary Probes against the deployed endpoint to separate Deployment/Infrastructure regressions from data-driven issues.", "required": true, "acceptable_evidence": ["Technical keywords: synthetic canary probe, golden input vector, deterministic output assertion, Prometheus infrastructure metrics (OOMKilled, 502/504, ECR digest).", "Explains that periodically sending a fixed, known golden input payload through the live endpoint isolates **Deployment/Infrastructure** issues: if the golden input suddenly fails, times out (`504`), or returns a different score than in Staging, the fault lies in the deployment environment (wrong ECR image/model version, missing env var, or pod saturation) rather than live input data."]}], "critical_failures": ["Measures only end-to-end final output accuracy or HTTP 500 rates at the outer API gateway with zero intermediate stage spans or boundary schema checks.", "Allows an ingestion failure (such as an empty PDF parse or all-null Redis lookup) to silently pass empty strings or zeros into the model without raising a stage-specific contract error.", "Cannot distinguish between a retrieval/feature-pipeline failure and a model inference failure."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'HARD', 'BROAD', 210, 'How would you design an end-to-end fraud detection system, including data, model, and deployment layers?', '{"key_points": [{"id": "KP1", "description": "Architect the Data & Dual-Layer Feature Store Layer (DVC + S3/Parquet offline store + Redis online store) with point-in-time joins and label-maturity windows.", "required": true, "acceptable_evidence": ["Technical keywords: S3/Parquet offline store, ElastiCache Redis online store, DVC versioning, point-in-time correctness, label-maturity window (delayed chargebacks), rolling velocity features.", "Explains the Data Layer from the Fraud Detection Study Guide: raw transaction streams and historical chargeback logs land in S3 and are versioned with DVC; to prevent data leakage from 30–90 day delayed chargebacks, training snapshots enforce a label-maturity window and point-in-time joins, while shared transformation logic computes rolling velocity/behavioral features (e.g., 1h/24h transaction counts, amount z-score vs. user history, geo-distance) into both S3/Parquet (offline) and Redis (`<5ms` online lookup)."]}, {"id": "KP2", "description": "Design the Training & Experimentation Layer handling extreme class imbalance (`0.1%` fraud) and chronological splits across Phase 1 (`LogisticRegression`) and Phase 2 (`XGBoost` + `TreeSHAP`).", "required": true, "acceptable_evidence": ["Technical keywords: 0.1% class imbalance, majority down-sampling, class_weight=''balanced'' / scale_pos_weight, chronological split (Jan-Mar train / Apr test), sklearn.pipeline.Pipeline, StandardScaler, LogisticRegression (L2 C GridSearch), XGBoost, TreeSHAP.", "Explains the Modeling Layer: strictly chronological train/validation/test splits prevent temporal leakage; extreme `0.1%` fraud imbalance is handled via majority down-sampling and cost-sensitive weights (`class_weight=''balanced''` / `scale_pos_weight`); Phase 1 establishes an interpretable `StandardScaler` + L2 `LogisticRegression` baseline, while Phase 2 deploys gradient-boosted `XGBoost` trees paired with `TreeSHAP` to extract the top 3 feature attributions per prediction."]}, {"id": "KP3", "description": "Evaluate and govern models in MLflow using imbalanced business metrics (`PR-AUC`, `FPR @ 90% Recall`) rather than raw accuracy.", "required": true, "acceptable_evidence": ["Technical keywords: PR-AUC (Precision-Recall AUC), FPR @ 90% Recall, cost-sensitive decision thresholding, MLflow Tracking Server (RDS + S3), MLflow Model Registry (Staging -> Validation -> Production).", "Explains that because a naive all-zero classifier achieves `99.9%` accuracy on `0.1%` fraud data, models are selected and gated in the MLflow Model Registry strictly on `PR-AUC` and `FPR @ 90% Recall` (minimizing false declines of legitimate customers while catching 90% of fraud)."]}, {"id": "KP4", "description": "Architect the Stateless Online Inference & Deployment Layer (`FastAPI` on `Amazon EKS` via `Docker`/`ECR`/`Helm`/`ArgoCD`) meeting a `<100ms` p99 SLA.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, POST /predict, GET /health, <100ms p99 SLA, prediction, probability, explanation, model_version, Docker, Amazon ECR, Amazon EKS, Helm, ArgoCD Canary rollout.", "Explains that the stateless FastAPI service pre-loads the `Production` MLflow pipeline in memory, enriches incoming `POST /predict` requests from Redis in `<5ms`, and returns `prediction`, `probability`, top-3 SHAP `explanation`, and `model_version` in `<100ms`, deployed on multi-AZ Amazon EKS via Helm and ArgoCD with Shadow/Canary traffic shifting."]}, {"id": "KP5", "description": "Close the Production Monitoring & Retraining Loop using Prometheus/Grafana, Evidently AI (`PSI`/`KS-test` & prediction drift), and delayed chargeback feedback.", "required": true, "acceptable_evidence": ["Technical keywords: Prometheus, Grafana, Evidently AI, PSI, KS-test, prediction probability drift proxy, delayed chargeback join, automated retraining trigger.", "Explains that Prometheus/Grafana monitor p99 latency and 5xx rates, while Evidently AI tracks feature drift (`PSI`, `KS-test`) and output probability score drift as an early proxy before delayed chargeback labels arrive to compute realized `PR-AUC` and trigger automated retraining."]}], "critical_failures": ["Uses raw accuracy or random `train_test_split` on `0.1%` imbalanced time-series fraud transactions.", "Computes historical user velocity features via slow synchronous SQL queries during `POST /predict` instead of using an Online Feature Store (Redis), violating the `<100ms` SLA.", "Trains on the most recent transactions without accounting for the 30–90 day chargeback label-maturity delay, treating unconfirmed fraud as legitimate transactions."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'SPECIFIC', 120, 'How would you design and implement a pipeline to process and extract structured data from large unstructured PDF documents?', '{"key_points": [{"id": "KP1", "description": "Architect an asynchronous, event-driven ingestion pipeline (`S3` -> `SQS`/`Celery` workers) with SHA-256 content deduplication and PII/PHI scrubbing (`Presidio`).", "required": true, "acceptable_evidence": ["Technical keywords: Amazon S3, EventBridge / SQS, Celery async workers, SHA-256 document hash deduplication, Microsoft Presidio PII/PHI redaction.", "Explains that uploading large PDFs (e.g., 100+ page Medicaid clinical manuals, call-center SOPs, or resumes in the Study Guides) to Amazon S3 triggers asynchronous Celery/SQS worker jobs that compute a SHA-256 file hash to skip unchanged documents and scrub sensitive PII/PHI via Microsoft Presidio."]}, {"id": "KP2", "description": "Perform layout-aware document parsing and table/OCR reconstruction using `Docling` (with fallback OCR) into hierarchical Markdown/JSON.", "required": true, "acceptable_evidence": ["Technical keywords: Docling, layout analysis, bounding boxes, table structure recognition (Markdown/HTML tables), multi-column reading order, OCR fallback (Textract / Tesseract).", "Explains that naive `PyPDF2` text extraction scrambles multi-column layouts and destroys tables; instead, the pipeline uses `Docling` (as detailed across the RAG Study Guides) to detect page layout geometry, preserve section hierarchy (`H1 -> H2 -> H3`), reconstruct complex tables into structured Markdown/JSON, and invoke OCR on scanned pages."]}, {"id": "KP3", "description": "Apply structure-aware Semantic Chunking (`200–500` tokens with `10–20%` overlap) enriched with document provenance metadata.", "required": true, "acceptable_evidence": ["Technical keywords: semantic / hierarchical chunking, 200-500 tokens, 10-20% overlap, table integrity preservation, metadata attachment (doc_id, page_number, section_header, effective_date, tenant_id).", "Explains that parsed documents are split along structural boundaries (`200–500` tokens with `10–20%` overlap while keeping tables and atomic clauses intact) and every chunk is stamped with rich metadata (`doc_id`, `page_number`, `section_path`, `effective_date`, `access_role`) before indexing into Milvus (HNSW) and BM25."]}, {"id": "KP4", "description": "Extract deterministic structured records using Constrained Decoding / Pydantic schemas (`Instructor` / Bedrock Structured Outputs) with confidence & citation validation.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic schema extraction, constrained decoding / tool calling, source page/bbox citation grounding, validation-repair loop, human-in-the-loop review queue.", "Explains that when extracting structured database records (e.g., candidate skills/experience in TalentScreen or eligibility rules in Healthcare RAG), the LLM is called at `temperature=0` with a strict Pydantic JSON Schema requiring source `page_number` and verbatim quote evidence for every extracted field, routing low-confidence or validation-failing records to a human review queue."]}], "critical_failures": ["Parses complex multi-column PDFs and financial/clinical tables using naive character-count splitting (`PyPDF2` + fixed 1000-char slices), slicing table rows in half and destroying header context.", "Passes an entire 300-page PDF into a single synchronous HTTP request on the main FastAPI web thread instead of processing asynchronously via Celery/SQS workers.", "Extracts structured fields via free-form text prompting (`''Return JSON''`) without Pydantic schema validation or source page citations."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would you design the system to handle continuous data updates and ensure the pipeline is triggered when new data arrives?', '{"key_points": [{"id": "KP1", "description": "Trigger pipelines automatically via Event-Driven Architecture (`S3 Event Notifications` -> `EventBridge` -> `SQS` / `Kafka`) rather than blind full-table polling.", "required": true, "acceptable_evidence": ["Technical keywords: S3 Event Notifications (s3:ObjectCreated:*, s3:ObjectRemoved:*), Amazon EventBridge, Amazon SQS / Kafka, Celery workers, micro-batch windowing.", "Explains that when new documents or transaction batches land in Amazon S3 (or CDC streams arrive from databases), `s3:ObjectCreated:*` events route through Amazon EventBridge into an SQS queue (with micro-batch debounce/windowing to prevent triggering 10,000 separate training jobs on single-record uploads) consumed by Celery/Airflow workers."]}, {"id": "KP2", "description": "Enforce idempotent, incremental delta processing using content hashing (`SHA-256` / `ETag`) and deterministic upserts.", "required": true, "acceptable_evidence": ["Technical keywords: idempotency, SHA-256 content hash, chunk-level diffing, Milvus upsert / soft-delete, Redis Feature Store incremental update.", "Explains that because cloud events guarantee at-least-once delivery, workers check the document/chunk `SHA-256` hash in PostgreSQL/RDS metadata first: unchanged records are skipped, modified RAG documents re-embed only changed chunks and upsert/tombstone old vectors in Milvus, and streaming transactions incrementally update rolling Redis Feature Store counters."]}, {"id": "KP3", "description": "Validate incoming data quality at ingress and execute zero-downtime index/cache invalidation and DVC snapshot versioning.", "required": true, "acceptable_evidence": ["Technical keywords: Great Expectations / Pydantic ingress validation, Redis cache invalidation, Milvus collection alias swap, DVC snapshot.", "Explains that continuous updates pass schema/null checks before mutating state, selectively invalidate stale entries in the Redis retrieval/response cache, and periodically commit new matured dataset snapshots to DVC to trigger scheduled or drift-driven model retraining."]}], "critical_failures": ["Re-embeds and rebuilds the entire multi-million-chunk Milvus vector database from scratch every time a single 2-page PDF is updated.", "Lacks idempotency checks on `s3:ObjectCreated` events, creating duplicate vector chunks or double-counting transaction features when SQS delivers a message twice.", "Updates the underlying vector index or feature store without invalidating stale cached responses in Redis."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'SPECIFIC', 90, 'How would you handle failures in asynchronous pipelines, and what retry or timeout strategies would you implement?', '{"key_points": [{"id": "KP1", "description": "Classify errors into Retryable Transient Failures (`HTTP 429`, `502/503/504`, network timeouts) vs. Non-Retryable Permanent Failures (`HTTP 400`, validation errors, corrupt files).", "required": true, "acceptable_evidence": ["Technical keywords: transient vs permanent errors, Bedrock ThrottlingException (HTTP 429), HTTP 503, HTTP 400 Bad Request, Pydantic ValidationError.", "Explains that retrying a permanent error (e.g., malformed JSON, corrupt password-protected PDF, or invalid schema) wastes compute and clogs queues; workers fail fast on permanent `4xx`/validation errors while scheduling retries strictly for transient `429`/`5xx`/network timeout errors."]}, {"id": "KP2", "description": "Implement bounded Exponential Backoff with Full Jitter (`t = random(0, min(cap, base * 2^attempt))`) and honor `Retry-After` headers.", "required": true, "acceptable_evidence": ["Technical keywords: exponential backoff with full jitter, max_retries (3-5), Retry-After header, thundering herd prevention, Celery autoretry_for.", "Explains that immediate or fixed-interval retries from hundreds of concurrent Celery/async workers create a synchronized ''thundering herd'' that amplifies downstream outages (e.g., AWS Bedrock rate limits); using capped exponential backoff (`base=1s, factor=2, max=60s`, `max_retries=3..5`) with randomized jitter spreads retry load evenly."]}, {"id": "KP3", "description": "Configure two-tier Timeouts (per-call connect/read timeouts + overall task `soft_time_limit`/`time_limit`) and late message acknowledgment (`acks_late=True`).", "required": true, "acceptable_evidence": ["Technical keywords: connect timeout, read timeout, Celery soft_time_limit / time_limit, SQS visibility_timeout, task_acks_late=True.", "Explains that every external network call (Bedrock, Milvus, Redis, Docling OCR) sets explicit connect/read timeouts, while Celery/SQS tasks enforce `soft_time_limit` (to catch `SoftTimeLimitExceeded` and clean up gracefully) and `acks_late=True` so a worker `OOMKilled` mid-task returns the message to the queue rather than losing it."]}, {"id": "KP4", "description": "Guarantee idempotent task execution, checkpoint partial progress, and route exhausted tasks to a Dead-Letter Queue (DLQ) with alerting.", "required": true, "acceptable_evidence": ["Technical keywords: idempotency key, stage checkpointing, Dead-Letter Queue (DLQ), maxReceiveCount, redrive policy, CloudWatch/Prometheus DLQ alarm.", "Explains that because retries cause tasks to execute multiple times, database/vector writes use deterministic idempotency keys (`doc_id#chunk_idx`) and checkpoint completed sub-steps (so a failed embedding step doesn''t re-run expensive Docling OCR), while messages exceeding `max_retries` move to a DLQ (`maxReceiveCount`) that triggers an engineer alert and replay runbook."]}], "critical_failures": ["Uses infinite `while True:` retry loops or zero-delay retries without exponential backoff and jitter, causing self-inflicted DDoS / thundering herd outages.", "Acknowledges and deletes messages from the queue *before* the async worker finishes processing (`acks_late=False`), permanently losing tasks whenever a pod crashes or scales down.", "Retries non-idempotent operations (like appending duplicate rows or charging a card) without an idempotency key."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'HARD', 'SPECIFIC', 120, 'How would you structure the training and evaluation pipeline for a classification model, including data splitting and performance measurement?', '{"key_points": [{"id": "KP1", "description": "Design leakage-free Data Splitting (Chronological Out-of-Time splits with label-maturity windows for temporal data, or Stratified Group splits for i.i.d. data).", "required": true, "acceptable_evidence": ["Technical keywords: chronological / out-of-time split (Jan-Mar train / Apr test), label-maturity window, StratifiedGroupKFold, entity-level grouping (user_id).", "Explains from the Fraud Detection Study Guide that random `train_test_split` on temporal transaction data leaks future patterns into the past; instead, the pipeline uses a strict chronological split (e.g., Jan–Mar for training/validation, April for holdout test) after accounting for the label-maturity window, or `StratifiedGroupKFold` grouped by `user_id` when data is non-temporal."]}, {"id": "KP2", "description": "Encapsulate all stateful preprocessing (`StandardScaler`, imputation, target/categorical encoding) inside `sklearn.pipeline.Pipeline` fitted strictly on `X_train`.", "required": true, "acceptable_evidence": ["Technical keywords: sklearn.pipeline.Pipeline, ColumnTransformer, StandardScaler.fit(X_train), StandardScaler.transform(X_val/X_test), zero statistical leakage.", "Explains that all preprocessing transformers (`SimpleImputer`, `StandardScaler`, `OneHotEncoder`) and resampling/down-sampling steps are executed strictly inside the training fold (`fit_transform(X_train)` and `transform(X_val)`/`transform(X_test)`), never on the full dataset prior to splitting."]}, {"id": "KP3", "description": "Address class imbalance (`0.1%` positive rate) via cost-sensitive learning (`class_weight=''balanced''`, `scale_pos_weight`) and training-fold-only down-sampling.", "required": true, "acceptable_evidence": ["Technical keywords: 0.1% class imbalance, majority down-sampling on train only, class_weight=''balanced'', XGBoost scale_pos_weight, unmodified validation/test distribution.", "Explains that while the training fold uses majority down-sampling or `class_weight=''balanced''` / `scale_pos_weight` to prevent gradient domination by the `99.9%` negative class, the validation and test sets must preserve the true unmodified production class distribution (`0.1%`)."]}, {"id": "KP4", "description": "Evaluate and tune decision thresholds using `PR-AUC`, `FPR @ Target Recall` (e.g., `FPR @ 90% Recall`), cost matrices, and probability calibration.", "required": true, "acceptable_evidence": ["Technical keywords: PR-AUC (Average Precision), FPR @ 90% Recall, Precision-Recall curve threshold tuning, Brier score / Platt / Isotonic calibration, TreeSHAP.", "Explains why raw accuracy and even `ROC-AUC` are misleading under severe class imbalance (since huge false-positive spikes barely move $FPR = FP / (FP + TN)$ when $TN$ is massive), and shows how the validation set is used to select hyperparameters and the optimal probability threshold $p^*$ (e.g., maximizing Recall $\\\\ge 90\\\\%$ at minimal `FPR`), while the untouched test set reports final unbiased generalization logged to MLflow."]}], "critical_failures": ["Fits `StandardScaler` or applies SMOTE/down-sampling to the entire dataset *before* splitting into train, validation, and test sets, causing severe data leakage and artificially inflated metrics.", "Down-samples or balances the holdout **test set** to 50/50, destroying the ability to measure real-world precision and false-positive rates.", "Uses raw classification accuracy or default `0.5` probability thresholds to evaluate a `0.1%` imbalanced classification problem."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'What are the trade-offs between using platforms like Databricks versus containerized deployments with Docker and Kubernetes for large-scale models?', '{"key_points": [{"id": "KP1", "description": "Evaluate Databricks strengths: data-gravity integration (Delta Lake / Unity Catalog), distributed Spark data prep, collaborative MLflow tracking, and rapid batch/training iteration.", "required": true, "acceptable_evidence": ["Technical keywords: Databricks, Apache Spark, Delta Lake, Unity Catalog, managed MLflow, batch scoring, rapid data-scientist velocity.", "Explains that Databricks excels when workloads are tightly coupled to massive tabular/lakehouse datasets in Delta Lake: providing turnkey distributed Spark feature engineering, unified Unity Catalog governance, built-in MLflow tracking, and zero-ops batch/streaming scoring without writing Kubernetes manifests."]}, {"id": "KP2", "description": "Evaluate Docker + Kubernetes (Amazon EKS) strengths: ultra-low-latency (`<100ms`) microservice serving, polyglot runtime control, fine-grained HPA/KEDA/Karpenter scaling, and cost efficiency at scale.", "required": true, "acceptable_evidence": ["Technical keywords: Docker, Amazon EKS, FastAPI / Triton / vLLM, <100ms p99 SLA, Helm + ArgoCD GitOps, KEDA/Karpenter, Spot/GPU node control, zero DBU markup.", "Explains that Docker + EKS provides full control over custom container runtimes (`FastAPI`, `NVIDIA Triton`, `vLLM`, `LangGraph`, `Celery`, `Redis`), sub-100ms online API latency, custom network meshes, GitOps promotion (ArgoCD + Helm), and direct EC2/Spot pricing without paying Databricks DBU (Databricks Unit) surcharges on 24/7 online inference."]}, {"id": "KP3", "description": "Compare operational overhead, vendor lock-in, and the hybrid ''Best-of-Both-Worlds'' enterprise pattern.", "required": true, "acceptable_evidence": ["Technical keywords: DBU cost vs DevOps/SRE overhead, hybrid architecture (Databricks for data/training + MLflow Registry -> Docker/ECR/EKS for online serving).", "Explains the canonical hybrid pattern used in the Study Guides (and Q1704): use Databricks/Spark + DVC for heavy offline data engineering, distributed feature generation, and MLflow model training, then export the registered MLflow artifact into a lean FastAPI Docker container deployed via ArgoCD/Helm onto Amazon EKS for high-concurrency, low-latency online serving."]}], "critical_failures": ["Claims that Databricks cannot train large models or that Kubernetes cannot run GPU workloads.", "Ignores the continuous DBU cost premium of running high-RPS 24/7 microservices on Databricks vs. the SRE maintenance overhead of self-managing Kubernetes.", "Fails to explain how MLflow Model Registry bridges offline Databricks training with online Docker/Kubernetes serving."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'What is the difference between Amazon EKS and ECS, and when would you choose one over the other?', '{"key_points": [{"id": "KP1", "description": "Contrast core architecture and ecosystem: open-standard Kubernetes (`EKS` with Pods, Helm, ArgoCD, CRDs) vs. AWS-proprietary container orchestration (`ECS` with Task Definitions & Services).", "required": true, "acceptable_evidence": ["Technical keywords: Amazon EKS (upstream Kubernetes, Pods, Helm, ArgoCD, KEDA, Karpenter, multi-cloud portability) vs Amazon ECS (AWS-native, Task Definitions, Services, Fargate/EC2).", "Explains that Amazon EKS runs upstream CNCF Kubernetes (enabling cloud-agnostic portability and the full Kubernetes ecosystem: Helm charts, ArgoCD GitOps, KEDA, Karpenter, Istio, Ray/Kubeflow, Prometheus Operator), whereas Amazon ECS is an AWS-proprietary orchestrator tightly integrated with ALB, IAM, and CloudWatch using simpler JSON `Task Definition`s."]}, {"id": "KP2", "description": "Compare operational complexity, control-plane pricing, and networking/scaling mechanics between EKS and ECS.", "required": true, "acceptable_evidence": ["Technical keywords: $0.10/hr EKS control plane fee vs free ECS control plane, Kubernetes version upgrades, CNI/add-on maintenance, GPU scheduling & taints.", "Explains that ECS has zero control-plane fee and lower operational overhead (no Kubernetes version upgrades, `coredns`/`kube-proxy`/CNI add-on management, or CRD maintenance), whereas EKS charges per cluster (`$0.10/hr`) and requires deeper Kubernetes expertise but offers far richer scheduling (taints/tolerations for heterogeneous CPU/GPU node pools, custom metric operators, and StatefulSets for Milvus)."]}, {"id": "KP3", "description": "Define clear decision criteria for choosing Amazon EKS vs. Amazon ECS for AI/ML workloads.", "required": true, "acceptable_evidence": ["Technical keywords: choose EKS for multi-service AI/RAG platforms (Milvus, LangGraph, Celery, vLLM/Triton, Helm/ArgoCD); choose ECS/Fargate for simple stateless AWS-only REST APIs.", "Explains when to choose each: choose **EKS** (as in the Study Guides) when orchestrating complex multi-service AI/ML platforms requiring GPU node sharing, vector databases (Milvus), Helm + ArgoCD GitOps, KEDA queue scaling, and multi-cloud portability; choose **ECS (with Fargate)** when a lean team needs to deploy a few stateless web APIs or batch workers purely on AWS with minimal DevOps overhead."]}], "critical_failures": ["Claims that Amazon ECS runs Kubernetes or supports Helm charts and Kubernetes CRDs natively.", "Claims that AWS Fargate only works with ECS (ignoring that both ECS and EKS support EC2 and Fargate launch types).", "Recommends EKS for a single simple stateless container without acknowledging the Kubernetes control-plane and operational overhead."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'CI/CD & GitOps', 'HARD', 'SPECIFIC', 120, 'What is the difference between canary deployment and blue-green deployment, and when would you use each?', '{"key_points": [{"id": "KP1", "description": "Define Blue-Green Deployment mechanics: provisioning a full parallel duplicate environment (`Green`) alongside `Blue` and switching 100% of traffic atomically after smoke verification.", "required": true, "acceptable_evidence": ["Technical keywords: Blue-Green deployment, 2x duplicate compute capacity, atomic 100% traffic cutover (ALB target group / Service selector swap), instant 100% rollback.", "Explains that Blue-Green maintains two complete, identically sized production environments (`Blue` running `v1`, `Green` running `v2`); `Green` is smoke-tested privately, the load balancer/Service selector switches 100% of live traffic from `Blue` to `Green` at once, and `Blue` stays warm on standby for an instantaneous 100% cutback if an issue arises."]}, {"id": "KP2", "description": "Define Canary Deployment mechanics: progressive incremental traffic shifting (`1% -> 5% -> 25% -> 50% -> 100%`) governed by live SLO and model-metric evaluation.", "required": true, "acceptable_evidence": ["Technical keywords: Canary deployment, progressive traffic shifting, Argo Rollouts / Istio / ALB weighted routing, Prometheus AnalysisRun, limited blast radius.", "Explains that Canary deploys a small number of `v2` pods alongside `v1` and routes a tiny percentage of real production traffic (`1–5%`) to `v2`, automatically evaluating live p99 latency, 5xx errors, prediction score distribution, and RAG Faithfulness over bake windows before incrementally stepping up to 100%."]}, {"id": "KP3", "description": "Compare trade-offs across infrastructure cost (2x GPU/CPU footprint vs. fractional overhead), blast radius (100% vs. 1–5%), and version coexistence.", "required": true, "acceptable_evidence": ["Technical keywords: 2x GPU/memory cost in Blue-Green, 1-5% blast radius in Canary, dual-version schema compatibility.", "Explains the core trade-offs: Blue-Green avoids running two API versions simultaneously on live user traffic and provides atomic cutover, but requires **2x peak compute/GPU capacity** during release and exposes 100% of users if a data-dependent bug slips past synthetic smoke tests; Canary requires only **5–10% extra capacity** and limits blast radius to a tiny cohort while testing on real production edge cases."]}, {"id": "KP4", "description": "Specify when to choose Canary vs. Blue-Green in AI/ML and cloud microservices.", "required": true, "acceptable_evidence": ["Technical keywords: Canary for new MLflow models, prompt/RAG changes, and expensive GPU clusters; Blue-Green for breaking API/config cutovers, EKS cluster upgrades, or Milvus index swaps.", "Explains that **Canary** is preferred for rolling out new MLflow fraud models, LLM prompts, or GPU-backed services (where 2x GPU duplication is prohibitively expensive and real-world input distributions are needed to validate model behavior), whereas **Blue-Green** is preferred for coordinated atomic cutovers (such as swapping a rebuilt Milvus HNSW collection alias, major infrastructure upgrades, or non-backward-compatible internal contracts)."]}], "critical_failures": ["Confuses Canary deployment (gradual percentage traffic shifting on real users) with Blue-Green deployment (two full parallel environments with an atomic 100% traffic switch).", "Recommends Blue-Green deployment for a 100-node GPU cluster without accounting for the cost and quota impossibility of provisioning 100 duplicate GPUs.", "Runs a Canary deployment without automated metric analysis (Prometheus/Evidently AI) or rollback triggers between weight steps."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'EASY', 'SPECIFIC', 60, 'What is the role of a Dockerfile in your deployment process, and what does it typically define?', '{"key_points": [{"id": "KP1", "description": "Define the role of a `Dockerfile` as a declarative blueprint for building an immutable, self-contained container image that guarantees parity from laptop to CI to Amazon EKS.", "required": true, "acceptable_evidence": ["Technical keywords: declarative build recipe, immutable image layers, OS/runtime isolation, parity across dev/staging/prod, Amazon ECR.", "Explains that the `Dockerfile` eliminates ''works on my machine'' drift by codifying the exact OS packages, Python runtime, locked dependencies, and startup command into a layered, content-addressable OCI image pushed to Amazon ECR and deployed identically on Kubernetes."]}, {"id": "KP2", "description": "Identify the core directives defined in a production AI/ML `Dockerfile` (`FROM`, `WORKDIR`, `RUN`, `COPY`, `ENV`, `USER`, `EXPOSE`, `HEALTHCHECK`, `CMD`/`ENTRYPOINT`).", "required": true, "acceptable_evidence": ["Technical keywords: FROM (pinned base image, e.g., python:3.11-slim), WORKDIR, COPY (requirements.txt/poetry.lock before source code), RUN (pip install --no-cache-dir), ENV (PYTHONDONTWRITEBYTECODE, PYTHONUNBUFFERED), USER (non-root), EXPOSE, CMD (uvicorn).", "Explains what each directive specifies and why `COPY requirements.txt` precedes `COPY src/` so Docker layer caching reuses the expensive dependency installation layer whenever only application Python code changes."]}, {"id": "KP3", "description": "Apply multi-stage builds and security hardening (non-root `USER`, `.dockerignore`, no embedded secrets) for lean, secure production images.", "required": true, "acceptable_evidence": ["Technical keywords: multi-stage build (AS builder / AS runtime), non-root UID, .dockerignore, zero hardcoded secrets, reduced attack surface.", "Explains that a multi-stage `Dockerfile` compiles C/C++ extensions (`gcc`, `build-essential`) in a builder stage and copies only the compiled wheels/venv into a minimal runtime stage running as an unprivileged `USER appuser`, slashing image size (for faster EKS pod cold starts) and CVE attack surface."]}], "critical_failures": ["Hardcodes sensitive secrets (`AWS_SECRET_ACCESS_KEY`, database passwords, or `.env` files) inside the `Dockerfile` using `ENV` or `COPY`, baking credentials permanently into image layer history.", "Copies the entire source repository (`COPY . .`) *before* installing `requirements.txt`, invalidating the Docker dependency cache on every single code edit.", "Runs the production container process as `root` (`UID 0`) with an unpinned `:latest` base image."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What is your approach to designing ML pipelines that can scale across different domains such as real-time sensing, robotics, or smart infrastructure?', '{"key_points": [{"id": "KP1", "description": "Decouple domain-specific ingestion/sensor adapters from a reusable core MLOps backbone using Canonical Data Contracts and a Pluggable Feature Store.", "required": true, "acceptable_evidence": ["Technical keywords: hexagonal / ports-and-adapters architecture, canonical event schema (Protobuf / Avro / Pydantic), Kafka / MQTT / Kinesis ingestion, offline Parquet + online Redis Feature Store.", "Explains that scaling across domains (financial transactions, IoT telemetry, robotics ROS2 streams, or smart-grid sensors) requires isolating domain-specific protocol adapters (`MQTT`/`gRPC`/`REST`) at the edge of the pipeline, normalizing streams into versioned canonical schemas (time-stamped entity events), and feeding a shared offline (S3/Parquet) + online (Redis) Feature Store."]}, {"id": "KP2", "description": "Design a Hybrid Edge-Cloud Split Architecture that places deterministic sub-10ms control loops on Edge hardware (`ONNX`/`TensorRT`) and heavy training/orchestration in the Cloud (`EKS`/`MLflow`).", "required": true, "acceptable_evidence": ["Technical keywords: edge-cloud continuum, on-device INT8/FP16 inference (ONNX Runtime / TensorRT), disconnected/intermittent connectivity resilience, cloud fleet training & MLflow Registry.", "Explains that robotics and real-time sensing cannot tolerate cloud round-trip jitter or network dropouts for safety-critical control (`<5–20ms`); the architecture runs quantized `ONNX`/`TensorRT` models locally on edge devices with local ring-buffer fallback, while streaming compressed telemetry and high-uncertainty/drift samples asynchronously to the cloud (S3/DVC + EKS) for fleet-wide retraining."]}, {"id": "KP3", "description": "Standardize model packaging (`MLflow` / `ONNX` / OCI containers) and Over-the-Air (OTA) / GitOps staged fleet rollout with hardware-in-the-loop (HIL) validation.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow Model Registry, ONNX hardware abstraction, Hardware-in-the-Loop (HIL) simulation gate, canary fleet rollout, instant local rollback.", "Explains that models trained in the cloud are exported to portable formats (`ONNX`/`TensorRT`/Docker), validated in CI against domain-specific simulation / HIL benchmarks and latency budgets, and rolled out progressively (`1%` canary devices/nodes -> `100%`) with local watchdog auto-rollback to the previous cached model if sensor errors or latency spike."]}, {"id": "KP4", "description": "Implement federated/edge telemetry aggregation and domain-configurable drift & safety guardrails.", "required": false, "acceptable_evidence": ["Technical keywords: edge histogram aggregation, PSI / KS sensor drift, out-of-distribution (OOD) detection, deterministic safety envelope.", "Explains that edge nodes compute lightweight local feature/prediction histograms (saving bandwidth) to detect sensor calibration drift or out-of-distribution (OOD) environments, while wrapping ML outputs in deterministic physics/rule safety bounds."]}], "critical_failures": ["Builds a monolithic, hardcoded pipeline for each domain from scratch instead of separating pluggable domain adapters/features from the shared training, registry, and deployment platform.", "Routes safety-critical real-time robotics control loops over the public internet to a cloud REST endpoint without accounting for network latency jitter or disconnection.", "Deploys cloud-trained models to heterogeneous edge/IoT hardware without quantization calibration, hardware-in-the-loop (HIL) profiling, or local fallback models."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'SPECIFIC', 120, 'What key metrics did you monitor for business and infrastructure health, and how did you implement dashboards using tools like Grafana and Prometheus?', '{"key_points": [{"id": "KP1", "description": "Define and track Infrastructure & Service Health metrics (RED/USE signals: RPS, `p50/p95/p99` latency, `4xx/5xx` errors, Redis hit rate, Milvus latency, and EKS pod CPU/Memory/GPU saturation).", "required": true, "acceptable_evidence": ["Technical keywords: RED method (Rate, Errors, Duration), USE method (Utilization, Saturation, Errors), histogram_quantile(0.99), <100ms fraud SLA, TTFT, Redis cache hit ratio, Celery queue lag.", "Explains that infrastructure health is tracked via Prometheus counters, gauges, and histograms scraped from FastAPI, Celery, Redis, Milvus, and Kubernetes `kube-state-metrics`/`node-exporter`/`DCGM`: monitoring request rate (RPS), HTTP `4xx/5xx` rates, `p50/p95/p99` latency (`<100ms` for Fraud; TTFT for RAG), Redis cache hit ratios, and pod CPU/RAM/GPU utilization."]}, {"id": "KP2", "description": "Define and track AI Quality & Business Health KPIs (fraud catch rate, `PR-AUC`, `FPR @ 90% Recall`, false-decline rate, RAG Faithfulness, call deflection rate, and USD cost per resolved query).", "required": true, "acceptable_evidence": ["Technical keywords: PR-AUC, FPR @ 90% Recall, fraud flagging rate, analyst override rate, RAG Faithfulness, self-service deflection rate, human escalation rate, token cost per query.", "Explains that technical uptime means nothing if business outcomes fail: the system tracks domain KPIs from the Study Guides—for Fraud Detection: positive prediction rate stability (`~0.1%`), analyst override rate, prevented fraud dollar volume, and realized `PR-AUC` / `FPR @ 90% Recall` (customer friction from false declines); for RAG/Agentic systems: call-center self-service deflection rate, average handle time reduction, thumbs-up/down ratio, sampled Faithfulness, and Bedrock token cost per query."]}, {"id": "KP3", "description": "Instrument custom Prometheus collectors in Python (`prometheus_client`) with bounded labels (`model_version`, `endpoint`, `status`, `tenant_tier`).", "required": true, "acceptable_evidence": ["Technical keywords: prometheus_client, Histogram, Counter, Gauge, ServiceMonitor, bounded label cardinality, model_version label.", "Explains how metrics are exposed in code: FastAPI middleware and model wrappers increment Prometheus `Counter`s (e.g., `fraud_predictions_total{model_version, outcome}`) and observe `Histogram`s (`inference_latency_seconds_bucket{stage}`) scraped by the Prometheus Operator `ServiceMonitor`."]}, {"id": "KP4", "description": "Structure hierarchical, version-controlled Grafana Dashboards (Executive Business view, Service SLO view, and Model/Drift Deep-Dive view) provisioned as code.", "required": true, "acceptable_evidence": ["Technical keywords: Grafana Dashboard-as-Code (JSON in Git / Helm ConfigMap), template variables ($env, $model_version), SLO burn-rate panels, Alertmanager integration.", "Explains that Grafana dashboards are organized into three linked tiers with template variables (`$env`, `$model_version`, `$service`) and versioned as JSON in Git/Helm so they deploy reproducibly alongside the application and fire alerts through Alertmanager when business or infra thresholds breach."]}], "critical_failures": ["Tracks only CPU, memory, and HTTP 200 status codes on Grafana dashboards with zero visibility into business outcomes, model prediction distributions, or token costs.", "Builds Grafana dashboards manually via browser clicks without exporting/versioning the dashboard JSON in Git/IaC.", "Uses `Avg` (mean) latency panels instead of `histogram_quantile(0.95/0.99, ...)` in PromQL, masking tail latency breaches."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'SPECIFIC', 90, 'What machine learning algorithms have you implemented, and how did you choose the best-performing model for deployment?', '{"key_points": [{"id": "KP1", "description": "Detail the progression of implemented algorithms from interpretable linear baselines (`LogisticRegression` with L2 Ridge regularization) to non-linear ensembles (`RandomForest`, `XGBoost`/`LightGBM`) and neural/Transformer models (`DeBERTa`, `BGE`, LLMs).", "required": true, "acceptable_evidence": ["Technical keywords: Phase 1 LogisticRegression (L2 regularization C, StandardScaler), Phase 2 XGBoost / LightGBM, Random Forest, BGE Bi-Encoder & Cross-Encoder, AWS Bedrock LLMs.", "Explains the iterative modeling progression from the Fraud Detection and RAG Study Guides: starting with a fast, calibrated Phase 1 `StandardScaler` + L2 `LogisticRegression` baseline (`GridSearchCV` over `C` with `class_weight=''balanced''`) to verify feature pipelines and establish a benchmark, then advancing to Phase 2 gradient-boosted decision trees (`XGBoost` tuning `max_depth`, `learning_rate`, `subsample`, `colsample_bytree`, `scale_pos_weight`) to capture complex non-linear feature interactions (e.g., high amount + new device + foreign IP)."]}, {"id": "KP2", "description": "Evaluate candidates on domain-aligned offline metrics (`PR-AUC`, `FPR @ 90% Recall`, calibration) across chronological out-of-time validation splits logged in MLflow.", "required": true, "acceptable_evidence": ["Technical keywords: PR-AUC, FPR @ 90% Recall, chronological validation split, MLflow experiment comparison, subgroup slice stability.", "Explains that candidate algorithms are compared in MLflow on chronological out-of-time validation/test splits using `PR-AUC` and `FPR @ 90% Recall` (where `XGBoost` significantly reduced false declines compared to `LogisticRegression` at the 90% fraud recall target)."]}, {"id": "KP3", "description": "Balance predictive accuracy against production operational constraints (`<100ms` p99 latency, memory footprint, and `TreeSHAP` explainability) when selecting the final deployment model.", "required": true, "acceptable_evidence": ["Technical keywords: multi-criteria model selection, <100ms p99 inference SLA, TreeSHAP top-3 feature explanations, regulatory auditability, CPU vs GPU cost.", "Explains why `XGBoost` + `TreeSHAP` was chosen for production deployment over heavy deep tabular neural networks: `XGBoost` delivered superior `PR-AUC` on tabular velocity features, executed in `<15ms` on commodity CPU pods (easily meeting the `<100ms` end-to-end SLA without expensive GPUs), and supported exact polynomial-time `TreeSHAP` attributions to return the top 3 feature explanations required by fraud analysts and regulators."]}], "critical_failures": ["Jumps straight to a complex deep neural network or massive ensemble without first building and benchmarking a simple, interpretable baseline (`LogisticRegression`).", "Selects a model for production based solely on a `0.001` offline metric gain while ignoring that it violates the `<100ms` latency SLA or lacks required explainability.", "Chooses the ''best'' model by tuning hyperparameters directly on the final holdout test set."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Containers & Orchestration', 'MEDIUM', 'SPECIFIC', 90, 'Why did you choose EKS for deployment, and how does it compare to other Kubernetes options like AKS or managed services?', '{"key_points": [{"id": "KP1", "description": "Explain the data-and-service gravity rationale for choosing Amazon EKS when the surrounding AI stack resides on AWS (`Bedrock`, `S3`, `RDS`, `ElastiCache Redis`, `ECR`, `IAM/IRSA`).", "required": true, "acceptable_evidence": ["Technical keywords: AWS data gravity, VPC PrivateLink integration, AWS Bedrock, S3, ElastiCache Redis, RDS, IRSA / Pod Identity, zero cross-cloud egress fees.", "Explains from the Study Guides that because the core data and AI dependencies—Amazon S3 (DVC datasets & MLflow artifacts), AWS Bedrock (Claude Sonnet/Haiku), ElastiCache Redis (online Feature Store & semantic cache), and RDS PostgreSQL—run in AWS, deploying compute on Amazon EKS inside the same VPC eliminates cross-cloud network latency (`<1–2ms` intra-VPC) and avoids expensive cross-cloud data egress fees while leveraging native IAM Roles for Service Accounts (IRSA)."]}, {"id": "KP2", "description": "Compare Amazon EKS against Azure AKS and Google GKE across control-plane management, cloud-native AI ecosystem integration, and portability.", "required": true, "acceptable_evidence": ["Technical keywords: EKS vs AKS vs GKE, upstream CNCF Kubernetes parity, Helm/ArgoCD portability, AWS VPC CNI & Karpenter vs GKE Autopilot vs AKS Azure CNI.", "Explains that while EKS, AKS, and GKE all run conformant upstream Kubernetes (so our Helm charts and ArgoCD manifests are 95%+ portable across all three), GKE offers strong automated cluster autopilot/upgrades and Vertex AI integration, AKS offers free basic control planes and tight Azure OpenAI / Entra ID integration, and EKS excels at deep AWS networking (`aws-vpc-cni` assigning native VPC IPs to pods), `Karpenter` fast node provisioning, and seamless integration with AWS Bedrock and SageMaker."]}, {"id": "KP3", "description": "Compare Amazon EKS against higher-level serverless managed services (`AWS App Runner`, `ECS Fargate`, `AWS Lambda`, `SageMaker Endpoints`).", "required": true, "acceptable_evidence": ["Technical keywords: EKS vs ECS Fargate / App Runner / Lambda, 15-min Lambda timeout & cold starts, stateful/long-lived SSE connections, GPU instance sharing, Milvus & Celery co-location.", "Explains why EKS was chosen over simpler serverless options: AWS Lambda has cold-start penalties, memory limits, and 15-minute timeouts unsuitable for pre-loaded ML models or long-running agent loops; App Runner / Fargate lack fine-grained GPU node slicing (`g5`/`g6`), DaemonSet observability, and high-performance co-location of FastAPI, Celery workers, BGE rerankers, and Milvus vector clusters under unified Helm + ArgoCD GitOps governance."]}], "critical_failures": ["Suggests running the Kubernetes compute cluster on Azure AKS while keeping the online Redis Feature Store, S3 buckets, and Bedrock calls in AWS, introducing tens of milliseconds of cross-cloud WAN latency and massive egress bills.", "Claims that Kubernetes YAML/Helm charts written for EKS cannot be adapted to AKS or GKE.", "Overlooks the operational trade-off that EKS requires managing cluster upgrades, VPC CNI networking, and add-ons compared to serverless platforms."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'SPECIFIC', 90, 'At what stage of the ML lifecycle do you perform evaluation, and how do you structure train-test-validation splits?', '{"key_points": [{"id": "KP1", "description": "Perform evaluation continuously across four distinct stages of the ML lifecycle rather than as a single post-training step.", "required": true, "acceptable_evidence": ["Technical keywords: (1) Pre-training data/feature evaluation, (2) Offline training/validation tuning, (3) Pre-deployment CI/CD Champion-Challenger gate, (4) Post-deployment online monitoring (A/B, shadow, drift & delayed-label eval).", "Explains that evaluation spans the entire lifecycle: (1) **Data & Feature Stage** (schema validation, label-maturity verification, feature-target mutual information), (2) **Model Development Stage** (cross-validation, hyperparameter tuning, error slice & TreeSHAP analysis), (3) **Pre-Deployment Gate in MLflow/CI** (unbiased holdout test comparison vs. the Production champion, subgroup fairness, and `<100ms` latency tests), and (4) **Production Stage** (shadow/canary testing, Evidently AI feature/prediction drift, and delayed ground-truth `PR-AUC` evaluation)."]}, {"id": "KP2", "description": "Define the strict separation of responsibilities between the Training, Validation, and Holdout Test splits.", "required": true, "acceptable_evidence": ["Technical keywords: Training set (weight/parameter fitting), Validation set (hyperparameter tuning, feature selection, probability threshold calibration), Test set (locked single-use final generalization estimate).", "Explains that the **Training set** fits model weights and `StandardScaler` parameters; the **Validation set** guides iterative decisions (selecting `XGBoost` vs. `LogisticRegression`, tuning hyperparameters, early stopping, and picking the probability threshold for `FPR @ 90% Recall`); and the **Holdout Test set** remains completely untouched until final pre-production certification so adaptive overfitting to the validation set is caught."]}, {"id": "KP3", "description": "Structure splits using Out-of-Time Chronological partitioning (with purge/maturity gaps) for temporal data and Entity-Grouped Stratification for non-temporal data.", "required": true, "acceptable_evidence": ["Technical keywords: chronological split (e.g., Jan-Feb train, Mar validation, Apr test), TimeSeriesSplit (expanding/sliding window), entity grouping (GroupKFold by user_id), label-maturity purge buffer.", "Explains from the Fraud Detection Study Guide that temporal datasets use strict chronological splits (`T_train < T_val < T_test`, or expanding-window `TimeSeriesSplit`) with a purge buffer for delayed chargeback labels, ensuring the model is evaluated on its ability to generalize to future unseen time periods and preventing the same transaction burst or future user velocity from leaking across splits."]}], "critical_failures": ["Evaluates the model only once during offline training and never validates pre-deployment latency/fairness or post-deployment production drift.", "Iteratively tunes hyperparameters and decision thresholds directly on the final Test set, leaking test information and invalidating the generalization estimate.", "Uses a random shuffle split on time-series fraud or log data, allowing future events to train a model predicting past events."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe your experience as a machine learning engineer and how it differs from a research-focused role?', '{"key_points": [{"id": "KP1", "description": "Contrast primary objectives: novel algorithmic/benchmark breakthroughs on static datasets (Research) vs. reliable, end-to-end production systems solving business problems under strict SLAs (ML Engineering).", "required": true, "acceptable_evidence": ["Technical keywords: Problem-First approach (AI Builder''s Handbook), static benchmark SOTA vs production SLA (<100ms latency, 99.9% uptime, cost-per-query, business ROI).", "Explains that while a Research role focuses on inventing novel neural architectures or maximizing offline accuracy on clean static benchmarks (like ImageNet/MMLU) regardless of compute cost, an ML Engineer takes a Problem-First systems approach: owning the full lifecycle from messy real-world data (delayed fraud labels, unstructured PDFs) to a reliable, cost-effective production service meeting `<100ms` latency SLAs and measurable business KPIs (`FPR @ 90% Recall`, call deflection rate)."]}, {"id": "KP2", "description": "Highlight core ML Engineering ownership across Feature Stores, CI/CD (CC/CD), Containerization (`Docker`/`EKS`/`Helm`/`ArgoCD`), Guardrails, and Drift Observability.", "required": true, "acceptable_evidence": ["Technical keywords: training-serving skew prevention, Feature Store (S3/Redis), MLflow Registry, FastAPI, Docker/EKS/ArgoCD, NeMo Guardrails, Presidio, Prometheus/Grafana/Langfuse/Evidently AI.", "Explains concrete engineering responsibilities that go far beyond model training: eliminating training-serving skew via shared Feature Stores, building stateless FastAPI microservices, automating CI/CD evaluation gates (DeepEval/RAGAS), deploying with Docker/Helm/ArgoCD on Amazon EKS, enforcing PII/safety guardrails, and monitoring production drift and tail latency."]}, {"id": "KP3", "description": "Demonstrate pragmatic engineering trade-offs (choosing a simpler, explainable, fast model over a marginal, brittle accuracy gain).", "required": true, "acceptable_evidence": ["Technical keywords: simplicity-first (LogisticRegression -> XGBoost + TreeSHAP), tiered model routing (Haiku vs Sonnet), explainability, maintainability.", "Provides concrete examples of production engineering judgment from the Study Guides: choosing `XGBoost` + `TreeSHAP` over a heavy black-box deep network to guarantee `<100ms` CPU inference and regulatory explainability, or routing simple intents to cached/small models rather than calling a frontier LLM on every request."]}], "critical_failures": ["Describes ML Engineering purely as running `model.fit()` in Jupyter notebooks on pre-cleaned CSV files with zero mention of deployment, latency SLAs, CI/CD, or production monitoring.", "Dismisses scientific rigor and evaluation metrics, claiming ML Engineers only write YAML files and don''t need to understand model mathematics, data leakage, or statistical validation.", "Optimizes exclusively for complex model architectures when a simpler baseline or deterministic rule solves the business problem at 10x lower cost and latency."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'Generative AI & LLMs', 'MEDIUM', 'SPECIFIC', 90, 'Can you describe your experience transitioning from classical machine learning models, such as regression, to building Generative AI applications?', '{"key_points": [{"id": "KP1", "description": "Explain which foundational MLOps & statistical principles transferred directly from classical ML to Generative AI (rigorous evaluation splits, baseline-first iteration, reproducibility, and drift monitoring).", "required": true, "acceptable_evidence": ["Technical keywords: transferable fundamentals, leakage-free Golden Datasets, baseline-first engineering, CI/CD quality gates, Docker/EKS/ArgoCD deployment, latency/cost SLOs.", "Explains that core disciplines built on classical ML systems (like the Fraud Detection `LogisticRegression` -> `XGBoost` pipeline)—such as preventing data leakage in evaluation splits, versioning artifacts, enforcing automated CI regression gates, and monitoring p99 latency/drift on EKS—provided a strong foundation that prevented ''vibe-check'' anti-patterns when building GenAI systems."]}, {"id": "KP2", "description": "Detail the paradigm shifts mastered when moving to GenAI: from structured tabular feature engineering to Context Engineering, Hybrid RAG (`Docling`, `Milvus`, `BM25`, `BGE` Reranking), and Agentic orchestration (`LangGraph`, `MCP`).", "required": true, "acceptable_evidence": ["Technical keywords: tabular feature engineering vs Context Engineering, Docling PDF parsing, Hybrid RAG (BM25 + Milvus HNSW + RRF + BGE Cross-Encoder), LangGraph stateful graphs, MCP tool calling, Structured Outputs (Pydantic).", "Explains the key technical shift: instead of training weights from scratch on tabular numerical columns, GenAI engineering focuses on orchestrating foundation models (AWS Bedrock Claude Sonnet/Haiku) via high-signal Context Engineering, hybrid retrieval pipelines, deterministic Pydantic Structured Outputs, and governed LangGraph/MCP tool loops."]}, {"id": "KP3", "description": "Detail the shift in Evaluation, Safety, and Serving mechanics (reference-free LLM judges, `Faithfulness`, `NeMo Guardrails`/`Presidio`, `SSE` streaming, and multi-layer semantic caching).", "required": true, "acceptable_evidence": ["Technical keywords: PR-AUC/RMSE vs RAGAS/DeepEval (Faithfulness, Recall@K), NeMo Guardrails, Presidio PII redaction, prompt injection defense, SSE token streaming, multi-layer Redis semantic cache, Langfuse tracing.", "Explains how evaluation and operations evolved: replacing single scalar metrics (`PR-AUC`/`RMSE`) with decomposed retrieval + generation evaluation (`Recall@K`, `MRR`, `Faithfulness`), layering deterministic input/output safety guardrails (`Presidio`, `NeMo Guardrails`), streaming responses via SSE, and instrumenting span-level traces and token costs in Langfuse."]}, {"id": "KP4", "description": "Apply hybrid architectural judgment to combine classical ML / deterministic encoders with Generative AI where each excels.", "required": false, "acceptable_evidence": ["Technical keywords: right tool for the job, hybrid ML + GenAI systems, XGBoost/DeBERTa for fast classification/scoring + LLM for synthesis/explanation.", "Explains that transitioning to GenAI does not mean abandoning classical ML: production systems combine fast classical/encoder models (`XGBoost` for `<20ms` fraud scoring, `BGE`/`DeBERTa` for routing and reranking) with LLMs for natural-language reasoning and synthesis."]}], "critical_failures": ["Treats Generative AI as a hammer for every problem, replacing fast `<10ms` tabular `XGBoost`/regression models with slow, expensive LLM prompts on structured numerical data.", "Abandons quantitative evaluation and version control when building GenAI apps, relying on manual prompt tweaking without a Golden Dataset or `DeepEval`/`RAGAS` metrics.", "Ignores GenAI-specific risks such as hallucinations, prompt injection, unbounded token costs, and TTFT streaming latency."]}', 1);
